/* -------------------------------------------------------------------
 *  Tap-active-tab to refresh — when the user taps the tab they're
 *  already on, the route's data layer re-fetches and the tab icon
 *  spins once so they get a visible confirmation. CSS only handles
 *  the spin animation; the JS toggles `.isRefreshing`. The animation
 *  duration matches the floor in `triggerTabRefresh()` (520ms) so a
 *  too-fast network refresh still completes a visible rotation.
 * ----------------------------------------------------------------- */
.mobileTabbar a.isRefreshing .tabIco{
  animation: tabRefreshSpin 0.85s cubic-bezier(0.4, 0, 0.2, 1) infinite;
  transform-origin: 50% 50%;
}
/* Create tab icon is absolutely centered — keep translate in the spin keyframes. */
.mobileTabbar a.tabCreate.isRefreshing .tabIco{
  animation: tabCreateRefreshSpin 0.85s cubic-bezier(0.4, 0, 0.2, 1) infinite;
  transform-origin: center center;
}
@keyframes tabRefreshSpin{
  0%   { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}
@keyframes tabCreateRefreshSpin{
  0%   { transform: translate(-50%, -50%) rotate(0deg); }
  100% { transform: translate(-50%, -50%) rotate(360deg); }
}
@media (prefers-reduced-motion: reduce){
  .mobileTabbar a.isRefreshing .tabIco{
    animation: none;
    opacity: 0.6;
  }
  .mobileTabbar a.tabCreate.isRefreshing .tabIco{
    transform: translate(-50%, -50%);
  }
}

/* Pull-to-refresh — content moves with finger; spinner rides on content */
.ptrMovable{
  --ptr-offset: 0px;
  --ptr-rotate: 0deg;
  position: relative;
  transform: translate3d(0, var(--ptr-offset), 0);
  will-change: transform;
  backface-visibility: hidden;
}
.ptrMovable.isPtrSnapping{
  transition: transform 0.38s cubic-bezier(0.22, 1, 0.36, 1);
}
.ptrSpinnerAnchor{
  position: absolute;
  left: 50%;
  top: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 32px;
  height: 32px;
  margin-left: -16px;
  transform: translate3d(0, calc(var(--ptr-offset) * -0.82 - 6px), 0);
  pointer-events: none;
  opacity: 0;
  transition: opacity 0.16s ease;
}
.ptrMovable.isPtrPulling .ptrSpinnerAnchor,
.ptrMovable.isPtrRefreshing .ptrSpinnerAnchor{
  opacity: 1;
}
.ptrSpinnerRing{
  display: block;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  box-sizing: border-box;
  border: 2.5px solid rgba(255, 255, 255, 0.2);
  border-top-color: rgba(255, 255, 255, 0.94);
  transform: rotate(var(--ptr-rotate, 0deg));
  transform-origin: 50% 50%;
  will-change: transform;
}
.ptrMovable.isPtrReady:not(.isPtrRefreshing) .ptrSpinnerRing{
  border-top-color: rgba(124, 92, 255, 0.96);
}
.ptrMovable.isPtrRefreshing .ptrSpinnerRing{
  animation: ptrRingSpin 0.75s linear infinite;
}
/* Profile: fixed below notch, tracks pull so it stays above the avatar */
.ptrMovable--profile.isPtrPulling .ptrSpinnerAnchor,
.ptrMovable--profile.isPtrRefreshing .ptrSpinnerAnchor{
  position: fixed;
  top: calc(env(safe-area-inset-top, 0px) + 12px + var(--ptr-offset, 0px) * 0.18);
  left: 50%;
  margin-left: -16px;
  transform: none;
  z-index: 55;
}
@media (max-width: 720px){
  .ptrMovable--profile.isPtrPulling .ptrSpinnerAnchor,
  .ptrMovable--profile.isPtrRefreshing .ptrSpinnerAnchor{
    top: calc(env(safe-area-inset-top, 0px) + 10px + var(--ptr-offset, 0px) * 0.15);
  }
}
@keyframes ptrRingSpin{
  from{ transform: rotate(0deg); }
  to{ transform: rotate(360deg); }
}
@media (prefers-reduced-motion: reduce){
  .ptrMovable.isPtrSnapping{
    transition-duration: 0.01ms;
  }
  .ptrMovable.isPtrRefreshing .ptrSpinnerRing{
    animation: none;
  }
}

