/* ---- Onboarding feature slides ------------------------------------- */

.onboardingScreen{
  padding: 0;
  min-height: 0;
  height: 100%;
  border: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
}
.onboardingInner{
  position: relative;
  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;
  min-height: 0;
  padding: env(safe-area-inset-top, 0) 20px calc(20px + env(safe-area-inset-bottom, 0));
  box-sizing: border-box;
}
.onboardingSkip{
  position: absolute;
  top: max(12px, env(safe-area-inset-top, 0));
  right: 16px;
  z-index: 2;
  border: none;
  background: transparent;
  color: rgba(223, 231, 251, 0.48);
  font-size: 14px;
  font-weight: 600;
  padding: 8px 10px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.onboardingSkip:hover{ color: rgba(255,255,255,0.82); }
.onboardingSlides{
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
}
.onboardingSlide{
  display: none;
  flex-direction: column;
  align-items: center;
  text-align: center;
  width: 100%;
  max-width: 360px;
  gap: 18px;
  animation: onboardingFadeIn 320ms ease;
}
.onboardingSlide.is-active{
  display: flex;
}
@keyframes onboardingFadeIn{
  from{ opacity: 0; transform: translateY(8px); }
  to{ opacity: 1; transform: translateY(0); }
}
@media (prefers-reduced-motion: reduce){
  .onboardingSlide.is-active{ animation: none; }
}
.onboardingTitle{
  margin: 0;
