  letter-spacing: -0.03em;
  color: #f2f6ff;
}
.onboardingLead{
  margin: 0;
  font-size: 15px;
  line-height: 1.48;
  color: rgba(223, 231, 251, 0.58);
  max-width: 320px;
}
.onboardingFooter{
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  padding-top: 8px;
}
.onboardingDots{
  display: inline-flex;
  gap: 8px;
  align-items: center;
}
.onboardingDot{
  width: 7px;
  height: 7px;
  padding: 0;
  border: none;
  border-radius: 999px;
  background: rgba(223, 231, 251, 0.22);
