  transition: width 200ms ease, background 200ms ease;
}
.onboardingDot.is-active{
  width: 22px;
  background: rgba(255,255,255,0.88);
}
.onboardingPrimaryBtn{
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  max-width: 340px;
  height: 52px;
  padding: 0 24px;
  border: none;
  border-radius: 999px;
  background: #fff;
  color: #0b1320;
  font-size: 16px;
  font-weight: 800;
  text-align: center;
  cursor: pointer;
  box-shadow: 0 14px 36px -12px rgba(255,255,255,0.32);
  transition: transform 120ms ease;
  -webkit-tap-highlight-color: transparent;
  appearance: none;
}
.onboardingPrimaryBtn:active{ transform: scale(0.98); }

/* Slide mocks */
.onboardingMock{
