}
.onboardingMoodChip--happy.is-on{
  animation: onboardingMoodPulse 2s ease-in-out infinite;
}
@keyframes onboardingMoodPulse{
  0%, 100%{ box-shadow: 0 8px 22px -8px rgba(251,191,36,0.35); }
  50%{ box-shadow: 0 10px 28px -6px rgba(251,191,36,0.55); }
}
.onboardingMock--echo{
  display: flex;
  justify-content: center;
  padding: 20px 0;
}
.onboardingMock--mashup{
  display: flex;
  justify-content: center;
  padding: 20px 0;
}
.onboardingMashupTileWrap{
  width: 108px;
  height: 108px;
}
.onboardingMashupTileWrap .homeDeskMashupTile{
  width: 108px;
  height: 108px;
}
.onboardingMashupTileWrap .homeDeskMashupDisc{
  width: 48px;
  height: 48px;
}
.onboardingEchoTileWrap{
  position: relative;
  width: 108px;
  height: 108px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.onboardingEchoPulse{
  position: absolute;
  inset: -14px;
  border-radius: 30px;
  border: 2px solid rgba(168,85,247,0.45);
  animation: onboardingEchoPulse 2.4s ease-out infinite;
  pointer-events: none;
}
@keyframes onboardingEchoPulse{
  0%{ transform: scale(0.92); opacity: 0.75; }
  70%{ transform: scale(1.18); opacity: 0; }
  100%{ transform: scale(1.18); opacity: 0; }
}
.onboardingEchoTile{
  position: relative;
  width: 108px;
  height: 108px;
  border-radius: 22px;
  padding: 3px;
