}
.onboardingEchoWave i:nth-child(1){ height: 14px; animation-delay: 0s; }
.onboardingEchoWave i:nth-child(2){ height: 28px; animation-delay: 0.12s; }
.onboardingEchoWave i:nth-child(3){ height: 20px; animation-delay: 0.24s; }
.onboardingEchoWave i:nth-child(4){ height: 32px; animation-delay: 0.08s; }
.onboardingEchoWave i:nth-child(5){ height: 16px; animation-delay: 0.18s; }
@keyframes onboardingWave{
  0%, 100%{ transform: scaleY(0.55); opacity: 0.5; }
  50%{ transform: scaleY(1); opacity: 1; }
}
.onboardingMock--friends{
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 14px;
  border-radius: 18px;
  background:
    radial-gradient(100% 80% at 100% 0%, rgba(124,92,255,0.10), transparent 55%),
    rgba(255,255,255,0.03);
  border: 1px solid rgba(255,255,255,0.07);
}
.onboardingFriendRow{
  display: flex;
  align-items: center;
  gap: 10px;
  opacity: 0;
  transform: translateY(10px);
}
.onboardingSlide.is-active .onboardingFriendRow{
  animation: onboardingFriendIn 420ms ease forwards;
}
.onboardingSlide.is-active .onboardingFriendRow:nth-child(1){ animation-delay: 0.05s; }
.onboardingSlide.is-active .onboardingFriendRow:nth-child(2){ animation-delay: 0.14s; }
.onboardingSlide.is-active .onboardingFriendRow:nth-child(3){ animation-delay: 0.23s; }
@keyframes onboardingFriendIn{
  to{ opacity: 1; transform: translateY(0); }
}
.onboardingFriendAv{
  width: 36px;
  height: 36px;
  border-radius: 12px;
  flex: 0 0 auto;
  box-shadow: 0 8px 18px -10px rgba(0,0,0,0.5);
}
.onboardingFriendAv--purple{
  background: linear-gradient(145deg, #7c5cff 0%, #4c2fd4 100%);
}
.onboardingFriendAv--teal{
  background: linear-gradient(145deg, #23d5ab 0%, #0e9a82 100%);
}
.onboardingFriendAv--pink{
  background: linear-gradient(145deg, #ff6b9d 0%, #c0266a 100%);
}
.onboardingFriendBody{
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.onboardingFriendBadge{
  align-self: flex-start;
  padding: 3px 7px;
  border-radius: 6px;
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
.onboardingFriendBadge--echo{
  color: #e9c4ff;
  background: rgba(168,85,247,0.22);
  border: 1px solid rgba(168,85,247,0.35);
}
.onboardingFriendBadge--drop{
  color: #8ef5e0;
  background: rgba(35,213,171,0.18);
  border: 1px solid rgba(35,213,171,0.32);
}
.onboardingFriendLine{
  display: block;
  width: 100%;
  height: 10px;
  border-radius: 6px;
  background: rgba(255,255,255,0.10);
}
.onboardingFriendLine--short{ max-width: 62%; }
.onboardingMock--persona{
  display: flex;
  justify-content: center;
  padding: 8px 0 16px;
}
.onboardingPersonaScene{
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
  padding: 24px 32px 20px;
  border-radius: 24px;
  background:
    radial-gradient(90% 70% at 50% 0%, rgba(124,92,255,0.22), transparent 62%),
    radial-gradient(70% 50% at 50% 100%, rgba(35,213,171,0.12), transparent 55%),
    rgba(124,92,255,0.10);
  border: 1px solid rgba(124,92,255,0.28);
  min-width: 200px;
}
.onboardingPersonaWaves{
  position: absolute;
  top: 28px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 5px;
  width: 120px;
  height: 40px;
  pointer-events: none;
}
.onboardingPersonaWaves i{
  display: block;
  width: 3px;
  border-radius: 4px;
  background: linear-gradient(180deg, rgba(124,92,255,0.85), rgba(35,213,171,0.75));
  animation: onboardingPersonaWave 1.3s ease-in-out infinite;
}
.onboardingPersonaWaves i:nth-child(1){ height: 10px; animation-delay: 0s; }
.onboardingPersonaWaves i:nth-child(2){ height: 22px; animation-delay: 0.1s; }
.onboardingPersonaWaves i:nth-child(3){ height: 32px; animation-delay: 0.2s; }
.onboardingPersonaWaves i:nth-child(4){ height: 22px; animation-delay: 0.1s; }
.onboardingPersonaWaves i:nth-child(5){ height: 10px; animation-delay: 0s; }
@keyframes onboardingPersonaWave{
  0%, 100%{ transform: scaleY(0.5); opacity: 0.45; }
  50%{ transform: scaleY(1); opacity: 1; }
}
.onboardingPersonaSilhouette{
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 88px;
  padding-top: 8px;
}
.onboardingPersonaHead{
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: linear-gradient(180deg, rgba(255,255,255,0.92) 0%, rgba(180,190,220,0.75) 100%);
  box-shadow: 0 10px 24px -12px rgba(0,0,0,0.55);
}
.onboardingPersonaShoulders{
  width: 76px;
  height: 38px;
  margin-top: -6px;
  border-radius: 38px 38px 0 0;
  background: linear-gradient(180deg, rgba(255,255,255,0.88) 0%, rgba(160,170,205,0.70) 100%);
  box-shadow: 0 12px 28px -14px rgba(0,0,0,0.5);
}
.onboardingPersonaLabel{
  font-size: 13px;
  font-weight: 700;
  color: rgba(232,238,255,0.82);
  letter-spacing: 0.04em;
  text-transform: uppercase;
}
.onboardingMock--coach{
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 16px 14px 18px;
  border-radius: 20px;
  background:
    radial-gradient(100% 80% at 0% 0%, rgba(54,231,192,0.12), transparent 55%),
    radial-gradient(90% 70% at 100% 100%, rgba(106,35,218,0.14), transparent 50%),
    rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.08);
  min-height: 168px;
}
.onboardingCoachChat{
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.onboardingCoachBubble{
  max-width: 92%;
  padding: 10px 12px;
  border-radius: 16px;
  font-size: 11px;
  font-weight: 560;
  line-height: 1.45;
  letter-spacing: -0.01em;
}
.onboardingCoachBubble--user{
  align-self: flex-end;
  color: rgba(248,250,255,0.92);
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.1);
  border-bottom-right-radius: 6px;
}
.onboardingCoachRow{
  display: flex;
  align-items: flex-end;
  gap: 8px;
}
.onboardingCoachOrbMini{
  flex: 0 0 auto;
  width: 28px;
  height: 28px;
  border-radius: 50%;
  overflow: hidden;
  box-shadow: 0 0 16px rgba(54,231,192,0.28);
}
.onboardingCoachOrbMini svg{
  display: block;
  width: 100%;
  height: 100%;
}
.onboardingCoachBubble--coach{
  flex: 1 1 auto;
  color: rgba(223,231,251,0.88);
  background:
    linear-gradient(135deg, rgba(54,231,192,0.12) 0%, rgba(63,115,240,0.14) 52%, rgba(106,35,218,0.12) 100%);
  border: 1px solid rgba(94,234,212,0.22);
  border-bottom-left-radius: 6px;
}
.onboardingCoachFabMock{
  position: absolute;
  right: 10px;
  bottom: 10px;
  display: flex;
  align-items: center;
  gap: 8px;
  pointer-events: none;
}
.onboardingCoachFabPill{
  padding: 7px 11px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: rgba(248,250,255,0.92);
  background: rgba(12,18,32,0.92);
  border: 1px solid rgba(94,234,212,0.28);
  box-shadow: 0 8px 24px -10px rgba(54,231,192,0.45);
  white-space: nowrap;
}
.onboardingCoachFabOrb{
  display: block;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  overflow: hidden;
  box-shadow:
    0 0 0 2px rgba(22,38,79,0.85),
    0 10px 28px -8px rgba(54,231,192,0.45);
  animation: onboardingCoachOrbPulse 2.8s ease-in-out infinite;
}
.onboardingCoachFabOrb svg{
  display: block;
  width: 100%;
  height: 100%;
}
@keyframes onboardingCoachOrbPulse{
  0%, 100%{ transform: scale(1); box-shadow: 0 0 0 2px rgba(22,38,79,0.85), 0 10px 28px -8px rgba(54,231,192,0.35); }
  50%{ transform: scale(1.05); box-shadow: 0 0 0 2px rgba(22,38,79,0.85), 0 12px 32px -6px rgba(54,231,192,0.55); }
}
.onboardingSlide.is-active .onboardingCoachBubble--user{
  animation: onboardingCoachBubbleIn 420ms ease forwards;
}
.onboardingSlide.is-active .onboardingCoachRow{
  animation: onboardingCoachBubbleIn 420ms ease 0.12s forwards;
  opacity: 0;
}
.onboardingSlide.is-active .onboardingCoachFabMock{
  animation: onboardingCoachBubbleIn 480ms ease 0.28s forwards;
  opacity: 0;
}
@keyframes onboardingCoachBubbleIn{
  from{ opacity: 0; transform: translateY(8px); }
  to{ opacity: 1; transform: translateY(0); }
}
@media (prefers-reduced-motion: reduce){
  .onboardingMockFieldGlow,
  .onboardingMockFieldLine,
  .onboardingMoodChip--happy.is-on,
  .onboardingEchoPulse,
  .onboardingEchoWave i,
  .onboardingPersonaWaves i,
  .onboardingSlide.is-active .onboardingFriendRow,
  .onboardingCoachFabOrb,
  .onboardingSlide.is-active .onboardingCoachRow,
  .onboardingSlide.is-active .onboardingCoachFabMock{
    animation: none !important;
  }
  .onboardingFriendRow{ opacity: 1; transform: none; }
  .onboardingSlide.is-active .onboardingCoachRow,
  .onboardingSlide.is-active .onboardingCoachFabMock{ opacity: 1; transform: none; }
  .onboardingMoodChip.is-on{ transform: none; }
}

