.rightsCheck{
  display: flex;
  align-items: flex-start;
  gap: 8px;
  margin: 18px 0 0;
  font-size: 11px;
  font-weight: 400;
  line-height: 1.5;
  letter-spacing: 0.01em;
  color: rgba(223, 231, 251, 0.36);
  cursor: pointer;
  user-select: none;
}
.rightsCheck > span{
  flex: 1;
  min-width: 0;
  font-weight: 400;
}
.rightsCheck input[type="checkbox"]{
  appearance: none;
  -webkit-appearance: none;
  width: 13px;
  height: 13px;
  margin: 0.18em 0 0;
  flex: 0 0 13px;
  border: 1px solid rgba(223, 231, 251, 0.24);
  border-radius: 3px;
  background: transparent;
  cursor: pointer;
  position: relative;
  vertical-align: top;
}
.rightsCheck input[type="checkbox"]:checked{
  border-color: rgba(124, 92, 255, 0.55);
  background: rgba(124, 92, 255, 0.16);
}
.rightsCheck input[type="checkbox"]:checked::after{
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: 3px;
  height: 6px;
  border: solid rgba(255,255,255,0.88);
  border-width: 0 1.5px 1.5px 0;
  transform: translate(-50%, -58%) rotate(45deg);
}
.rightsCheck a{
  color: rgba(223, 231, 251, 0.52);
