.hubRow{
  --hub-cover-rgb-fb: 102, 110, 132;
  --hub-cover-rgb-eff: var(--hub-cover-rgb, var(--hub-cover-rgb-fb));
  border:1px solid rgba(255,255,255,0.10);
  border-radius:14px;
  padding:10px 10px 10px;
  margin-bottom:8px;
  background: linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.012));
  display:flex;
  flex-direction:column;
  gap:7px;
  position:relative;
}
.hubCoverWrap{
  width:100%;
  border-radius:10px;
  overflow:hidden;
  border:0;
  background: transparent;
  position:relative;
}
.hubCover{
  width:100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
  display:block;
}
.hubActionRow{
  display:flex;
  gap:8px;
  flex-wrap:wrap;
  margin-top:2px;
}
.hubActionRow .ghost{
  border-radius:10px;
  padding:7px 11px;
}
.hubPlayOverlay{
  position:absolute;
  left:10px;
  bottom:10px;
  width:34px;
  height:34px;
  z-index:3;
  border-radius:999px;
  border:1px solid rgba(255,255,255,0.22);
  background: rgba(8,12,20,0.62);
  color:#fff;
  display:flex;
  align-items:center;
  justify-content:center;
  font-size:14px;
  pointer-events:auto;
  cursor:pointer;
}
.hubPlayProgress{
  position:absolute;
  left:46px;
  right:10px;
  bottom:8px;
  height:5px;
  z-index:2;
  border-radius:999px;
  background: rgba(255,255,255,0.22);
  overflow:hidden;
  pointer-events:none;
  display:none;
}
.hubCoverWrap.isPlaying .hubPlayProgress{ display:block; }
.hubPlayProgress span{
  display:block;
  height:100%;
  width:0%;
  background: linear-gradient(90deg, rgba(var(--hub-cover-rgb-eff), 0.62), rgba(var(--hub-cover-rgb-eff), 0.22));
  transition: width 120ms linear;
}

/*
 * "Alive" cues for the playing post — purely CSS so there's no JS animation
 * loop running. Each rule keys off classes the JS already toggles
 * (`isPlaying` on the cover wrap, plus a new `isLoading` class while audio
 * is buffering between src-set and the play() promise resolving).
 */

/* Subtle "breathing" pulse on the cover image so it feels live without
 * shifting layout. Stays well under the threshold of being distracting. */
.hubCoverWrap.isPlaying .hubCover{
  animation: hubCoverBreath 3.6s ease-in-out infinite;
  will-change: transform, filter;
}
@keyframes hubCoverBreath{
  0%, 100% { transform: scale(1); filter: brightness(1) saturate(1); }
  50% { transform: scale(1.012); filter: brightness(1.04) saturate(1.06); }
}

/* 3-bar equalizer overlay. Hidden by default, fades in only while playing. */
.hubEq{
  position:absolute;
  top:10px;
  left:10px;
  display:flex;
  align-items:flex-end;
  gap:4px;
  height:18px;
  padding:6px 9px;
  border-radius:9px;
  background: rgba(6,10,18,0.72);
  border: 1px solid rgba(255,255,255,0.16);
  box-shadow:
    0 0 12px rgba(var(--hub-cover-rgb-eff), 0.16),
    0 0 10px rgba(var(--hub-cover-rgb-eff), 0.10);
  pointer-events:none;
  opacity:0;
  transition: opacity 220ms ease;
}
.hubCoverWrap.isPlaying .hubEq{ opacity:1; }
.hubEq i{
  display:block;
  width:4px;
  height:100%;
  background: linear-gradient(180deg, rgba(var(--hub-cover-rgb-eff), 0.95), rgba(var(--hub-cover-rgb-eff), 0.35));
  border-radius:2px;
  box-shadow: 0 0 6px rgba(var(--hub-cover-rgb-eff), 0.28);
  transform-origin: bottom center;
  animation: hubEqBar 780ms ease-in-out infinite;
  will-change: transform;
}
.hubEq i:nth-child(2){ animation-duration: 980ms; animation-delay: 100ms; }
.hubEq i:nth-child(3){ animation-duration: 860ms; animation-delay: 55ms; }
@keyframes hubEqBar{
  0%, 100% { transform: scaleY(0.28); }
  25% { transform: scaleY(0.92); }
  45% { transform: scaleY(0.48); }
  65% { transform: scaleY(1); }
  85% { transform: scaleY(0.62); }
}

/* Loading shimmer on the progress bar while audio is buffering. The progress
 * bar otherwise only shows during playback — `isLoading` reuses the slot to
 * confirm "we heard you tap, audio is on the way" before play() resolves. */
.hubCoverWrap.isLoading .hubPlayProgress{
  display:block;
  background: linear-gradient(90deg,
    rgba(255,255,255,0.10) 0%,
    rgba(255,255,255,0.40) 50%,
    rgba(255,255,255,0.10) 100%);
  background-size: 220% 100%;
  animation: hubLoadingShimmer 1100ms linear infinite;
}
.hubCoverWrap.isLoading .hubPlayProgress span{ opacity:0; }
@keyframes hubLoadingShimmer{
  0% { background-position: 110% 0; }
  100% { background-position: -110% 0; }
}

@media (prefers-reduced-motion: reduce){
  .hubCoverWrap.isPlaying .hubCover,
  .hubEq i,
  .hubCoverWrap.isLoading .hubPlayProgress{
    animation: none !important;
  }
  .coverArtPlaySpinner{
    animation: none !important;
  }
}

/*
 * Focus mode: dim non-focused rows so the centered card visually owns the
 * screen. Driven by `.isActive` which JS toggles on the row whose center
 * is closest to the viewport center (raf-throttled during scroll). This
 * decouples the *visual* focus from audio loading — focus snaps in the
 * instant a swipe lands, instead of waiting for `startHubPlayback` to
 * finish loading and add `.isPlaying`.
 */
#hubList .hubRow{
  transition:
    opacity 200ms cubic-bezier(0.22, 1, 0.36, 1),
    filter 200ms cubic-bezier(0.22, 1, 0.36, 1),
    transform 200ms cubic-bezier(0.22, 1, 0.36, 1),
    border-color 200ms cubic-bezier(0.22, 1, 0.36, 1),
    background 200ms cubic-bezier(0.22, 1, 0.36, 1);
}
/* Option B (focused-card): when any post is active, neighbors dim
 * hard so the active card feels like the only thing on screen
 * without going fullscreen. We use opacity + saturate + blur in
 * concert — opacity alone made nearby covers still grab the eye. */
#hubList:has(.hubRow.isActive) .hubRow:not(.isActive){
  opacity: 0.32;
  filter: saturate(0.45) blur(1.5px);
  transform: scale(0.985);
}
/* Old Safari (and the iOS PWA at boot) doesn't always honor the
 * filter blur immediately if there's no dedicated layer. Promote the
 * row to its own compositing layer so the dim animates cleanly on
 * scroll-snap. */
#hubList .hubRow{
  will-change: transform, opacity, filter;
}
@media (prefers-reduced-motion: reduce){
  #hubList .hubRow{ transition: none; }
}

/* Skeleton placeholders for the Hub feed while the first cloud refresh
 * is in flight. The silhouette mirrors the real `.hubRow` (16:9 art
 * on top, meta strip with avatar + creator/time, title line, then
 * the Like/Melody/Share pill row) so the swap from skeleton to real
