/* ---- Action row hierarchy: Like (primary) + Reactions (secondary) ---- */
.hubActionRow{
  display:flex;
  align-items:center;
  gap:10px;
  flex-wrap:wrap;
  margin-top:6px;
}

/* Like — bigger, primary. Fills with red as the count grows. */
.hubLike{
  display:inline-flex;
  align-items:center;
  gap:8px;
  height:36px;
  padding:0 14px 0 12px;
  border-radius:999px;
  border:1px solid rgba(255,255,255,0.14);
  background:
    linear-gradient(180deg, rgba(255,255,255,0.04), rgba(255,255,255,0.012));
  color:#f0f4ff;
  font-weight:700;
  font-size:13.5px;
  cursor:pointer;
  /* Coordinated focus transitions: size/padding/font glide on focus
   * change, while transform/border/background still react quickly to
   * hover/press feedback. Eased with ease-out-quart for a soft landing. */
  transition:
    height 280ms cubic-bezier(0.22, 1, 0.36, 1),
    padding 280ms cubic-bezier(0.22, 1, 0.36, 1),
    gap 280ms cubic-bezier(0.22, 1, 0.36, 1),
    font-size 280ms cubic-bezier(0.22, 1, 0.36, 1),
    transform 140ms ease,
    border-color 200ms ease,
    background 200ms ease;
  -webkit-tap-highlight-color: transparent;
}
.hubLike:hover{ border-color: rgba(255,255,255,0.24); }
.hubLike:active{ transform: scale(0.96); }
.hubLikeHeart{
  font-size:18px;
  line-height:1;
  display:inline-block;
  color: var(--danger);
  text-shadow:
    0 0 6px rgba(255, 77, 109, 0.45),
    0 0 14px rgba(255, 77, 109, 0.20);
  transition:
    transform 220ms cubic-bezier(.2,1.4,.4,1),
    font-size 280ms cubic-bezier(0.22, 1, 0.36, 1);
}
/* Brief pulse on tap. JS sets data-burst="1" momentarily. */
.hubLike[data-burst="1"] .hubLikeHeart{
  animation: hubLikeBurst 520ms cubic-bezier(.2,1.6,.4,1);
}
@keyframes hubLikeBurst{
  0%   { transform: scale(1); }
  35%  { transform: scale(1.55); }
  60%  { transform: scale(0.92); }
  100% { transform: scale(1); }
}
.hubLikeCount{
  font-variant-numeric: tabular-nums;
  letter-spacing:0.2px;
  color: rgba(223, 231, 251, 0.92);
}
/* Once liked (count > 0), turn the chip a touch warmer so it reads as "you liked something here". */
.hubLike[data-count]:not([data-count="0"]){
  border-color: rgba(255, 77, 109, 0.35);
  background: linear-gradient(180deg, rgba(255, 77, 109, 0.10), rgba(255, 77, 109, 0.04));
}

/* Reactions — secondary chips. Smaller, subtler. */
.hubReacts{
  display:flex;
  flex-wrap:wrap;
  gap:6px;
  flex:1 1 auto;
  justify-content:flex-end;
}
.hubReact{
  display:inline-flex;
  align-items:center;
  gap:5px;
  height:30px;
  padding:0 10px;
  border-radius:999px;
  border:1px solid rgba(255,255,255,0.10);
  background: rgba(255,255,255,0.025);
  color: rgba(223, 231, 251, 0.82);
  font-size: 13px;
  font-weight:500;
  cursor:pointer;
  transition:
    height 280ms cubic-bezier(0.22, 1, 0.36, 1),
    padding 280ms cubic-bezier(0.22, 1, 0.36, 1),
    gap 280ms cubic-bezier(0.22, 1, 0.36, 1),
    font-size 280ms cubic-bezier(0.22, 1, 0.36, 1),
    transform 120ms ease,
    border-color 200ms ease,
    color 200ms ease,
    background 200ms ease;
  -webkit-tap-highlight-color: transparent;
}
.hubReact:hover{
  color:#fff;
  border-color: rgba(255,255,255,0.20);
  background: rgba(255,255,255,0.05);
}
.hubReact:active{ transform: scale(0.94); }
.hubReactIcon{
  font-size:13px;
  line-height:1;
  opacity:0.85;
  transition: font-size 280ms cubic-bezier(0.22, 1, 0.36, 1);
}
.hubReactLabel{
  letter-spacing:0.1px;
}
.hubReactCount{
  font-variant-numeric: tabular-nums;
  opacity:0.7;
  margin-left:2px;
}
.hubReact[data-burst="1"]{
  animation: hubReactBurst 360ms cubic-bezier(.2,1.5,.4,1);
}
@keyframes hubReactBurst{
  0%   { transform: scale(1); }
  40%  { transform: scale(1.10); }
  100% { transform: scale(1); }
}

/* Share — same neutral chip as the other reactions. Color was distracting
 * against the existing palette (purple brand + warm Like + cover art);
 * the arrow icon + label is unambiguous on its own. */
.hubShare .hubReactIcon{
  transform: translateX(0.5px);
  font-size: 13px;
  letter-spacing:0;
}

/* Player Share + Download Video — neutral ghost buttons in line with the
 * rest of the player controls. */
.playerShareBtn,
.playerDownloadVideoBtn{
  display:inline-flex;
  align-items:center;
  gap:6px;
  font-weight:600;
}
.playerShareLabel,
.playerDownloadVideoLabel{ letter-spacing:0.1px; }
.playerDownloadVideoBtn[disabled]{
  opacity:0.7;
  cursor:wait;
}
/* Tiny spinner shown while the server is encoding the mp4. */
.dlSpin{
  display:inline-block;
  width:11px;
  height:11px;
  border-radius:999px;
  border:2px solid rgba(255,255,255,0.22);
  border-top-color: rgba(255,255,255,0.85);
  animation: dlSpin 700ms linear infinite;
  margin-right:2px;
}
@keyframes dlSpin{
  0%   { transform: rotate(0deg); }
  100% { transform: rotate(360deg); }
}
@media (prefers-reduced-motion: reduce){
  .dlSpin{ animation: none; }
}

@media (prefers-reduced-motion: reduce){
  .hubLike[data-burst="1"] .hubLikeHeart,
  .hubReact[data-burst="1"]{
    animation: none !important;
  }
  #hubList .hubRow.isActive{
    transform: none;
  }
  .hubTitle{ transition: none; }
}

/* Labels strategy:
 *   - Default (mobile): hide the text label. Compact icon + count chip
 *     keeps four reactions on one line with the like button.
 *   - Focused card: show the label so the user reading that card
 *     gets the meaning of each icon at a glance.
 *   - Tablet+ (≥ 600px): always show labels — there's plenty of room. */
.hubReact .hubReactLabel{ display:none; }
.hubRow.isActive .hubReact .hubReactLabel{
  display:inline;
}
@media (min-width: 600px){
  .hubReact .hubReactLabel{ display:inline; }
}

/* Share is universally understood from the arrow alone — keep its label
 * hidden on phones (even on the focused card, where Like/Melody/Lyrics
 * get their words) so all four chips fit on one row. Tablet+ has room
 * to show "Share" as text. */
.hubRow.isActive .hubShare .hubReactLabel{
  display:none;
}
@media (min-width: 600px){
  .hubRow.isActive .hubShare .hubReactLabel{
    display:inline;
  }
}

/* Phones: keep one consistent chip size in both focused and unfocused
 * states. The lift, glow ring, title gradient, and dim-others already
 * carry the focused card visually — chip resizing on top read as
 * "buttons jumping around" instead of polish. */
@media (max-width: 520px){
  .hubActionRow{
    gap:6px;
    flex-wrap:nowrap;
  }
  .hubReacts{
    gap:5px;
    flex:1 1 auto;
    min-width:0;
    justify-content:flex-end;
    flex-wrap:nowrap;
  }
  .hubLike{
    height:32px;
    padding:0 11px 0 10px;
    gap:6px;
    font-size: 13.5px;
    flex:0 0 auto;
  }
  .hubLikeHeart{ font-size:16px; }
  .hubReact{
    height:28px;
    padding:0 9px;
    gap:4px;
    font-size:11.5px;
    flex:0 1 auto;
    min-width:0;
  }
  .hubReactIcon{ font-size:13px; }
  /* Hide labels on phones in both states — icons + count carry meaning. */
  .hubRow.isActive .hubReact .hubReactLabel{
    display:none !important;
  }
}
.hubMoreCorner{
  position:absolute;
  right:10px;
  top:10px;
  width:34px;
  height:34px;
  border-radius:999px;
  border:1px solid rgba(255,255,255,0.24);
