}
.feedHookMarker{
  position: absolute;
  left: var(--feedHookPct, -999px);
  transform: translateX(-50%);
  width: 9px;
  height: 7px;
  pointer-events: none;
  z-index: 3;
  opacity: 0;
  transition: opacity 180ms ease;
}
.feedHookMarker::before{
  content: "";
  display: block;
  width: 9px;
  height: 7px;
  background: rgba(155, 135, 255, 0.96);
  clip-path: polygon(50% 100%, 0 0, 100% 0);
  filter: drop-shadow(0 0 5px rgba(124, 92, 255, 0.48));
}
.hasFeedHook > .feedHookMarker,
