  width: 7px;
  height: 5px;
}
.hubNowProg.hasFeedHook .feedHookMarker::before{
  width: 7px;
  height: 5px;
  filter: drop-shadow(0 0 4px rgba(124, 92, 255, 0.42));
}
/* Friends feed dock — tip overlaps waveform tops slightly. */
.followActMediaDockWave.hasFeedHook{
  overflow: visible;
}
.followActMediaDockWave.hasFeedHook .feedHookMarker{
  top: auto;
  bottom: calc(100% - 2px);
  width: 7px;
  height: 5px;
  z-index: 4;
}
.followActMediaDockWave.hasFeedHook .feedHookMarker::before{
  width: 7px;
  height: 5px;
}
/* Cover-art overlay scrubber — same sit-on spacing. */
.followActRealtimeProgress.hasFeedHook:not(.followActMediaDockWave) .feedHookMarker{
  top: auto;
  bottom: calc(100% - 2px);
  z-index: 4;
}
