  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  width: min(86vw, 320px);
  padding: 26px 22px 22px;
  border-radius: 22px;
  border: 1px solid rgba(255,255,255,0.13);
  background:
    linear-gradient(160deg, rgba(34, 40, 58, 0.97), rgba(14, 17, 28, 0.97)),
    radial-gradient(circle at 22% 0%, rgba(124, 92, 255, 0.22), transparent 64%);
  box-shadow: 0 28px 70px rgba(0,0,0,0.5);
  text-align: center;
  animation: remixCardIn 200ms ease-out;
}
@keyframes remixCardIn{
  from{ transform: translateY(10px) scale(0.96); opacity: 0; }
  to{ transform: translateY(0) scale(1); opacity: 1; }
}
.remixLoadingSpinner{
