/* ── Create context cards (remix + persona) ───────────────────────── */
.createContextCard{
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0;
  padding: 14px 14px 13px;
  border-radius: 18px;
  max-width: 100%;
  overflow: hidden;
  box-sizing: border-box;
  isolation: isolate;
}
.createContextCard::before{
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  opacity: 0.55;
}
.createContextCard::after{
  content: "";
  position: absolute;
  top: 0;
  left: 14px;
  right: 14px;
  height: 1px;
  border-radius: 999px;
  pointer-events: none;
  opacity: 0.85;
}
.remixSourceBanner{
  border: 1px solid rgba(124, 92, 255, 0.38);
  background:
    radial-gradient(120% 90% at 0% 0%, rgba(124, 92, 255, 0.22), transparent 58%),
    radial-gradient(90% 70% at 100% 100%, rgba(78, 192, 255, 0.14), transparent 55%),
    linear-gradient(165deg, rgba(16, 20, 34, 0.96) 0%, rgba(10, 13, 24, 0.92) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.08),
    0 14px 34px rgba(124, 92, 255, 0.14),
    0 4px 14px rgba(0, 0, 0, 0.28);
}
.createContextCard--remix::before{
  background: linear-gradient(135deg, rgba(124, 92, 255, 0.35), rgba(78, 192, 255, 0.18));
  mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
  mask-composite: exclude;
  -webkit-mask-composite: xor;
  padding: 1px;
}
.createContextCard--remix::after{
  background: linear-gradient(90deg, transparent, rgba(180, 168, 255, 0.55), rgba(120, 210, 255, 0.35), transparent);
}
.remixSourceBannerRow{
  display: flex;
  align-items: flex-start;
  gap: 12px;
  min-width: 0;
  position: relative;
  z-index: 1;
}
.remixSourceBanner[hidden],
.createContextCard[hidden]{ display: none !important; }
.createChallengeHint[hidden]{ display:none !important; }
.remixSourceBannerCover{
  flex: 0 0 auto;
  width: 46px;
  height: 46px;
  border-radius: 13px;
  background-color: rgba(255,255,255,0.08);
  background-size: cover;
  background-position: center;
  border: 1px solid rgba(255,255,255,0.16);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.12),
