}
.remixSourceBannerTitle{
  font-size: 14px;
  font-weight: 700;
  color: rgba(255, 255, 255, 0.96);
  line-height: 1.28;
  letter-spacing: -0.01em;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.remixSourceBannerSub{
  font-size: 11.5px;
  line-height: 1.38;
  color: rgba(220, 228, 245, 0.72);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.createContextCardActions{
