}
.remixSourceBannerClose:hover{
  background: rgba(255,255,255,0.14);
  color: #fff;
}
.remixSourceLyricsPanel{
  margin-top: 11px;
  padding-top: 11px;
  border-top: 1px solid rgba(255,255,255,0.1);
  position: relative;
  z-index: 1;
}
.remixSourceLyricsPanel[hidden]{ display:none !important; }
.remixSourceLyricsSummary{
  list-style:none;
  cursor:pointer;
  font-size: 10.5px;
