.styleSuggestPill{
  -webkit-appearance:none;
  appearance:none;
  flex:0 0 auto;
  white-space:nowrap;
  display:inline-flex;
  align-items:center;
  gap:6px;
  padding:7px 13px;
  border-radius:999px;
  border:1px solid rgba(255,255,255,0.12);
  background:rgba(255,255,255,0.04);
  color:rgba(232,238,247,0.86);
  font-size:12.5px;
  font-weight:650;
  letter-spacing:0.01em;
