/* Moment story studio — full-screen Instagram-style compose */
@keyframes momentStudioIn{
  from{ opacity: 0; transform: scale(1.02); }
  to{ opacity: 1; transform: scale(1); }
}
@keyframes momentStudioSpin{
  to{ transform: rotate(360deg); }
}
body[data-route="moment"] .header,
body[data-route="moment"] .footer,
body[data-route="moment"] .generateOrb,
body[data-route="moment"] .hubNowPlaying{
  display: none !important;
}
body[data-route="moment"] .mobileTabbar{
  display: none !important;
}
body[data-route="moment"] .app{
  padding: 0 !important;
  min-height: 100dvh;
}
html.momentRouteCameraLive,
body.momentRouteCameraLive{
  background: transparent !important;
}
body.momentRouteCameraLive .app,
body.momentRouteCameraLive main.grid,
body.momentRouteCameraLive .momentStudio,
body.momentRouteCameraLive .momentStudioViewport,
body.momentRouteCameraLive .momentStudioMedia,
body.momentRouteCameraLive .momentStudioPickStage{
  background: transparent !important;
}
body.momentRouteCameraLive .momentStudioChrome{
  background: transparent !important;
}
.momentStudio--liveNative{
  background: transparent !important;
}
.momentStudio--liveNative .momentStudioCameraVideo,
.momentStudio--liveNative .momentStudioCameraFallback{
  display: none !important;
}
.momentStudio--liveNative .momentStudioShade{
  opacity: 0 !important;
  pointer-events: none;
}
.momentStudio--webLive .momentStudioPickStage{
  background: #000;
}
body[data-route="moment"] main.grid{
  padding: 0 !important;
  margin: 0 !important;
  max-width: none !important;
}
body[data-route="moment"] main.grid > [data-route="moment"],
body[data-route="moment"] #momentPage{
  display: block !important;
  min-height: 100dvh;
}
/* Create chooser (z 13000) must not sit above moment and eat touches after "Create moment". */
body[data-route="moment"] #createChooserSheet{
  display: none !important;
  visibility: hidden !important;
  pointer-events: none !important;
}
.momentStudio{
  position: fixed;
  inset: 0;
  z-index: 15000;
  touch-action: manipulation;
  background: #000;
  color: #fff;
  overflow: hidden;
  animation: momentStudioIn 280ms cubic-bezier(0.22, 1, 0.36, 1);
}
