  transition: background 180ms ease, border-color 180ms ease, box-shadow 180ms ease, transform 180ms ease, opacity 180ms ease;
}
.photoMoodPrimary:disabled,
.imageMoodActions .primary:disabled{
  opacity: 0.42;
  cursor: not-allowed;
  box-shadow: none;
}
.photoMoodPrimary.isReady:not(:disabled),
.imageMoodActions .primary.isReady:not(:disabled){
  color: #041510;
  background: linear-gradient(180deg, #3ee7bf 0%, #23d5ab 100%);
  border-color: rgba(35, 213, 171, 0.85);
  box-shadow:
    0 0 0 1px rgba(35, 213, 171, 0.35),
    0 10px 24px rgba(35, 213, 171, 0.28);
  animation: photoMoodCtaPulse 1.8s ease-in-out infinite;
}
.photoMoodPrimary.isBusy:not(:disabled),
.imageMoodActions .primary.isBusy{
  opacity: 1;
  color: rgba(232, 255, 248, 0.96);
  background: linear-gradient(120deg, rgba(35, 213, 171, 0.22), rgba(124, 92, 255, 0.22), rgba(35, 213, 171, 0.22));
  background-size: 220% 100%;
  border-color: rgba(35, 213, 171, 0.45);
  animation: lyricShimmer 2.2s linear infinite;
  cursor: wait;
}
@keyframes photoMoodCtaPulse{
  0%, 100%{ box-shadow: 0 0 0 1px rgba(35, 213, 171, 0.30), 0 10px 24px rgba(35, 213, 171, 0.22); }
  50%{ box-shadow: 0 0 0 2px rgba(35, 213, 171, 0.45), 0 12px 28px rgba(35, 213, 171, 0.36); }
}
.photoMoodSecondary,
.imageMoodActions .ghost{
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.10);
  color: rgba(248, 250, 255, 0.88);
}
.photoMoodSecondary:disabled,
.imageMoodActions .ghost:disabled{
  opacity: 0.45;
}
html[data-theme="light"] .imageMoodAnalyzingLabel{
  color: rgba(15, 23, 40, 0.92);
