.echoTile{
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 7px;
  width: 76px;
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
  color: inherit;
  -webkit-tap-highlight-color: transparent;
}
.echoTile:active{ transform: scale(0.96); }
.echoTileShell{
  position: relative;
  width: 72px;
  height: 72px;
  border-radius: 20px;
  overflow: hidden;
  background: rgba(8,10,18,0.92);
  box-shadow:
    0 4px 18px rgba(0,0,0,0.42),
    inset 0 0 0 1px rgba(255,255,255,0.08);
}
.echoTileShell--pulse::before{
  content: "";
  position: absolute;
  inset: -2px;
  border-radius: 22px;
  background: linear-gradient(135deg, rgba(124,92,255,0.55), rgba(167,139,250,0.35), rgba(35,213,171,0.2));
  opacity: 0.85;
  z-index: 0;
  animation: echoTileGlow 2.8s ease-in-out infinite;
}
@keyframes echoTileGlow{
  0%, 100%{ opacity: 0.55; transform: scale(1); }
  50%{ opacity: 0.95; transform: scale(1.02); }
}
.echoTile.isViewed .echoTileShell--pulse::before{
  opacity: 0;
  animation: none;
}
.echoTileShell--add{
  display: flex;
  align-items: center;
  justify-content: center;
  background:
    linear-gradient(145deg, rgba(124,92,255,0.18), rgba(6,9,16,0.95));
  border: 1px dashed rgba(167,139,250,0.45);
  box-shadow: 0 6px 20px rgba(0,0,0,0.35);
}
.echoTileShell--add::before{ display: none; }
.echoTileAddIcon{
  font-size: 28px;
  font-weight: 300;
  line-height: 1;
  color: rgba(167,139,250,0.95);
}
.echoTileMedia{
  position: absolute;
  inset: 3px;
  border-radius: 17px;
  overflow: hidden;
  z-index: 2;
}
.echoTileAvatar,
.echoTileAvatarFallback{
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  border-radius: 17px;
}
.echoTileAvatarFallback{
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 18px;
  font-weight: 800;
  letter-spacing: 0.04em;
  color: rgba(232,238,247,0.88);
  background: linear-gradient(145deg, rgba(124,92,255,0.35), rgba(6,9,16,0.9));
}
.echoTileWave{
  position: absolute;
  inset: auto 4px 4px;
  left: 4px;
  right: 4px;
  height: 22px;
  z-index: 3;
  display: flex;
  align-items: flex-end;
  gap: 1px;
  pointer-events: none;
  mask-image: linear-gradient(180deg, transparent, #000 35%);
}
.echoTileOnce{
  position: absolute;
  top: 5px;
  right: 5px;
  z-index: 4;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.06em;
  padding: 2px 5px;
  border-radius: 6px;
  color: rgba(255,255,255,0.92);
  background: rgba(6,9,16,0.72);
  border: 1px solid rgba(167,139,250,0.45);
  backdrop-filter: blur(8px);
}
.echoTileLabel{
  font-size: 11px;
  font-weight: 700;
  max-width: 76px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: rgba(232,238,247,0.72);
}
.echoTile.isActive .echoTileLabel{ color: rgba(167,139,250,0.95); }
.echoTile--add .echoTileLabel{ color: rgba(167,139,250,0.88); }

.echoWave{
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1.5px;
  min-width: 0;
}
.echoBar{
  flex: 1;
  max-width: 5px;
  min-width: 2px;
  height: calc(8px + var(--bar-h, 35%) * 48px);
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(200,180,255,0.95) 0%, rgba(124,92,255,0.9) 50%, rgba(35,213,171,0.75) 100%);
  transform-origin: center bottom;
  opacity: 0.52;
  transition: height 70ms ease, opacity 120ms ease, box-shadow 120ms ease;
  animation: echoBarBreathe 3.2s ease-in-out infinite;
  animation-delay: calc(var(--bar-i, 0) * 40ms);
}
.echoBar--hi{ filter: saturate(1.12); opacity: 0.62; }
.echoBar--tile{
  max-width: 3px;
  min-width: 1.5px;
  height: calc(4px + var(--bar-h, 35%) * 14px);
  animation-duration: 2.6s;
}
.echoBar--live{
  opacity: 0.88;
  animation: none;
}
@keyframes echoBarBreathe{
  0%, 100%{ transform: scaleY(0.92); opacity: 0.48; }
  50%{ transform: scaleY(1.06); opacity: 0.72; }
}

.echoViewerSheet{
