  align-items: stretch;
  justify-content: center;
  pointer-events: none;
}
.echoComposeSheet[hidden]{ display: none !important; }
.echoComposeSheet.isOpen{ pointer-events: auto; }
.echoComposeBackdrop{
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 95% 65% at 50% 12%, rgba(124,92,255,0.2), transparent 58%),
    radial-gradient(ellipse 55% 45% at 88% 78%, rgba(35,213,171,0.1), transparent 52%),
    radial-gradient(ellipse 40% 35% at 8% 62%, rgba(167,139,250,0.08), transparent 50%),
    #03040a;
  background-color: rgba(3,4,10, calc(0.98 + var(--echo-pressure) * 0.01));
  backdrop-filter: blur(28px) saturate(calc(1.08 + var(--echo-pressure) * 0.06));
  -webkit-backdrop-filter: blur(28px) saturate(calc(1.08 + var(--echo-pressure) * 0.06));
  opacity: 0;
  transition:
    opacity 380ms ease,
    background 400ms ease;
}
.echoComposeSheet.isOpen .echoComposeBackdrop{ opacity: 1; }
.echoComposeSheet.isTouching .echoComposeBackdrop,
.echoComposeSheet.isRecording .echoComposeBackdrop{
  background-color: rgba(2,3,12, calc(0.99 + var(--echo-pressure) * 0.005));
}
.echoComposeSheet.isRecording .echoComposeBackdrop{
  background-image:
    radial-gradient(ellipse 100% 70% at 50% 38%, rgba(124,92,255,0.28), transparent 62%),
    radial-gradient(ellipse 50% 40% at 82% 80%, rgba(255,77,109,0.08), transparent 55%),
    radial-gradient(ellipse 40% 35% at 12% 55%, rgba(35,213,171,0.1), transparent 50%);
}
.echoComposeSheet.isProcessing .echoComposeBackdrop,
.echoComposeSheet.isReleasing .echoComposeBackdrop{
  background-image:
    radial-gradient(ellipse 90% 60% at 50% 42%, rgba(124,92,255,0.32), transparent 60%),
    radial-gradient(ellipse 45% 40% at 70% 75%, rgba(35,213,171,0.12), transparent 55%);
  animation: echoBackdropSend 2.4s ease-in-out infinite;
}
@keyframes echoBackdropSend{
  0%, 100%{ opacity: 1; filter: brightness(1); }
  50%{ opacity: 0.92; filter: brightness(1.08); }
}
.echoComposeDrift{
  position: absolute;
  inset: -20%;
  pointer-events: none;
  opacity: 0.55;
  background:
    radial-gradient(ellipse 55% 40% at 30% 25%, rgba(124,92,255,0.14), transparent 60%),
    radial-gradient(ellipse 45% 35% at 75% 70%, rgba(35,213,171,0.07), transparent 58%);
  animation: echoComposeDrift 22s ease-in-out infinite alternate;
}
@keyframes echoComposeDrift{
  0%{ transform: translate(0, 0) scale(1); }
  100%{ transform: translate(2%, -1.5%) scale(1.04); }
}
.echoComposeGrain{
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.045;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  mix-blend-mode: soft-light;
}
.echoComposeMotes{
  position: absolute;
  inset: 0;
  pointer-events: none;
  overflow: hidden;
}
.echoComposeMotes::before,
.echoComposeMotes::after{
  content: "";
  position: absolute;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: rgba(200,180,255,0.35);
  box-shadow:
    12vw 18vh 0 0 rgba(167,139,250,0.2),
    78vw 22vh 0 0 rgba(167,139,250,0.15),
    44vw 72vh 0 0 rgba(35,213,171,0.12),
    88vw 58vh 0 0 rgba(167,139,250,0.1);
  animation: echoMotesFloat 18s ease-in-out infinite alternate;
}
.echoComposeMotes::after{
  animation-duration: 26s;
  animation-delay: -6s;
  opacity: 0.6;
}
@keyframes echoMotesFloat{
  0%{ transform: translateY(0); opacity: 0.5; }
  100%{ transform: translateY(-12px); opacity: 0.85; }
}
.echoComposeCard{
