.echoComposeAmbient{
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(
      ellipse calc(70% + var(--echo-pressure) * 18%) calc(48% + var(--echo-pressure) * 12%) at 50% 42%,
      rgba(124,92,255, calc(0.14 + var(--echo-pressure) * 0.1 + var(--echo-voice) * 0.08)),
      transparent 62%
    ),
    radial-gradient(ellipse 60% 40% at 80% 80%, rgba(35,213,171,0.06), transparent 55%);
  opacity: calc(0.85 + var(--echo-pressure) * 0.12);
  transition: opacity 400ms ease;
}
.echoComposeAura{
  position: absolute;
  left: 50%;
  top: 50%;
  width: min(280px, 78vw);
  height: min(280px, 78vw);
  transform: translate(-50%, -50%);
  pointer-events: none;
}
.echoComposeWaveHorizon--orbit{
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  transform: none;
  left: auto;
  top: auto;
  display: block;
  mask-image: radial-gradient(circle, #000 38%, transparent 70%);
  -webkit-mask-image: radial-gradient(circle, #000 38%, transparent 70%);
}
.echoComposeWaveHorizon--orbit .echoBar--orbit{
  position: absolute;
  left: 50%;
  top: 50%;
  width: 2px;
  min-width: 2px;
  max-width: 2px;
  height: calc(10px + var(--bar-h, 0.35) * 36px);
  margin-left: -1px;
  margin-top: calc(-5px - var(--bar-h, 0.35) * 18px);
  transform-origin: center calc(5px + var(--bar-h, 0.35) * 18px);
  transform: rotate(var(--orbit-deg, 0deg))
    translateY(calc(-64px - var(--echo-aura, 0) * 32px - var(--echo-pressure, 0) * 12px));
  opacity: calc(0.28 + var(--bar-h, 0.35) * 0.5 + var(--echo-voice, 0) * 0.2);
  border-radius: 999px;
  background: linear-gradient(
    180deg,
    rgba(200,180,255,0.5),
    rgba(124,92,255,0.75) 50%,
    rgba(35,213,171,0.35)
  );
  box-shadow: 0 0 10px rgba(124,92,255, calc(0.15 + var(--echo-voice, 0) * 0.25));
  transition:
    height 90ms ease,
    opacity 120ms ease,
    transform 120ms ease;
}
.echoComposeWaveHorizon--orbit .echoBar--orbit.echoBar--breathe{
  animation: echoOrbitBreathe 3.6s ease-in-out infinite;
  animation-delay: calc(var(--bar-i, 0) * 55ms);
}
@keyframes echoOrbitBreathe{
  0%, 100%{ opacity: 0.32; filter: blur(0); }
  50%{ opacity: 0.58; filter: blur(0.3px); }
}
.echoComposeSheet.isTouching .echoComposeWaveHorizon--orbit .echoBar--orbit,
.echoComposeSheet.isRecording .echoComposeWaveHorizon--orbit .echoBar--orbit{
  animation: none;
}
