@keyframes echoBeatChipPulse{
  0%, 100%{ box-shadow: 0 0 0 2px rgba(124,92,255,0.18), 0 6px 18px rgba(124,92,255,0.22); }
  50%{ box-shadow: 0 0 0 3px rgba(124,92,255,0.30), 0 8px 22px rgba(124,92,255,0.32); }
