.echoBeatChip.is-variant-0 .echoBeatChipDots::before{ background: rgba(255,255,255,0.95); }
.echoBeatChip.is-variant-1 .echoBeatChipDots::after{ background: rgba(255,255,255,0.95); }

/* =====================================================================
 * Suggest chip — this is an ACTION button, not a selectable beat. It
 * should never look like the .is-active genre chips. Subtle amber-gold
 * accent, dimmed until a recording exists.
 * =================================================================== */
.echoBeatChip--suggest{
  color: rgba(252,237,200,0.92);
  background: rgba(255,255,255,0.04);
  border: 1px dashed rgba(252,211,77,0.42);
  box-shadow: none;
  gap: 5px;
  font-weight: 700;
}
.echoBeatChip--suggest:hover{
  color: rgba(255,244,210,1);
  background: rgba(252,211,77,0.08);
  border-color: rgba(252,211,77,0.6);
}
.echoBeatChip--suggest.is-active,
.echoBeatChip--suggest:active{
  background: rgba(252,211,77,0.08);
}
.echoBeatChip--suggest .echoBeatChipSparkle{
  display: inline-block;
  font-size: 13px;
  line-height: 1;
  transform-origin: center;
  animation: echoSuggestSparkle 2.8s ease-in-out infinite;
}
@keyframes echoSuggestSparkle {
  0%, 100% { transform: scale(1) rotate(0deg);  opacity: 0.92; }
  50%      { transform: scale(1.12) rotate(8deg); opacity: 1; }
}
/* Dimmed until a recording exists — clear it's an action that needs input first */
.echoBeatChip--suggest.is-empty{
  opacity: 0.42;
  border-style: dashed;
  border-color: rgba(151,165,186,0.28);
  color: rgba(151,165,186,0.7);
}
.echoBeatChip--suggest.is-empty .echoBeatChipSparkle{ animation: none; opacity: 0.55; }
/* Recording exists — bright and ready to tap */
.echoBeatChip--suggest.is-ready{
  border-style: solid;
  border-color: rgba(252,211,77,0.72);
  box-shadow: 0 0 0 1px rgba(252,211,77,0.18), 0 6px 18px -10px rgba(252,211,77,0.55);
}
/* Armed — waiting for the next recording to auto-pick a beat */
.echoBeatChip--suggest.is-armed{
  opacity: 1;
  color: rgba(255,244,210,1);
  background: linear-gradient(135deg, rgba(252,211,77,0.16), rgba(244,114,182,0.10));
  border-style: solid;
  border-color: rgba(252,211,77,0.72);
  box-shadow: 0 0 0 1px rgba(252,211,77,0.28), 0 6px 18px -10px rgba(252,211,77,0.65);
  animation: echoSuggestArmedPulse 1.6s ease-in-out infinite;
}
@keyframes echoSuggestArmedPulse {
  0%, 100% { box-shadow: 0 0 0 1px rgba(252,211,77,0.28), 0 6px 18px -10px rgba(252,211,77,0.65); }
  50%      { box-shadow: 0 0 0 2px rgba(252,211,77,0.45), 0 10px 22px -8px rgba(252,211,77,0.85); }
}
.echoBeatChip--suggest.is-armed .echoBeatChipSparkle{ animation: echoSuggestSparkle 1.4s ease-in-out infinite; }
.echoBeatChip--suggest.is-busy{
  opacity: 0.78;
  cursor: progress;
}
.echoBeatChip--suggest.is-busy .echoBeatChipSparkle{
  animation: echoSuggestBusy 0.9s linear infinite;
}
@keyframes echoSuggestBusy {
  0%   { transform: rotate(0deg);   }
  100% { transform: rotate(360deg); }
}

