/* Profile is laid out as a vertical stack of independent blocks (hero ·
 * songs · account), each spaced like Library/Hub. The route section
 * itself is borderless so blocks decide their own framing. */
.profileSection{
  display: flex;
  flex-direction: column;
  gap: 14px;
  /* No section-level entrance animation: the route-enter transition
     (animateRouteEnter) already animates this panel. A separate
     `animation: sectionFadeIn` (translateY 8px→0) re-fires when the
     routeEnter class is removed, making the whole panel nudge 8px and
     snap back — the "misplace then settle" glitch. */
  max-width: 100%;
  overflow-x: visible;
  overflow-y: visible;
}

/* =================================================================
 * Aura profile header
 *
 * No full-page gradient wash — the hero sits on the same surface as
 * the rest of the app. A breathing gradient ring around the avatar
 * lights up when audio is playing (data-audio-state="playing").
 * ================================================================= */
.profileAura{
  --aura-tint: rgba(124, 92, 255, 0.55);
  --aura-tint-soft: rgba(124, 92, 255, 0.18);
  --aura-tint-solid: rgb(168, 152, 255);
  --aura-bpm: 88;
  --profile-header-pad-top: 46px;
  --profile-header-gap: 10px;
  --profile-avatar-size: 96px;
  --profile-stats-max-w: 360px;
  --profile-pro-banner-inset: 0px;
  --profile-pro-banner-max-w: none;
  --profile-aura-pad-x: 8px;
  --profile-songs-block-pad-x: 6px;
  --profile-stat-col-pad-x: 4px;
  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  gap: var(--profile-header-gap);
  /* Top chrome is position:fixed; reserve one safe-area pass + row height
     so the avatar clears the credits pill + edit/settings (no second
     safe-area — `.app` top padding is zeroed on this route in mobile). */
  padding: calc(env(safe-area-inset-top, 0px) + var(--profile-header-pad-top)) var(--profile-aura-pad-x, 8px) 4px;
  margin-bottom: 0;
  max-width: 100%;
  overflow-x: hidden;
}

/* Top chrome row — fixed to the viewport. Markup lives in
 * #profileAuraHeaderChromeRoot OUTSIDE [data-route="profile"] so the
 * router's display:none never tears down fixed layout (fixes iOS
 * jump when returning from Credits / Settings). Off-route: visibility
 * hidden (not display:none) so safe-area stays stable. */
.profileAuraHeaderChrome{
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 60;
  display: flex;
  flex-wrap: nowrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: calc(env(safe-area-inset-top, 0px) + 8px) 14px 8px;
  margin: 0;
  pointer-events: none;
  background: transparent;
}
body:not([data-route="profile"]) #profileAuraHeaderChromeRoot{
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
}
.profileAuraHeaderChrome > *{
  pointer-events: auto;
}

/* Desktop web shell: credits were fixed top-left and sat on the sidebar
 * brand mark. Keep mobile as-is (credits left / gear right); on desktop
 * pin the whole chrome cluster to the top-right next to Settings. */
@media (min-width: 1024px){
  html.is-web-shell body[data-route="profile"] #profileAuraHeaderChromeRoot.profileAuraHeaderChrome{
    justify-content: flex-end;
    gap: 8px;
  }
  html.is-web-shell body[data-route="profile"] #profileAuraHeaderChromeRoot .profileAuraToolbar{
    margin-left: 0;
