/* Owner-only "Publishing…" chip: a brand-new song is being saved permanently
   and pushed live in the background. Indeterminate shimmer (no honest % to
   show for a server-side copy) + a soft pulsing dot. */
.libRowChip.libRowChipPublishing{
  flex-shrink: 0;
  gap: 6px;
  padding: 0 10px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.01em;
  color: rgba(214, 224, 255, 0.96);
  border: 0;
  background: linear-gradient(
    100deg,
    rgba(124,92,255,0.18) 0%,
    rgba(124,92,255,0.18) 30%,
    rgba(168,142,255,0.42) 50%,
    rgba(124,92,255,0.18) 70%,
    rgba(124,92,255,0.18) 100%
  );
  background-size: 220% 100%;
  animation: libRowPublishingShimmer 1.5s linear infinite;
}
.libRowPublishingDot{
  width: 7px;
  height: 7px;
  border-radius: 999px;
  background: rgba(168,142,255,0.95);
  box-shadow: 0 0 0 0 rgba(168,142,255,0.55);
  animation: libRowPublishingPulse 1.4s ease-out infinite;
}
@keyframes libRowPublishingShimmer{
  0%{ background-position: 120% 0; }
  100%{ background-position: -120% 0; }
}
@keyframes libRowPublishingPulse{
  0%{ box-shadow: 0 0 0 0 rgba(168,142,255,0.55); }
  70%{ box-shadow: 0 0 0 6px rgba(168,142,255,0); }
  100%{ box-shadow: 0 0 0 0 rgba(168,142,255,0); }
}
@media (prefers-reduced-motion: reduce){
  .libRowChip.libRowChipPublishing{ animation: none; }
  .libRowPublishingDot{ animation: none; }
}

