@media (max-width: 720px){
  /* Base rule above is display:none; JS clears inline display when showing.
     Without this, computed style stays none and the bar never paints. */
  .hubNowPlaying{
    --cover-glow-rgb: 100, 108, 128;
    --cover-prog-rgb: 100, 108, 128;
    --mini-player-gap: 3px;
    display: block;
    position: fixed;
    left: 0;
    right: 0;
    bottom: calc(var(--tabbar-h, calc(62px + env(safe-area-inset-bottom, 0px))) + var(--mini-player-gap, 3px));
    z-index: 65;
    padding: 0 6px;
    pointer-events: none;
    transform: translate3d(0, 28px, 0);
    opacity: 0;
    will-change: transform, opacity;
    transition:
      transform 340ms cubic-bezier(0.22, 1, 0.36, 1),
      opacity 300ms ease;
  }
  .hubNowPlaying.isVisible{
    pointer-events: auto;
    transform: translate3d(0, 0, 0);
    opacity: 1;
  }
  .hubNowShell{
    position: relative;
    margin: 0 auto;
    max-width: min(640px, 100%);
    border-radius: 20px;
    overflow: hidden;
    isolation: isolate;
    box-shadow:
      0 10px 28px rgba(0, 0, 0, 0.34),
      0 2px 8px rgba(0, 0, 0, 0.18);
    transform: scale(0.96) translateY(4px);
    opacity: 0.92;
    will-change: transform, opacity, box-shadow;
    transition:
      transform 360ms cubic-bezier(0.22, 1, 0.36, 1),
      opacity 300ms ease,
      box-shadow 320ms ease;
  }
  .hubNowPlaying.isVisible .hubNowShell{
    transform: scale(1) translateY(0);
    opacity: 1;
    box-shadow:
      0 10px 28px rgba(0, 0, 0, 0.38),
      0 2px 8px rgba(0, 0, 0, 0.20),
      0 0 0 1px rgba(255, 255, 255, 0.08);
  }
  .hubNowPlaying.isPlaying .hubNowShell{
    box-shadow:
      0 12px 32px rgba(0, 0, 0, 0.42),
      0 2px 10px rgba(0, 0, 0, 0.22),
      0 0 0 1px rgba(255, 255, 255, 0.10);
  }
  @media (prefers-reduced-motion: reduce){
    .hubNowPlaying{
      transform: none;
      transition: none;
    }
    .hubNowPlaying.isVisible{
      transform: none;
    }
    .hubNowShell{
      transform: none !important;
      transition: none;
      opacity: 1 !important;
    }
    .footer{
      transition: none !important;
    }
