.coachFab{
  display: none;
  position: relative;
  width: 34px;
  height: 34px;
  padding: 0;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 50%;
  background: transparent;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: transform 160ms ease, filter 200ms ease, opacity 200ms ease;
  animation: coachOrbBloom 420ms cubic-bezier(0.34, 1.56, 0.64, 1) both;
  will-change: transform, opacity;
}
.coachFab--header{
  display: inline-flex;
  flex: 0 0 auto;
  z-index: 2;
  overflow: visible;
}
.coachFab:active{ transform: scale(0.94); }
.coachFabIco{
  display: inline-flex;
  width: 100%;
  height: 100%;
  overflow: visible;
  transform-origin: 50% 50%;
  /* Subtle, slow "breathing" so the orb feels alive once it has settled.
     Lives on the inner wrapper so it never fights the entrance transform on
     the button. Delayed to start after the bloom finishes. */
  animation: coachOrbBreathe 4200ms ease-in-out 420ms infinite;
}
.coachFab .coachFabIco svg{
  width: 100%;
  height: 100%;
  filter: drop-shadow(0 3px 8px rgba(91, 60, 255, 0.28));
  animation: coachOrbGlow 4200ms ease-in-out 420ms infinite;
}
@keyframes coachOrbBloom{
  0%   { opacity: 0; transform: scale(0.55) rotate(-18deg); }
  55%  { opacity: 1; }
  100% { opacity: 1; transform: scale(1) rotate(0deg); }
}
@keyframes coachOrbBreathe{
  0%, 100% { transform: scale(1); }
  50%      { transform: scale(1.035); }
}
@keyframes coachOrbGlow{
  0%, 100% { filter: drop-shadow(0 3px 8px rgba(91, 60, 255, 0.28)); }
  50%      { filter: drop-shadow(0 5px 12px rgba(91, 60, 255, 0.42)); }
}
/* Teal orbit arcs sit outside the sphere — pulse + an occasional spin so the
   coach orb reads interactive without constant distraction. */
.coachOrbArcRing{
  transform-origin: 50px 50px;
  animation: coachArcSpin 11s ease-in-out infinite;
}
.coachOrbArc{
  opacity: 0.92;
  stroke: #36e7c0;
  animation: coachArcPulse 5200ms ease-in-out infinite;
}
.coachOrbArc--b{ animation-delay: 160ms; }
@keyframes coachArcSpin{
  0%, 68%, 100% { transform: rotate(0deg); }
  78% { transform: rotate(52deg); }
  86% { transform: rotate(38deg); }
}
@keyframes coachArcPulse{
  0%, 62%, 100% { opacity: 0.62; }
  78%           { opacity: 1; }
  90%           { opacity: 0.78; }
}
/* The "Need help?" idle nudge pill that pops to the left of the orb. */
.coachFabPill{
  position: absolute;
  right: calc(100% + 8px);
  top: 50%;
  white-space: nowrap;
  padding: 5px 10px;
  border-radius: 999px;
  background: linear-gradient(135deg, rgba(124,92,255,0.96), rgba(63,115,240,0.94));
  color: #fff;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.01em;
  line-height: 1.2;
  box-shadow: 0 8px 18px rgba(18,10,52,0.42);
  opacity: 0;
  transform: translateY(-50%) translateX(8px) scale(0.92);
  transform-origin: right center;
  pointer-events: none;
  transition: opacity 220ms ease, transform 240ms cubic-bezier(0.34,1.56,0.64,1);
}
.coachFab--nudge:not(.coachFab--hint):not(.coachFab--generating) .coachFabPill{
  opacity: 1;
  transform: translateY(-50%) translateX(0) scale(1);
  animation: coachFabPillBump 1800ms ease-in-out 220ms 1;
}
/* Contextual tips are a short sentence. Render them as a clean rounded card
   that sits ABOVE the orb (growing upward, away from the form) with a little
   caret pointing down at the orb — instead of the old stadium pill that wrapped
   into a tall blob over the Create fields. Both --nudge and --hint are present
   when a tip shows, so we override the idle-nudge positioning/animation here. */
.coachFab--header.coachFab--hint.coachFab--nudge .coachFabPill{
  animation: none;
}
.coachFab--hint .coachFabPill{
  right: 0;
  left: auto;
  top: auto;
  bottom: calc(100% + 12px);
  white-space: normal;
  width: max-content;
  max-width: min(72vw, 250px);
  border-radius: 14px;
  line-height: 1.34;
  text-align: right;
  transform: translateY(6px) scale(0.96);
  transform-origin: bottom right;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.coachFab--header.coachFab--hint .coachFabPill{
  right: 0;
  left: auto;
  top: calc(100% + 10px);
  bottom: auto;
  transform: translateY(4px) scale(0.96);
  transform-origin: top right;
}
.coachFab--hint.coachFab--nudge .coachFabPill{
  opacity: 1;
  transform: translateY(0) scale(1);
  animation: none;
}
/* Header orb: idle "Need help?" stays on the orb's center line (left of sphere). */
.coachFab--header.coachFab--nudge:not(.coachFab--hint):not(.coachFab--generating) .coachFabPill{
  right: calc(100% + 8px);
  left: auto;
  top: 50%;
  bottom: auto;
  transform: translateY(-50%) translateX(0) scale(1);
  white-space: nowrap;
  width: auto;
  max-width: none;
  border-radius: 999px;
  line-height: 1.2;
  text-align: left;
  animation: coachFabPillBump 1800ms ease-in-out 220ms 1;
}
.coachFab--header.coachFab--generating.coachFab--nudge .coachFabPill{
  right: 0;
  left: auto;
  top: calc(100% + 10px);
  bottom: auto;
  white-space: nowrap;
  opacity: 1;
  transform: translateY(0) scale(1);
  animation: coachGenPillPulseHeader 2600ms ease-in-out infinite;
}
/* Song generation — persistent status pill (replaces the loading bar). */
.coachFab--generating.coachFab--nudge .coachFabPill{
  opacity: 1;
  transform: translateY(-50%) translateX(0) scale(1);
  animation: coachGenPillPulse 2600ms ease-in-out infinite;
  background: linear-gradient(135deg, rgba(35,213,171,0.94), rgba(91,60,255,0.96));
  box-shadow: 0 10px 26px rgba(18,10,52,0.46), 0 0 0 1px rgba(255,255,255,0.08) inset;
}
@keyframes coachGenPillPulse{
  0%, 100% { opacity: 1; transform: translateY(-50%) translateX(0) scale(1); }
  50%      { opacity: 0.92; transform: translateY(-50%) translateX(0) scale(1.02); }
}
@keyframes coachGenPillPulseHeader{
  0%, 100% { opacity: 1; transform: translateY(0) scale(1); }
  50%      { opacity: 0.92; transform: translateY(0) scale(1.02); }
}
/* Caret: a small rotated square fused to the card's bottom edge, sitting right
   above the orb's center so the tip clearly belongs to the orb. */
.coachFab--hint .coachFabPill::after{
  content: "";
  position: absolute;
  top: 100%;
  right: 22px;
  width: 12px;
  height: 12px;
  margin-top: -6px;
  background: linear-gradient(135deg, rgba(124,92,255,0.96), rgba(63,115,240,0.94));
  border-radius: 2px;
  transform: rotate(45deg);
}
@keyframes coachFabPillBump{
  0%, 100% { transform: translateY(-50%) translateX(0) scale(1); }
  50%      { transform: translateY(-50%) translateX(-2px) scale(1.03); }
}
/* Respect reduced-motion: no spin/scale/pulse, just a quiet fade-in. */
@media (prefers-reduced-motion: reduce){
  .coachFab{ animation: coachOrbFadeIn 280ms ease both; }
  .coachFabIco,
  .coachFab .coachFabIco svg,
  .coachOrbArcRing,
  .coachOrbArc{ animation: none; }
  .coachOrbArc{ opacity: 0.8; }
  .coachFab--nudge .coachFabPill{ animation: none; }
}
@keyframes coachOrbFadeIn{
  from { opacity: 0; }
  to   { opacity: 1; }
}
