.profilePersonaSignature.profilePersonaRow{
  overflow: visible;
}
.profilePersonaSignature{
  position: relative;
  isolation: isolate;
  margin: 8px 0 26px;
  padding: 20px 20px 18px;
  border-radius: 26px;
  border: 1px solid rgba(124, 92, 255, 0.38);
  background:
    radial-gradient(130% 120% at 0% 0%, rgba(124, 92, 255, 0.22), transparent 58%),
    radial-gradient(100% 90% at 100% 100%, rgba(35, 213, 171, 0.14), transparent 55%),
    linear-gradient(165deg, rgba(24, 30, 48, 0.96), rgba(8, 11, 22, 0.92));
  box-shadow:
    0 26px 60px rgba(0, 0, 0, 0.38),
    0 0 56px rgba(124, 92, 255, 0.2),
    0 0 32px rgba(35, 213, 171, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.12);
}
.profilePersonaSignature::before{
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(135deg, rgba(124,92,255,0.65), rgba(35,213,171,0.45), rgba(183,168,255,0.55));
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
          mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
          mask-composite: exclude;
  pointer-events: none;
  z-index: -1;
  opacity: 0.85;
}
.profilePersonaSignature::after{
  content: "";
  position: absolute;
  inset: 12px 18px auto;
  height: 48px;
  border-radius: 999px;
  background: radial-gradient(80% 100% at 50% 50%, rgba(124,92,255,0.28), transparent 70%);
  filter: blur(18px);
  pointer-events: none;
  z-index: -2;
}
.profilePersonaSignature[hidden]{ display: none !important; }
.profilePersonaSignatureTop{
  display: flex;
  align-items: center;
  gap: 14px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.profilePersonaSignatureTop:focus-visible{
  outline: 2px solid rgba(124, 92, 255, 0.55);
  outline-offset: 3px;
  border-radius: 16px;
}
.profilePersonaSignatureMark{
  flex: 0 0 auto;
