}
.vwListenDot{
  position: absolute;
  left: 50%;
  top: 50%;
  width: 12px;
  height: 12px;
  margin: -6px 0 0 -6px;
  border-radius: 999px;
  background: linear-gradient(135deg, #23d5ab, #7c5cff);
  box-shadow: 0 0 18px rgba(35,213,171,0.55);
}
.vwListenRing{
  position: absolute;
