  border-radius: 999px;
  border: 2px solid rgba(35,213,171,0.45);
  animation: vwListenRipple 2.2s ease-out infinite;
}
.vwListenRing:nth-child(2){ animation-delay: 0.55s; }
.vwListenRing:nth-child(3){ animation-delay: 1.1s; }
@keyframes vwListenRipple{
  0%{ transform: scale(0.35); opacity: 0.95; }
  100%{ transform: scale(1.15); opacity: 0; }
}
.vwBuildLoader{
  position: relative;
  width: 72px;
  height: 72px;
  margin: 0 auto 4px;
