}
.vwEqLoader span:nth-child(2){ animation-delay: 0.12s; }
.vwEqLoader span:nth-child(3){ animation-delay: 0.24s; }
.vwEqLoader span:nth-child(4){ animation-delay: 0.08s; }
.vwEqLoader span:nth-child(5){ animation-delay: 0.3s; }
