  font-size: clamp(56px, 14vw, 64px);
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.045em;
  font-variant-numeric: tabular-nums;
  background: linear-gradient(135deg, var(--brand-violet) 0%, var(--brand-teal) 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.giftSheetBalanceCaption{
