.giftSheetTiers{
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  padding: 10px 16px 8px;
  margin-top: 2px;
}
.giftSheetTier{
  appearance: none;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 112px;
  padding: 12px 8px 10px;
  border-radius: 16px;
  border: 1px solid var(--border);
  background: var(--surface-secondary, rgba(255,255,255,0.04));
  color: var(--text-primary);
  font: inherit;
  text-align: center;
  cursor: pointer;
  transition:
    background 160ms ease,
    border-color 160ms ease,
    transform 160ms ease,
    opacity 160ms ease;
  -webkit-tap-highlight-color: transparent;
}
.giftSheetTierIcon{
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 52px;
  height: 52px;
}
.giftSheetTierGlow{
  position: absolute;
  inset: -10px;
  border-radius: 50%;
  pointer-events: none;
  filter: blur(18px);
  opacity: 0.9;
  z-index: 0;
}
.giftSheetTierIcon .giftSheetTierSvg,
.giftSheetTierIcon .giftTierSvg--mic,
.giftSheetTierIcon .giftTierSvg--pulse,
.giftSheetTierIcon .giftTierSvg--star{
  position: relative;
  z-index: 1;
  width: 30px;
  height: 30px;
  display: block;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.giftSheetTierIcon--mic .giftSheetTierGlow{
  background: rgba(242, 244, 248, 0.25);
}
.giftSheetTierIcon--mic .giftTierSvg--mic{
  color: currentColor;
}
.giftSheetTierIcon--pulse .giftSheetTierGlow{
  background:
    radial-gradient(circle at 40% 50%, rgba(124, 92, 255, 0.28) 0%, transparent 68%),
    radial-gradient(circle at 62% 44%, rgba(34, 230, 210, 0.20) 0%, transparent 62%);
}
.giftSheetTierIcon--star .giftSheetTierGlow{
  background: rgba(255, 209, 102, 0.30);
}
.giftSheetTier--mic:not(:disabled):hover{
  border-color: rgba(242, 244, 248, 0.22);
}
.giftSheetTier--pulse:not(:disabled):hover{
  border-color: rgba(124, 92, 255, 0.32);
}
.giftSheetTier--star:not(:disabled):hover{
  border-color: rgba(255, 209, 102, 0.34);
}
.giftSheetTierSvg{
  width: 30px;
  height: 30px;
  display: block;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.giftSheetTierName{
  font-size: 14px;
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: -0.01em;
  color: inherit;
}
.giftSheetTierValue{
  font-size: 12px;
  font-weight: 500;
  line-height: 1.2;
  color: var(--text-muted);
}
.giftSheetTier:hover:not(:disabled){
  background: var(--surface-hover, rgba(255,255,255,0.07));
  border-color: var(--border-strong, rgba(255,255,255,0.16));
}
.giftSheetTier:active:not(:disabled),
.giftSheetTier.isSending{
  transform: scale(0.97);
  background: rgba(255,255,255,0.08);
  border-color: rgba(255,255,255,0.22);
}
.giftSheetTier:active:not(:disabled) .giftSheetTierIcon,
.giftSheetTier.isSending .giftSheetTierIcon{
  transform: scale(1.04);
}
.giftSheetTier:disabled{
  opacity: 0.38;
  cursor: not-allowed;
}
.giftSheetTier:disabled .giftSheetTierIcon{
