/* Gift sent — premium center overlay with dim + tier motion */
.giftSentOverlay{
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px;
  pointer-events: none;
  background: transparent;
}
.giftSentOverlay[hidden]{
  display: none !important;
}
.giftSentDim{
  position: absolute;
  inset: 0;
  background: rgba(4, 6, 12, 0.82);
  opacity: 0;
  pointer-events: none;
}
.giftSentOverlay.isActive .giftSentDim{
  animation: giftSentDimIn 2650ms ease forwards;
}
.giftSentOverlay.isLeaving .giftSentDim{
  opacity: 0;
  animation: none;
  transition: opacity 140ms ease;
}
/* Keep icon stack hidden when isActive drops — base .giftSentStage is opacity:1 */
.giftSentOverlay.isLeaving .giftSentStage{
  opacity: 0;
  transform: scale(1.02);
  animation: none;
}
.giftSentOverlay.isLeaving .giftSentIconStack{
  animation: none;
}
.giftSentOverlay.isLeaving .giftSentGlow--base,
.giftSentOverlay.isLeaving .giftSentGlow--clash{
  opacity: 0;
  animation: none;
}
.giftSentOverlay.isLeaving .giftSentLabel{
  opacity: 0;
}
@keyframes giftSentDimIn{
  0%{ opacity: 0; }
  4%{ opacity: 1; }
  78%{ opacity: 1; }
  100%{ opacity: 0; }
}
.giftSentStage{
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
  opacity: 1;
  transform: scale(0.88);
  will-change: transform, opacity;
}
.giftSentOverlay.isActive .giftSentStage{
  animation: giftSentReveal 2650ms cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
@keyframes giftSentReveal{
  0%{
    opacity: 0.72;
    transform: scale(0.82);
  }
  6%{
    opacity: 1;
    transform: scale(1.18);
  }
  20%{
    opacity: 1;
    transform: scale(1);
  }
  76%{
    opacity: 1;
    transform: scale(1);
  }
  100%{
    opacity: 0;
    transform: scale(1.02);
  }
}
.giftSentIconStack{
  position: relative;
  width: 148px;
  height: 148px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.giftSentGlow{
  position: absolute;
  border-radius: 50%;
  pointer-events: none;
  filter: blur(36px);
}
.giftSentGlow--base{
  inset: -28px;
  opacity: 0.95;
}
.giftSentGlow--clash{
  inset: -36px;
  opacity: 0;
  mix-blend-mode: screen;
}
.giftSentOverlay.isActive .giftSentGlow--clash{
  animation: giftGlowClash 2650ms ease-in-out forwards;
}
@keyframes giftGlowClash{
  0%, 100%{ opacity: 0.25; transform: scale(0.88); }
  14%{ opacity: 1; transform: scale(1.22); }
  32%{ opacity: 0.5; transform: scale(1.02); }
  52%{ opacity: 0.92; transform: scale(1.16); }
  72%{ opacity: 0.45; transform: scale(1.08); }
}
.giftSentStage--mic .giftSentGlow--base{
  background: rgba(242, 244, 248, 0.32);
}
.giftSentStage--mic .giftSentGlow--clash{
  background: rgba(186, 198, 220, 0.38);
}
.giftSentStage--mic .giftSentSvg,
.giftSentStage--mic .giftTierSvg--mic{
  color: #F2F4F8;
  filter: drop-shadow(0 0 12px rgba(242, 244, 248, 0.45));
}
.giftSentStage--pulse .giftSentGlow--base{
  background:
    radial-gradient(circle at 38% 50%, rgba(124, 92, 255, 0.38) 0%, transparent 68%),
    radial-gradient(circle at 64% 42%, rgba(34, 230, 210, 0.28) 0%, transparent 62%);
}
.giftSentStage--pulse .giftSentGlow--clash{
  background:
    radial-gradient(circle at 55% 48%, rgba(34, 230, 210, 0.42) 0%, transparent 58%),
    radial-gradient(circle at 35% 52%, rgba(124, 92, 255, 0.34) 0%, transparent 58%);
}
.giftSentStage--star .giftSentGlow--base{
  background: rgba(255, 209, 102, 0.38);
}
.giftSentStage--star .giftSentGlow--clash{
  background: rgba(255, 159, 28, 0.36);
}
.giftSentOverlay.isActive .giftSentStage--star .giftSentIconStack{
  animation: giftStarReveal 980ms cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
@keyframes giftStarReveal{
  0%{ transform: rotate(-32deg) scale(0.62); opacity: 0.4; }
  50%{ transform: rotate(16deg) scale(1.16); opacity: 1; }
  100%{ transform: rotate(0deg) scale(1); opacity: 1; }
}
.giftSentOverlay.isActive .giftSentStage--pulse .giftSentPulsePath{
  animation: giftPulseDraw 520ms cubic-bezier(0.22, 1, 0.36, 1) forwards;
}
@keyframes giftPulseDraw{
  from{ stroke-dashoffset: 100; opacity: 0.35; }
  8%{ opacity: 1; }
  to{ stroke-dashoffset: 0; opacity: 1; }
}
.giftSentIcon{
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  justify-content: center;
}
.giftSentSvg,
.giftTierSvg--mic,
.giftTierSvg--pulse,
.giftTierSvg--star{
  width: 76px;
  height: 76px;
  display: block;
  fill: none;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.giftSentStage--star .giftSentSvg,
.giftSentStage--star .giftTierSvg--star{
  filter: drop-shadow(0 0 14px rgba(255, 209, 102, 0.42));
}
.giftSentStage--pulse .giftSentSvg,
.giftSentStage--pulse .giftTierSvg--pulse{
