}
.giftSentOverlay--received{
  pointer-events: auto;
}
.giftSentOverlay--received.isReceivedReady .giftSentDim{
  opacity: 1;
  animation: none;
  background: rgba(4, 6, 12, 0.88);
  pointer-events: auto;
}
.giftSentOverlay--received.isReceivedReady .giftSentStage{
  opacity: 1;
  transform: scale(1);
  animation: none;
}
.giftSentOverlay--received.isReceivedReady .giftSentIconStack,
.giftSentOverlay--received.isReceivedReady .giftSentGlow--base,
.giftSentOverlay--received.isReceivedReady .giftSentGlow--clash,
.giftSentOverlay--received.isReceivedReady .giftSentLabel,
.giftSentOverlay--received.isReceivedReady .giftSentSub{
  opacity: 1;
  animation: none;
}
.giftSentOverlay--received.isReceivedReady .giftSentActions{
  display: flex;
  animation: giftSentActionsIn 320ms cubic-bezier(0.22, 1, 0.36, 1) both;
}
@keyframes giftSentActionsIn{
  from{ opacity: 0; transform: translateY(8px); }
  to{ opacity: 1; transform: translateY(0); }
}

