/* --- Profile Pro upsell (below bio on own profile). --- */
.profileProBanner{
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  /* Match profileSongsBlock / post card horizontal edges (aura 8px vs feed 6px). */
  width: calc(100% + ((var(--profile-songs-block-pad-x, 6px) - var(--profile-aura-pad-x, 8px)) * 2));
  max-width: var(--profile-pro-banner-max-w, none);
  margin:
    12px
    calc(var(--profile-songs-block-pad-x, 6px) - var(--profile-aura-pad-x, 8px))
    6px;
  padding: 12px 14px 12px 14px;
  border-radius: 16px;
  text-decoration: none;
  color: inherit;
  overflow: hidden;
  border: 1px solid rgba(124, 92, 255, 0.42);
  background:
    radial-gradient(130% 120% at 100% 0%, rgba(124, 92, 255, 0.28), transparent 58%),
    radial-gradient(90% 80% at 0% 100%, rgba(35, 213, 171, 0.14), transparent 55%),
    linear-gradient(135deg, rgba(124, 92, 255, 0.14), rgba(18, 22, 36, 0.92) 48%, rgba(35, 213, 171, 0.08));
  box-shadow:
    0 0 0 1px rgba(255, 255, 255, 0.04) inset,
    0 10px 28px rgba(8, 10, 18, 0.42),
    0 0 24px rgba(124, 92, 255, 0.12);
  transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}
.profileProBanner::before{
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  background: linear-gradient(120deg, rgba(255, 255, 255, 0.1), transparent 42%, rgba(35, 213, 171, 0.08));
  opacity: 0.55;
}
.profileProBanner:active{
  transform: scale(0.985);
}
.profileProBanner:focus-visible{
  outline: 2px solid rgba(124, 92, 255, 0.85);
  outline-offset: 2px;
}
.profileProBanner[hidden]{ display: none; }
