}
.callingCardChip[data-state="playing"] .callingCardChipWave > span:nth-child(1){ animation-delay: 0ms; }
.callingCardChip[data-state="playing"] .callingCardChipWave > span:nth-child(2){ animation-delay: 80ms; }
.callingCardChip[data-state="playing"] .callingCardChipWave > span:nth-child(3){ animation-delay: 160ms; }
.callingCardChip[data-state="playing"] .callingCardChipWave > span:nth-child(4){ animation-delay: 240ms; }
.callingCardChip[data-state="playing"] .callingCardChipWave > span:nth-child(5){ animation-delay: 200ms; }
.callingCardChip[data-state="playing"] .callingCardChipWave > span:nth-child(6){ animation-delay: 120ms; }
.callingCardChip[data-state="playing"] .callingCardChipWave > span:nth-child(7){ animation-delay: 60ms; }
