/* Friends — floating + (top-right; stays clear of mini-player) */
.friendsComposeFabRoot{
  position: fixed;
  top: calc(env(safe-area-inset-top, 0px) + 10px);
  right: 14px;
  z-index: 70;
  pointer-events: none;
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
  transition: opacity 200ms ease, visibility 200ms ease;
}
body[data-route="friends"], body.friendsFeedActive #friendsComposeFabRoot{
  display: none !important;
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
}
body.friendsComposeSheetOpen #friendsComposeFabRoot,
body.trackSheetOpen #friendsComposeFabRoot{
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
}
.friendsComposeFabRoot .friendsComposeFab{
  pointer-events: auto;
}
.friendsComposeFab{
  position: relative;
  width: 52px;
  height: 52px;
  border: none;
  border-radius: 999px;
  padding: 0;
  background: rgba(8, 10, 18, 0.94);
  color: rgba(248, 250, 255, 0.96);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  box-shadow:
    0 8px 26px rgba(0, 0, 0, 0.38),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
  transition: transform 160ms ease, box-shadow 200ms ease, background 200ms ease;
}
.friendsComposeFabRing{
  position: absolute;
  inset: -2px;
  border-radius: inherit;
  pointer-events: none;
  padding: 2px;
  background: linear-gradient(135deg, #23d5ab 0%, #4ad6c8 28%, #7c5cff 72%, #b78bff 100%);
  -webkit-mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
          mask:
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
          mask-composite: exclude;
  box-shadow:
    0 0 18px -4px rgba(35, 213, 171, 0.28),
    0 0 20px -4px rgba(124, 92, 255, 0.36);
}
.friendsComposeFabIco{
  position: relative;
  z-index: 1;
}
.friendsComposeFab:active{
  transform: scale(0.94);
}
.friendsComposeFab[aria-expanded="true"]{
  background: rgba(124, 92, 255, 0.28);
}

/* Friends compose bottom sheet */
.friendsComposeSheet{
  --friends-compose-sheet-gap: max(8px, env(safe-area-inset-bottom, 0px));
  --friends-keyboard-inset: 0px;
  position: fixed;
  inset: 0;
  z-index: 121;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  box-sizing: border-box;
  padding: 0 10px calc(var(--friends-compose-sheet-gap) + var(--friends-keyboard-inset, 0px));
  pointer-events: none;
  touch-action: none;
  transition: padding-bottom 220ms ease;
}
.friendsComposeSheet.isOpen{ pointer-events: auto; }
.friendsComposeSheet[hidden]{ display: none !important; }
.friendsComposeSheetBackdrop{
  position: absolute;
  inset: 0;
  background:
    radial-gradient(90% 70% at 50% 100%, rgba(124,92,255,0.04), transparent 64%),
    rgba(3, 5, 10, 0.72);
  opacity: 0;
  transition: opacity 260ms ease;
  touch-action: none;
