  display: block;
}
.discoveryRowArtGlow{
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(180deg, transparent 35%, rgba(0,0,0,0.45) 100%);
  pointer-events: none;
}
.discoveryRowArtBadge{
  position: absolute;
  inset: 0;
  margin: auto;
  width: 28px;
  height: 28px;
  border-radius: 999px;
  z-index: 2;
  background: rgba(8,11,18,0.65);
  border: 1px solid rgba(255,255,255,0.30);
  color: #fff;
  font-size: 13px;
  font-weight: 800;
  line-height: 1;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 160ms ease, background-color 160ms ease, border-color 160ms ease, box-shadow 160ms ease;
  -webkit-backdrop-filter: blur(6px);
  backdrop-filter: blur(6px);
  pointer-events: none;
}
.discoveryRowArtBtn:hover .discoveryRowArtBadge,
.discoveryRowArtBtn:focus-visible .discoveryRowArtBadge{
  opacity: 1;
}
.discoveryRow.discoveryRowPlaying .discoveryRowArtBadge{
  opacity: 1;
  background: linear-gradient(180deg, rgba(var(--cover-glow-rgb), 0.52), rgba(var(--cover-glow-rgb), 0.22));
  border-color: rgba(255,255,255,0.45);
  box-shadow: 0 6px 18px rgba(var(--cover-glow-rgb), 0.22);
}
.discoveryRow.discoveryRowActive .discoveryRowArtBadge{
  opacity: 1;
}
.discoveryRow.discoveryRowLoading .discoveryRowArtBadge{
  opacity: 1;
}
.discoveryRowEq{
  flex: 0 0 auto;
  display: none;
  align-items: flex-end;
  gap: 3px;
  height: 18px;
  margin-right: 4px;
}
.discoveryRow.discoveryRowPlaying .discoveryRowEq{
  display: inline-flex;
}
.discoveryRowEq span{
  display: block;
  width: 3px;
  height: 100%;
  border-radius: 2px;
  background: linear-gradient(180deg, rgba(var(--cover-glow-rgb), 0.85), rgba(var(--cover-glow-rgb), 0.35));
  transform-origin: bottom;
  animation: discoveryRowEqBar 1.05s ease-in-out infinite;
}
.discoveryRowEq span:nth-child(2){ animation-delay: 0.18s; }
.discoveryRowEq span:nth-child(3){ animation-delay: 0.36s; }
@keyframes discoveryRowEqBar{
  0%, 100%{ transform: scaleY(0.35); }
  50%{ transform: scaleY(1); }
}
.discoveryRowMid{
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.discoveryRowTitle{
  font-size: 15px;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: #f0f4ff;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.discoveryRowMeta{
  font-size: 12px;
  color: rgba(223,231,251,0.58);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.discoveryRowMeta + .remixAttributionLine,
.discoveryRowMeta + .mashupAttributionLine,
.discoveryRowMeta + .challengeAttributionLine,
.discoveryRowMeta + .discoveryRowStyle{
  margin-top: -1px;
}
.discoveryRowStyle{
  display: block;
  margin-top: 2px;
  max-width: 100%;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.35;
  color: var(--song-row-desc-color);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.discoveryRowMeta + .releaseCaptionLine,
.remixAttributionLine + .releaseCaptionLine,
.mashupAttributionLine + .releaseCaptionLine,
.challengeAttributionLine + .remixAttributionLine,
.challengeAttributionLine + .mashupAttributionLine,
.challengeAttributionLine + .releaseCaptionLine{
  margin-top: -1px;
}
.discoveryRowSide{
  flex: 0 0 auto;
  width: auto;
  min-width: 40px;
  margin: 0 4px 0 0;
  align-self: center;
  border-radius: 0;
  border: 0;
  background: transparent;
  color: rgba(232,238,247,0.45);
  font-size: 22px;
  font-weight: 800;
  line-height: 1;
  padding: 8px 4px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: color 0.18s ease, opacity 0.18s ease;
}
.discoveryRowSide:hover{
  color: rgba(232,238,247,0.92);
}
.discoveryRowSide:focus-visible{
  outline: 2px solid rgba(124,92,255,0.55);
  outline-offset: 2px;
}
.discoveryRowMain:focus-visible{
  outline: 2px solid rgba(124,92,255,0.55);
  outline-offset: 2px;
  border-radius: 16px;
}
.discoveryStudioFooter{
  margin-top: 22px;
}
@media (prefers-reduced-motion: reduce){
  .discoveryRow,
  .discoverySpotCardWrap,
  .discoverySpotCard,
  .discoverySkeletonArt,
  .discoverySkeletonLine,
  .discoverySkeletonMoreLabel,
  .discoverySkeletonSpotFill,
  .discoveryRefreshBtn.isRefreshing .discoveryRefreshIco{
    animation: none !important;
  }
  .discoveryRowEq span,
  .discoverySpotCardEq span{
    animation: none !important;
  }
  .discoveryRow,
  .discoverySpotCardWrap,
  .discoverySpotCard{ opacity: 1; transform: none; }
}

/* ============================================================
 * Search page — magazine of remixable occasion shelves.
 *   One sticky search bar, lazy people strip when relevant,
 *   horizontal shelves of "make it yours" templates, and a
 *   bottom sheet that pre-fills the Create page with the
 *   chosen template's style/lyrics/title.
 * ============================================================ */

.searchPage{
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding: 12px 0 28px;
  width: 100%;
  min-width: 0;
}

.searchBarWrap{
  position: sticky;
  top: 0;
  z-index: 5;
  padding: 6px 0 10px;
  background: linear-gradient(180deg, rgba(11,13,18,0.96) 70%, rgba(11,13,18,0));
}
.searchBar{
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  height: 52px;
  padding: 0 14px;
  border-radius: 16px;
  background: rgba(255,255,255,0.05);
  border: 1px solid rgba(255,255,255,0.10);
  transition: border-color 180ms ease, background-color 180ms ease;
  width: 100%;
}
.searchBar:focus-within{
  border-color: rgba(255,255,255,0.22);
  background: rgba(255,255,255,0.08);
}
.searchBarIcon{
  flex: 0 0 auto;
  color: rgba(232,238,247,0.7);
}
.searchBarInput{
  flex: 1 1 0;
  min-width: 0;
  width: 100%;
  background: transparent;
  border: 0;
  outline: 0;
  color: #e8eef7;
  font-size: 17px;
  font-weight: 500;
  letter-spacing: -0.01em;
  caret-color: #7c5cff;
}
.searchBarInput::placeholder{
  color: transparent;
}
/* The pill shows focus via its own :focus-within border; suppress the global
   purple input focus ring so no frame appears inside the container. */
.searchBarInput:focus{
  box-shadow: none;
  border-color: transparent;
}
.searchBarHint{
  position: absolute;
  left: 14px;
  top: 50%;
  transform: translateY(-50%);
  color: rgba(232,238,247,0.42);
  font-size: 17px;
  letter-spacing: -0.01em;
  pointer-events: none;
  transition: opacity 220ms ease, transform 220ms ease;
}
.searchBar.hasValue .searchBarHint{ opacity: 0; }
.searchBarHint.swapping{ opacity: 0; transform: translateY(calc(-50% + 8px)); }
.searchBarClear{
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 999px;
  background: rgba(255,255,255,0.08);
  border: 0;
  color: rgba(232,238,247,0.85);
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.searchBarClear[hidden]{ display: none !important; }

/* People strip ---------------------------------------------- */
.searchPeopleStrip{
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.searchPeopleStrip[hidden],
.searchEmpty[hidden],
.searchRemixSheet[hidden]{
  display: none !important;
}
.searchPeopleHead{
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(232,238,247,0.5);
}
.searchPeopleRow{
  display: flex;
  gap: 14px;
  overflow-x: auto;
  scrollbar-width: none;
  padding: 2px 2px 6px;
  -ms-overflow-style: none;
}
.searchPeopleRow::-webkit-scrollbar{ display: none; }
.searchPersonCard{
  flex: 0 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  width: 76px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  background: transparent;
  border: 0;
  padding: 0;
  color: inherit;
}
.searchPersonAvatar{
  width: 64px;
  height: 64px;
  border-radius: var(--nabad-squircle-radius);
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.08);
  object-fit: cover;
}
.searchPersonText{
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  min-width: 0;
  max-width: 76px;
}
.searchPersonName{
  font-size: 12px;
  font-weight: 700;
  color: #e8eef7;
  max-width: 76px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.searchPersonHandle{
  font-size: 11px;
  color: rgba(232,238,247,0.52);
  max-width: 76px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* Shelves --------------------------------------------------- */
.searchShelves{
  display: flex;
  flex-direction: column;
  gap: 22px;
}
.searchShelf{
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-width: 100%;
  overflow: hidden;
}
.searchShelf.isDimmed{
  opacity: 0.32;
  filter: saturate(0.7);
  transition: opacity 220ms ease, filter 220ms ease;
}
.searchShelfHead{
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 0 2px;
}
.searchShelfTitle{
  margin: 0;
  font-size: 17px;
  font-weight: 800;
  letter-spacing: -0.01em;
  color: #e8eef7;
}
.searchShelfRow{
  /* Same pattern as `.profileTopWeekScroll`, which is the proven-working
     horizontal carousel in the app. The combination of `overflow-y: hidden`
     and `scroll-snap-type` on iOS WKWebView is what *unlocks* the touch
     gesture; without them, the page absorbs the swipe. */
  display: flex;
  gap: 14px;
  overflow-x: auto;
  overflow-y: hidden;
  -webkit-overflow-scrolling: touch;
  scroll-snap-type: x mandatory;
  padding: 2px 2px 12px;
  scrollbar-width: none;
  -ms-overflow-style: none;
  max-width: 100%;
}
.searchShelfRow::-webkit-scrollbar{ display: none; }
.searchPoster{
  flex: 0 0 168px;
  width: 168px;
  height: 230px;
  position: relative;
  border-radius: 18px;
  overflow: hidden;
  cursor: pointer;
  scroll-snap-align: start;
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.08);
  padding: 0;
  -webkit-tap-highlight-color: transparent;
  transition: border-color 200ms ease;
}
.searchPoster:hover, .searchPoster:focus-visible{
  border-color: rgba(255,255,255,0.18);
}
.searchPosterArt{
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.searchPosterArt[data-placeholder="1"]{
  background:
    radial-gradient(120% 80% at 0% 0%, rgba(124,92,255,0.55), transparent 60%),
    radial-gradient(120% 80% at 100% 100%, rgba(35,213,171,0.42), transparent 65%),
    linear-gradient(160deg, #1a1f2e 0%, #0f1320 100%);
  filter: saturate(0.95);
}
.searchPosterVignette{
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(0,0,0,0) 38%, rgba(0,0,0,0.78) 100%);
  pointer-events: none;
}
.searchPosterChip{
  position: absolute;
  top: 10px;
  left: 10px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(11,13,18,0.6);
  border: 1px solid rgba(255,255,255,0.14);
  color: rgba(248,250,255,0.94);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.searchPosterText{
  position: absolute;
  left: 12px;
  right: 12px;
  bottom: 12px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.searchPosterTitle{
  font-size: 15px;
  font-weight: 800;
  letter-spacing: -0.01em;
  color: #fff;
  line-height: 1.2;
  text-shadow: 0 1px 2px rgba(0,0,0,0.55);
}
.searchPosterSub{
  font-size: 11px;
  font-weight: 600;
  color: rgba(255,255,255,0.78);
  text-shadow: 0 1px 2px rgba(0,0,0,0.5);
}
.searchPosterCta{
  display: inline-flex;
  align-items: center;
  gap: 4px;
  margin-top: 6px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.9);
}
.searchPosterCta::after{
  content: "→";
  font-size: 12px;
  line-height: 1;
  transform: translateY(-0.5px);
}

/* Empty state ----------------------------------------------- */
.searchEmpty{
  padding: 26px 12px;
  text-align: center;
  color: rgba(232,238,247,0.6);
}
.searchEmptyTitle{
  margin: 0 0 6px;
  font-size: 15px;
  font-weight: 800;
  color: #e8eef7;
}
.searchEmptyHint{
  margin: 0;
  font-size: 13px;
}

/* Discover inline search (TikTok-style overlay on Discover tab) */
.discoveryPaneStudio.isSearchOpen .discoveryMainContent{
  display: none;
}
.discoverySearchPanel{
  display: none;
  flex-direction: column;
  min-height: 0;
  animation: discoverySearchIn 220ms ease;
}
.discoveryPaneStudio.isSearchOpen .discoverySearchPanel{
  display: flex;
}
.discoverySearchPanelInner{
  display: flex;
  flex-direction: column;
  gap: 12px;
  min-height: 0;
}
.discoverySearchBarWrap{
  position: sticky;
  top: 0;
  z-index: 6;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 2px 0 8px;
  background: linear-gradient(180deg, rgba(11,13,18,0.98) 72%, rgba(11,13,18,0));
}
.discoverySearchClose svg{
  width: 20px;
  height: 20px;
  flex-shrink: 0;
}
/* Back chevron lives in the Discover header next to the title (same flow as
   Messages: [back] Title). It only appears while search is open, and the
   search/magnifier button hides so the header reads as a standard back row. */
.discoveryStudioHead .discoverySearchClose{
  display: none;
  margin-top: 2px;
}
.discoveryPaneStudio.isSearchOpen .discoveryStudioHead .discoverySearchClose{
  display: inline-flex;
}
.discoveryPaneStudio.isSearchOpen #discoverySearchBtn{
  display: none;
}
.discoverySearchBarWrap .searchBar{
  flex: 1 1 0;
  min-width: 0;
  height: 48px;
  border-radius: 14px;
  background: rgba(255,255,255,0.06);
  border-color: rgba(255,255,255,0.12);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.04);
}
.discoverySearchResults{
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding-bottom: 24px;
}
.searchSectionHead{
  display: flex;
  align-items: baseline;
  gap: 8px;
  padding: 0 2px 4px;
}
.searchTracksSection[hidden]{ display: none !important; }
.searchTracksGrid{
  display: block;
  padding: 4px 0 12px;
  min-width: 0;
}
.searchTracksList{
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 0 2px;
}
.searchTracksList .discoverFeedSongRow{
  --feed-song-art-size: 52px;
  border-radius: 14px;
  border: 1px solid rgba(255,255,255,0.08);
  background: rgba(255,255,255,0.04);
  overflow: hidden;
}
.searchTracksList .discoverFeedSongRow + .discoverFeedSongRow::before{
  display: none;
}
.searchTracksList .discoverFeedSongRowPlay{
  padding: 10px 12px 10px 10px;
  gap: 12px;
}
.searchTracksList .discoverFeedSongArt{
  border-radius: 10px;
}
html[data-theme="light"] .searchTracksList .discoverFeedSongRow{
  border-color: rgba(15,23,42,0.08);
  background: rgba(15,23,42,0.03);
}
.searchTracksLoading{
  grid-column: 1 / -1;
  padding: 18px 8px;
  text-align: center;
  color: rgba(232,238,247,0.55);
  font-size: 14px;
}
.searchTrendingLabel{
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(232,238,247,0.5);
  padding: 0 2px;
}
.searchTrendingLabel[hidden]{ display: none !important; }
.searchShelves[hidden]{ display: none !important; }
.searchDiscoverHints{
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.searchDiscoverHints[hidden]{ display: none !important; }
.searchDiscoverHintsLabel{
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(232,238,247,0.5);
  padding: 0 2px;
}
.searchDiscoverHintsRow{
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.searchDiscoverHintChip{
  display: inline-flex;
  align-items: center;
  max-width: 100%;
  padding: 8px 14px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,0.10);
  background: rgba(255,255,255,0.05);
  color: rgba(232,238,247,0.88);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.searchDiscoverHintChip:active{ transform: scale(0.98); }
html[data-theme="light"] .searchDiscoverHintChip{
  border-color: rgba(15,23,40,0.08);
  background: rgba(15,23,40,0.04);
  color: rgba(15,23,40,0.82);
}
.discoveryRefreshBtn.isActive{
  background: var(--nabad-glass-bg-hover);
  border-color: var(--nabad-glass-border-hover);
  color: var(--nabad-glass-color-hover);
  box-shadow:
    var(--nabad-glass-shadow-hover),
    var(--nabad-glass-inset-top),
    var(--nabad-glass-inset-bottom);
}
html[data-theme="light"] .discoverySearchBarWrap{
  background: linear-gradient(180deg, rgba(236,240,247,0.98) 72%, rgba(236,240,247,0));
}
html[data-theme="light"] .discoverySearchBarWrap .searchBar{
  background: rgba(15,23,40,0.04);
  border-color: rgba(15,23,40,0.08);
}
@keyframes discoverySearchIn{
  from{ opacity: 0; transform: translateY(6px); }
  to{ opacity: 1; transform: translateY(0); }
}

/* Remix bottom sheet ---------------------------------------- */
.searchRemixSheet{
  position: fixed;
  inset: 0;
  z-index: 60;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  pointer-events: none;
}
.searchRemixSheet.isOpen{ pointer-events: auto; }
.searchRemixSheet[hidden]{ display: none !important; }
.searchRemixBackdrop{
  position: absolute;
  inset: 0;
  background: rgba(4,6,12,0.6);
  opacity: 0;
  transition: opacity 220ms ease;
  backdrop-filter: blur(6px);
  -webkit-backdrop-filter: blur(6px);
}
.searchRemixSheet.isOpen .searchRemixBackdrop{ opacity: 1; }
.searchRemixCard{
  position: relative;
  width: 100%;
  max-width: 520px;
  margin: 0 12px;
  border-radius: 22px 22px 18px 18px;
  background: linear-gradient(180deg, #14182a, #0e1220);
  border: 1px solid rgba(255,255,255,0.08);
  padding: 16px 16px calc(20px + env(safe-area-inset-bottom));
  display: flex;
  flex-direction: column;
  gap: 14px;
  transform: translateY(28px);
  opacity: 0;
  transition: transform 240ms cubic-bezier(0.2, 0.8, 0.2, 1), opacity 200ms ease;
  box-shadow: 0 -10px 60px rgba(0,0,0,0.55);
}
.searchRemixSheet.isOpen .searchRemixCard{
  transform: translateY(0);
  opacity: 1;
}
.searchRemixClose{
  position: absolute;
  top: 12px;
  right: 12px;
  width: 30px;
  height: 30px;
  border-radius: 999px;
  background: rgba(255,255,255,0.08);
  border: 0;
  color: #e8eef7;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  -webkit-tap-highlight-color: transparent;
}
.searchRemixCover{
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 10;
  border-radius: 14px;
  overflow: hidden;
  background: #1a1f2e;
}
.searchRemixCover.isPlaceholder{
  background:
    radial-gradient(120% 80% at 0% 0%, rgba(124,92,255,0.55), transparent 60%),
    radial-gradient(120% 80% at 100% 100%, rgba(35,213,171,0.42), transparent 65%),
    linear-gradient(160deg, #1a1f2e 0%, #0f1320 100%);
}
.searchRemixCover img{
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}
.searchRemixCover img[hidden]{
  display: none;
}
.searchRemixPlay{
  position: absolute;
  right: 12px;
  bottom: 12px;
  width: 44px;
  height: 44px;
  border-radius: 999px;
  background: rgba(255,255,255,0.92);
  color: #12151e;
  border: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  box-shadow: 0 8px 18px rgba(0,0,0,0.4);
}
.searchRemixPlay.isPlaying svg{ display: none; }
.searchRemixPlay.isPlaying::after{
  content: "";
  width: 12px;
  height: 12px;
  background: linear-gradient(90deg, #12151e 5px, transparent 5px 7px, #12151e 7px);
}
.searchRemixMeta{
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.searchRemixOccasion{
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(232,238,247,0.55);
}
.searchRemixTitle{
  margin: 0;
  font-size: 22px;
  font-weight: 900;
  letter-spacing: -0.02em;
