/* =================================================================
 *  Hub reel — vertical scroll-snap, one post per viewport.
 *
 *  The legacy `.hubRow` page-scroll + neighbor-blur layout still
 *  lives in CSS for any non-hub surface that reuses it (the Profile
 *  "All releases" list reuses `.libraryRows` instead, so this is
 *  hub-route only). Everything below is scoped to
 *  body[data-route="hub"] so the rest of the app is untouched.
 *
 *  Layout:
 *    - .app loses its top/side/bottom padding so the reel fills the
 *      device edge-to-edge.
 *    - The brand header is hidden; the Latest / Trending segment
 *      floats over the reel as a translucent pill.
 *    - #hubList becomes the snap-y scroll container, sized to the
 *      viewport minus the bottom tab bar.
 *    - Each .hubReel panel is 100% of the container (one screen at
 *      a time) with three layers: blurred backdrop, centered cover
 *      card, and the action rail + meta footer floated above.
 * ================================================================= */
body[data-route="hub"] .header{ display: none !important; }
/* Page footer (build hint) leaks under the reel as dead space — hide
   it on the hub route. Also lock viewport to 100dvh so nothing else
   pushes the layout taller than the screen. */
body[data-route="hub"] > .app > .footer,
body[data-route="hub"] .footer{ display: none !important; }
body[data-route="hub"] .app{
  padding: 0 !important;
  margin: 0 !important;
  max-width: 100% !important;
  width: 100vw !important;
  height: 100dvh !important;
  min-height: 100dvh !important;
  overflow: hidden !important;
  position: relative;
}
/* Lock the document so scroll only happens inside #hubList */
body[data-route="hub"]{
  overflow: hidden !important;
  height: 100dvh !important;
}
body[data-route="hub"] .card.wide.hubCard{
  padding: 0 !important;
  margin: 0 !important;
  border: 0 !important;
  border-radius: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  position: relative;
}
body[data-route="hub"] .hubTop{
  position: absolute;
  top: env(safe-area-inset-top, 0px);
  left: 0;
  right: 0;
  z-index: 6;
  padding: 10px 14px 10px;
  margin: 0;
  display: flex;
  justify-content: center;
  background: transparent;
  pointer-events: none;
}
body[data-route="hub"] .hubTop > *{ pointer-events: auto; }
/* Centered Nabad wordmark replaces the old Latest/Trending pill on the
   reel. Acts as both branding ("this is Nabad") and an affordance:
   tap = scroll to top. Tiny glass plate keeps it legible over bright
   covers without being a heavy chrome bar. */
body[data-route="hub"] .hubBrand{
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 16px 7px 16px;
  background: rgba(8, 10, 18, 0.42);
  border: 1px solid rgba(255,255,255,0.10);
  border-radius: 999px;
  backdrop-filter: blur(14px) saturate(130%);
  -webkit-backdrop-filter: blur(14px) saturate(130%);
  cursor: pointer;
  position: relative;
  min-height: 36px;
  color: #fff;
  transition: transform 160ms ease, background 200ms ease, border-color 200ms ease;
}
body[data-route="hub"] .hubBrand:hover{
  background: rgba(8, 10, 18, 0.55);
  border-color: rgba(255,255,255,0.16);
}
body[data-route="hub"] .hubBrand:active{
  transform: scale(0.97);
}
body[data-route="hub"] .hubBrandMark{
  width:24px;
  height:24px;
}
body[data-route="hub"] .hubBrandWordmark{
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  line-height: 1;
}
/* The wordmark mirrors the header brand but ~70% size so it sits inside
   the floating pill without dominating the cover. */
body[data-route="hub"] .hubBrandPrimary{
  font-size: 18px;
  letter-spacing: -0.048em;
}
body[data-route="hub"] .hubBrandSecondary{
  font-size: 10px;
  letter-spacing: 0.14em;
  transform: translateY(0);
  color: rgba(231,237,247,0.78);
}
/* Tiny notification dot sits up-right of the wordmark; only visible
   when new posts arrived since the last Hub visit. */
body[data-route="hub"] .hubBrandDot{
  position: absolute;
  top: 5px;
  right: 8px;
  width: 8px;
  height: 8px;
  border-radius: 999px;
  background: linear-gradient(135deg, #67e8f9, #c084fc);
  box-shadow: 0 0 8px rgba(192,132,252,0.55), 0 0 14px rgba(103,232,249,0.32);
}
body[data-route="hub"] #hubAudioHint{
  position: absolute;
  top: calc(env(safe-area-inset-top, 0px) + 64px);
  left: 12px;
  right: 12px;
  z-index: 6;
  padding: 10px 14px;
  border-radius: 14px;
  background: rgba(8,10,18,0.72);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border: 1px solid rgba(124,92,255,0.35);
  text-align: center;
}

/* The reel container itself. Truly full-bleed — the tab bar floats
   over the bottom with its own translucent gradient. */
body[data-route="hub"] #hubList{
  height: 100dvh;
  min-height: 100svh;
  margin: 0;
  padding: 0;
  overflow-y: scroll;
  overflow-x: hidden;
  overscroll-behavior-y: contain;
  scroll-snap-type: y mandatory;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  scrollbar-width: none;
  background: #04060c;
}
body[data-route="hub"] #hubList::-webkit-scrollbar{ display: none; }
/* The mobile tab bar gets a soft gradient backdrop on the reel route
   so the reel can flow under it without losing icon legibility. */
body[data-route="hub"] .mobileTabbar{
  background: linear-gradient(180deg, rgba(4,6,12,0) 0%, rgba(4,6,12,0.85) 60%, rgba(4,6,12,0.95) 100%);
  border-top-color: transparent;
}

/* HARD-RESET every legacy .hubRow.isActive effect on the hub route.
   The new layout owns the entire viewport; the old neighbor-blur +
   focus-pulse + cover-tint backdrop were never meant to coexist with
   a snap reel. We blanket-clear them so the screenshot's "purple
   border while scrolling" cannot reappear. */
body[data-route="hub"] #hubList .hubRow,
body[data-route="hub"] #hubList .hubReel{
  border: 0 !important;
  border-radius: 0 !important;
  padding: 0 !important;
  margin: 0 !important;
  background: transparent !important;
  box-shadow: none !important;
  filter: none !important;
  opacity: 1 !important;
  transform: none !important;
  animation: none !important;
  transition: none !important;
  will-change: auto !important;
  pointer-events: auto !important;
  gap: 0 !important;
}
body[data-route="hub"] #hubList:has(.hubReel.isActive) .hubReel:not(.isActive){
  filter: none !important;
  opacity: 1 !important;
  transform: none !important;
  background: transparent !important;
  border-color: transparent !important;
  box-shadow: none !important;
}
body[data-route="hub"] #hubList .hubReel.isActive,
body[data-route="hub"] #hubList .hubRow.isActive{
  border-color: transparent !important;
  background: transparent !important;
  box-shadow: none !important;
  animation: none !important;
  transform: none !important;
}
body[data-route="hub"] #hubList .hubReel.isActive::before,
body[data-route="hub"] #hubList .hubRow.isActive::before{
  content: none !important;
  background: none !important;
}

/* One panel per viewport, full bleed, snap-aligned. */
.hubReel{
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 100%;
  margin: 0;
  padding: 0;
  border: 0;
  background: transparent;
  scroll-snap-align: start;
  scroll-snap-stop: always;
  isolation: isolate;
  overflow: hidden;
  display: grid;
  grid-template-areas: "stage";
  color: #fff;
}
/* Subtle bottom scrim so the meta strip (creator @, time, title) stays
   legible on bright artwork. No top shade — the Latest/Trending pill
   floats on its own translucent backdrop-filter. */
.hubReel::after{
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(180deg,
    transparent 0%,
    transparent 55%,
    rgba(4,6,12,0.55) 88%,
    rgba(4,6,12,0.80) 100%);
  z-index: 2;
}

/* The cover IS the background now — no separate blurred backdrop layer.
   We keep the element in the DOM (the active-reel observer reads it
   for the blur fallback if/when we ever want it back), but it's hidden
   so it can't paint a second image fetch. */
.hubReelBackdrop{
  display: none !important;
}
.hubReelBackdropVeil{ display: none !important; }

/* Layer 2 — the cover. Now spans the entire viewport. */
.hubReelStage{
  position: relative;
  z-index: 1;
  grid-area: stage;
  display: block;
  padding: 0;
  width: 100%;
  height: 100%;
}
.hubReelCoverBtn{
  position: absolute;
  inset: 0;
  display: block;
  width: 100%;
  height: 100%;
  aspect-ratio: auto;
  padding: 0;
  border: 0;
  margin: 0;
  background: #04060c;
  border-radius: 0;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  overflow: hidden;
  transition: none;
  box-shadow: none;
}
.hubReelCoverBtn:active{ transform: none; }
/* Cover image fills the full viewport. object-fit: cover crops to
   fit — for square artwork on a tall phone we lose ~equal slivers
   top/bottom, which keeps the subject roughly centered. */
.hubReelCoverBtn .hubReelCover,
.hubReelCoverBtn img.hubCover{
  display: block !important;
  position: absolute;
  inset: 0;
  z-index: 1;
  width: 100% !important;
  height: 100% !important;
  aspect-ratio: auto !important;
  object-fit: cover;
  border-radius: 0;
  animation: none !important;
}
.hubReelCoverGlow{ display: none !important; }
.hubReelCoverGlyph{
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 72px;
  line-height: 1;
  color: rgba(255,255,255,0.92);
  text-shadow: 0 8px 20px rgba(0,0,0,0.55);
  pointer-events: none;
  transition: opacity 220ms ease, transform 220ms ease;
  z-index: 2;
}
.hubCoverWrap.isPlaying .hubReelCoverGlyph{
  opacity: 0;
  transform: scale(0.7);
}
/* User requested removing the loading line + equalizer from the reel
   to keep the cover totally clean. Audio still plays; the only on-cover
   affordance is the centered ▶ glyph when paused. */
body[data-route="hub"] .hubReelProgress,
body[data-route="hub"] .hubPlayProgress,
body[data-route="hub"] .hubEq{
  display: none !important;
}

/* Layer 3a — right action rail (Reels pattern). Sits well above the
   floating tab bar so the buttons aren't crowded near the bottom edge
   and the lowest icon (⋯) has comfortable thumb clearance. */
.hubReelRail{
  position: absolute;
  right: 10px;
  /* tab bar ~76px + safe-area + ~70px breathing room. Higher than v1
     because the rail now has 5 items (avatar/like/share/remix/more)
     and the user reported the lowest icon felt cramped against tab. */
  bottom: calc(150px + env(safe-area-inset-bottom, 0px));
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  z-index: 4;
}
.hubReelAvatarBtn{
  width: 46px;
  height: 46px;
  padding: 0;
  border: 2px solid rgba(255,255,255,0.85);
  border-radius: var(--nabad-squircle-radius);
  background: rgba(0,0,0,0.4);
  overflow: hidden;
  cursor: pointer;
}
.hubReelAvatarBtn:active{ transform: scale(0.94); }
.hubReelAvatarImg{
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  border-radius: inherit;
}
.hubReelRailBtn{
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  width: 50px;
  min-width: 50px;
  padding: 4px 0;
  border: 0;
  background: transparent;
  color: #fff;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.02em;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  text-shadow: 0 1px 3px rgba(0,0,0,0.6);
}
.hubReelRailBtn:active{ transform: scale(0.94); }
.hubReelRailBtn .hubLikeHeart,
.hubReelRailBtn .hubReactIcon{
  font-size: 30px;
  line-height: 1;
  filter: drop-shadow(0 2px 6px rgba(0,0,0,0.55));
}
.hubReelRailBtn .hubReactLabel,
.hubReelRailBtn .hubReelRemixLabel{ display: none; }
/* Remix icon — slightly thicker glyph than the share arrow so the
   "loop / re-make" affordance reads at the same visual weight as
   the heart and arrow. */
.hubReelRailBtn .hubReelRemixIcon{
  font-size: 30px;
  line-height: 1;
  font-weight: 900;
  filter: drop-shadow(0 2px 6px rgba(0,0,0,0.55));
}
.hubReelLikeBtn[data-burst="1"] .hubLikeHeart{
  animation: hubReelHeartPop 320ms ease;
  color: #ff4d6d;
}
@keyframes hubReelHeartPop{
  0%   { transform: scale(1); }
  40%  { transform: scale(1.35); }
  100% { transform: scale(1); }
}
.hubReelMoreBtn span{ font-size: 30px; line-height: 1; }

/* Layer 3b — bottom meta strip. Padded UP from the bottom so the
   title clears the floating tab bar (tabbar ~64px + safe-area). */
.hubReelMeta{
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 18px 84px calc(90px + env(safe-area-inset-bottom, 0px)) 18px;
  z-index: 4;
  color: #fff;
  pointer-events: none;
}
.hubReelMeta > *{ pointer-events: auto; }
.hubReelCreatorRow{
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-bottom: 6px;
  font-size: 13px;
  font-weight: 700;
  color: rgba(255,255,255,0.92);
  flex-wrap: wrap;
}
.hubReelCreator{
  color: #fff;
  font-weight: 800;
  text-decoration: none;
}
.hubReelTitle{
  margin: 0 0 4px;
  font-size: 22px;
  font-weight: 800;
  line-height: 1.18;
  letter-spacing: -0.01em;
  text-shadow: 0 2px 12px rgba(0,0,0,0.6);
  word-break: break-word;
}
.hubReelProofChip{
  border: 0;
  background: rgba(255,255,255,0.14);
  color: rgba(255,255,255,0.9);
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  cursor: pointer;
}
.hubReelRemixLine,
.hubReelTemplateLine{
  font-size: 11px;
  color: rgba(232,238,247,0.78);
  letter-spacing: 0.02em;
  margin-top: 2px;
}

/* The "Load more" pill at the end of the feed gets its own snap
   panel so it doesn't share a screen with a real post. */
.hubReelLoadMoreWrap{
  scroll-snap-align: start;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 100%;
  height: 100%;
  min-height: 100%;
  padding: 24px;
}

/* Compact "More" popover — anchors right next to the ⋯ button so it
   looks attached, not detached. Overrides the base .libMenu/.hubMoreMenu
   rules (which assume top-right anchoring inside a card with min-width
   170px) to force a small, content-tight rectangle for the reel
   layout. */
.hubReelMoreMenu{
  position: absolute;
  right: 70px;
  /* Rail's More button sits at bottom: calc(150px + safe-area); the
     popover lines up with it horizontally and sits just to its left. */
  bottom: calc(150px + env(safe-area-inset-bottom, 0px));
  top: auto;
  left: auto;
  z-index: 6;
  min-width: 0;
  width: max-content;
  max-width: 220px;
  padding: 6px;
  gap: 2px;
  border-radius: 10px;
  background: rgba(10, 14, 24, 0.96);
  border: 1px solid rgba(255,255,255,0.10);
  box-shadow: 0 14px 30px rgba(0,0,0,0.5);
}
.hubReelMoreMenu .ghost{
  padding: 8px 12px;
  font-size: 13.5px;
  font-weight: 700;
  min-height: 0;
  border: 0;
  background: transparent;
  border-radius: 8px;
  justify-content: flex-start;
  text-align: left;
  white-space: nowrap;
}
.hubReelMoreMenu .ghost:hover,
.hubReelMoreMenu .ghost:active{
  background: rgba(255,255,255,0.06);
  border-color: transparent;
}

/* iOS still throws a tiny extra paint at the snap edges — kill the
   default user-select highlight inside reels so a long-press on the
   meta doesn't show a text selection rectangle over the cover. */
.hubReel,
.hubReel * {
  -webkit-user-select: none;
  user-select: none;
}
.hubReelTitle,
.hubReelCreator,
.hubReelCreatorRow{
  -webkit-user-select: text;
  user-select: text;
}

/* Reel-style loading skeleton — one full-bleed panel that mirrors
   the production reel silhouette (centered square cover, right-rail
   action dots, bottom meta lines). When the first cloud refresh
   lands the skeleton is replaced by real reel articles in the same
   layout, so the swap is invisible to the eye. */
/* Reel skeleton matches the live full-bleed reel silhouette so the
   swap to real data is invisible:
     - Cover = full-screen shimmering panel (was: a centered square)
     - Right rail = 5 dots (avatar/like/share/remix/more) positioned
       at the same bottom: 150px + safe-area as the live rail
     - Bottom meta lines positioned at 90px + safe-area, matching the
       live reel's meta strip
   No more centered square + blurred backdrop — the live layout doesn't
   use that anymore, and showing it during load made the transition
   feel like two different screens. */
.hubReelSkeleton{
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 100%;
  background: #04060c;
  scroll-snap-align: start;
  overflow: hidden;
}
.hubReelSkelCover{
  position: absolute;
  inset: 0;
  background: linear-gradient(
    180deg,
    rgba(255,255,255,0.05) 0%,
    rgba(255,255,255,0.12) 50%,
    rgba(255,255,255,0.05) 100%
  );
  background-size: 100% 220%;
  animation: hubReelSkelShimmer 1.6s ease-in-out infinite;
}
.hubReelSkelRail{
  position: absolute;
  right: 10px;
  bottom: calc(150px + env(safe-area-inset-bottom, 0px));
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 16px;
  z-index: 2;
}
.hubReelSkelDot{
  display: block;
  width: 46px;
  height: 46px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(255,255,255,0.06) 0%, rgba(255,255,255,0.16) 50%, rgba(255,255,255,0.06) 100%);
  background-size: 200% 100%;
  animation: hubReelSkelShimmer 1.4s ease-in-out infinite;
}
.hubReelSkelMeta{
  position: absolute;
  left: 18px;
  right: 84px;
  bottom: calc(90px + env(safe-area-inset-bottom, 0px));
  display: flex;
  flex-direction: column;
  gap: 8px;
  z-index: 2;
}
.hubReelSkelLineSm,
.hubReelSkelLineLg{
  display: block;
  background: linear-gradient(90deg, rgba(255,255,255,0.06) 0%, rgba(255,255,255,0.16) 50%, rgba(255,255,255,0.06) 100%);
  background-size: 200% 100%;
  animation: hubReelSkelShimmer 1.4s ease-in-out infinite;
  border-radius: 6px;
}
.hubReelSkelLineSm{ height: 10px; width: 40%; }
.hubReelSkelLineLg{ height: 18px; width: 60%; border-radius: 7px; }
/* Nabad-aesthetic loading pill. Only fades in after 4s so fast networks
   (incl. typical WiFi) never see it — it exists for the user who's
   genuinely waiting on a slow Supabase round-trip. Glassy gradient
   chip with an animated mini-equalizer matches the rest of the
   music-themed UI. */
.hubReelSkelHint{
  position: absolute;
  left: 50%;
  top: 30%;
  transform: translate(-50%, -50%);
  margin: 0;
  padding: 9px 14px 9px 11px;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-size: 12.5px;
  font-weight: 500;
  letter-spacing: 0.02em;
  color: rgba(255,255,255,0.94);
  background: linear-gradient(
    135deg,
    rgba(34, 211, 238, 0.18) 0%,
    rgba(99, 102, 241, 0.16) 50%,
    rgba(168, 85, 247, 0.20) 100%
  );
  border: 1px solid rgba(255,255,255,0.14);
  border-radius: 999px;
  box-shadow:
    0 8px 28px rgba(0,0,0,0.34),
    0 0 22px rgba(34, 211, 238, 0.22),
    inset 0 1px 0 rgba(255,255,255,0.08);
  backdrop-filter: blur(14px) saturate(130%);
  -webkit-backdrop-filter: blur(14px) saturate(130%);
  white-space: nowrap;
  opacity: 0;
  z-index: 3;
  animation: hubReelSkelHintIn 0.55s cubic-bezier(.2,.7,.2,1) 4s forwards;
  pointer-events: none;
}
.hubReelSkelHintText{
  background: linear-gradient(90deg, #a5f3fc 0%, #d8b4fe 100%);
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: transparent;
}
.hubReelSkelHintBars{
  display: inline-flex;
  align-items: flex-end;
  gap: 2px;
  width: 14px;
  height: 13px;
}
.hubReelSkelHintBars i{
  display: block;
  width: 3px;
  background: linear-gradient(180deg, #67e8f9 0%, #c084fc 100%);
  border-radius: 2px;
  transform-origin: 50% 100%;
  animation: hubReelHintBar 1.1s ease-in-out infinite;
}
.hubReelSkelHintBars i:nth-child(1){ height: 55%; animation-delay: 0s; }
.hubReelSkelHintBars i:nth-child(2){ height: 100%; animation-delay: 0.16s; }
.hubReelSkelHintBars i:nth-child(3){ height: 72%; animation-delay: 0.32s; }
@keyframes hubReelHintBar{
  0%, 100% { transform: scaleY(0.4); }
  50%      { transform: scaleY(1); }
}
@keyframes hubReelSkelHintIn{
  to { opacity: 1; transform: translate(-50%, -50%) scale(1); }
  from { opacity: 0; transform: translate(-50%, -50%) scale(0.92); }
}
@keyframes hubReelSkelShimmer{
  0%   { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}
@media (prefers-reduced-motion: reduce){
  .hubReelSkelCover,
  .hubReelSkelDot,
  .hubReelSkelLineSm,
  .hubReelSkelLineLg{
    animation: none !important;
  }
  .hubReelSkelHint{
    animation: none !important;
    opacity: 1;
    transform: translate(-50%, -50%);
  }
  .hubReelSkelHintBars i{
    animation: none !important;
    transform: scaleY(0.7);
  }
}

