#nabadProducerRoot{
  flex: 1 1 auto;
  min-height: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  height: 100%;
}

.nabadProducerShell{
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  width: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}
.nabadProducerHero{
  position: relative;
  flex-shrink: 0;
  width: 100%;
  padding: calc(env(safe-area-inset-top, 0px) + 8px) 16px 14px;
  overflow: hidden;
}
.nabadProducerHeroInner{
  position: relative;
  z-index: 1;
  max-width: 720px;
  margin: 0 auto;
}
.nabadProducerAura{
  pointer-events: none;
  position: absolute;
  inset: 0;
  background:
    radial-gradient(140% 120% at 0% -30%, rgba(35,211,171,0.32), transparent 62%),
    radial-gradient(120% 100% at 100% -20%, rgba(168,130,255,0.28), transparent 56%),
    linear-gradient(180deg, rgba(10,16,28,0.55) 0%, rgba(6,8,14,0.18) 100%);
  z-index: 0;
}
.nabadProducerHero::after{
  content: "";
  pointer-events: none;
  position: absolute;
  inset: auto 0 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(35,211,171,0.35), rgba(168,130,255,0.35), transparent);
  z-index: 2;
}
.nabadProducerHead,
.nabadProducerProgress{
  position: relative;
  z-index: 1;
}
.nabadProducerStage{
  flex: 1 1 auto;
  min-height: 0;
  overflow-x: hidden;
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  touch-action: pan-y;
  padding: 10px 14px calc(var(--nabad-producer-dock-h, 132px) + 12px);
  scroll-padding-bottom: calc(var(--nabad-producer-dock-h, 132px) + 12px);
}
.nabadProducerChat{
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.nabadProducerScrollAnchor{
  width: 100%;
  height: 1px;
  flex-shrink: 0;
  pointer-events: none;
  visibility: hidden;
}
.nabadProducerDock{
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 6;
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 10px 14px calc(10px + env(safe-area-inset-bottom, 0px));
  border-top: 1px solid rgba(255,255,255,0.08);
  background: rgba(6,8,14,0.94);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
  box-sizing: border-box;
}
body.nabadProducerKeyboardOpen[data-route="nabad-producer"] .nabadProducerDock{
  bottom: var(--nabad-producer-keyboard-inset, 0px);
  padding-bottom: 10px;
}
body.nabadProducerKeyboardOpen[data-route="nabad-producer"] #nabadProducerRoot{
  padding-bottom: var(--nabad-producer-keyboard-inset, 0px);
  box-sizing: border-box;
}
.nabadProducerHead{
