  align-items: center;
  gap: 10px;
  flex-shrink: 0;
  padding-bottom: 10px;
}
.nabadProducerBack{
  flex-shrink: 0;
  margin-top: 2px;
}
.nabadProducerHeadMark{
  flex-shrink: 0;
