  gap: 8px;
}
.nabadProducerStepPill{
  display: inline-flex;
  padding: 2px 8px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
  color: rgba(235,225,255,0.95);
  background: rgba(124,92,255,0.22);
  border: 1px solid rgba(168,130,255,0.32);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.nabadProducerTrailPill{
  display: inline-flex;
  align-items: center;
  padding: 4px 10px;
  border-radius: 999px;
  font-size: 11px;
  font-weight: 600;
  color: rgba(210,255,248,0.88);
  background: rgba(35,211,171,0.1);
