/* --- Shared Nabad back control --- */
/* Icon-only: drop the glass container (border / fill / blur / shadow) and keep
   just the chevron, while preserving the full-size tap target. Placed after the
   shared glass rules so it wins by source order without !important. */
.nabadBackBtn{
  border: 0;
  background: transparent;
  -webkit-backdrop-filter: none;
          backdrop-filter: none;
  box-shadow: none;
}
.nabadBackBtn:hover{
  background: transparent;
  border-color: transparent;
  box-shadow: none;
}
.nabadBackBtn svg{
  width: 22px;
  height: 22px;
  flex-shrink: 0;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
/* Player mode: bare icon over (often bright) cover art needs a touch of depth —
   a subtle dark halo keeps the chevron readable without a visible container. */
body[data-route="player"] .nabadBackBtn{
  color: #fff;
}
body[data-route="player"] .nabadBackBtn svg{
  filter: drop-shadow(0 1px 5px rgba(0, 0, 0, 0.6));
  stroke-width: 2.2;
}
.userPublicBack.nabadBackBtn:not([hidden]){
  position: absolute;
  top: 0;
  left: 0;
  z-index: 3;
  margin: 0;
}

/* --- Messages (Friends → inbox) --- */
.messagesPage.wide,
section.messagesPage,
.messagesThreadPage.wide,
section.messagesThreadPage{
