  position: absolute;
  inset: -30% -20%;
  background:
    radial-gradient(circle at 35% 40%, rgba(34,211,238,0.16), transparent 52%),
    radial-gradient(circle at 65% 58%, rgba(124,92,255,0.14), transparent 54%),
    radial-gradient(circle at 50% 50%, rgba(251,191,36,0.08), transparent 60%);
  animation: mashupAuraPulse 2.2s ease-in-out infinite;
  pointer-events: none;
}
@keyframes mashupAuraPulse{
  0%, 100% { opacity: 0.55; transform: scale(0.96); }
  50% { opacity: 1; transform: scale(1.04); }
}
.mashupBlendStageInner{
  position: relative;
  width: min(100%, 220px);
  height: 148px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.mashupBlendCovers{
  position: relative;
  width: 196px;
  height: 112px;
}
.mashupBlendCover{
  position: absolute;
  top: 8px;
  width: 96px;
  height: 96px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid rgba(255,255,255,0.14);
  box-shadow:
    0 0 0 1px rgba(251,191,36,0.12),
    0 14px 34px rgba(0,0,0,0.38);
  background: rgba(255,255,255,0.06);
}
.mashupBlendCover--a{
  left: 0;
  animation: mashupCoverSwapA 2.6s ease-in-out infinite;
}
.mashupBlendCover--b{
  right: 0;
  animation: mashupCoverSwapB 2.6s ease-in-out infinite;
}
@keyframes mashupCoverSwapA{
  0%, 100% {
    transform: translate(0, 0) scale(1);
    opacity: 1;
    z-index: 2;
    box-shadow: 0 0 0 2px rgba(34,211,238,0.34), 0 14px 34px rgba(0,0,0,0.38);
