/* --- Mentor (voice lab) — premium “alive” layout --- */
.mentorPage.wide,
section.mentorPage{
  grid-column: 1 / -1;
  width: 100%;
  max-width: 100%;
}
.mentorPage{
  position: relative;
  /* Let page scroll naturally; html already clips horizontal scroll */
  overflow: visible;
  width: 100%;
  max-width: 100%;
  margin: 0 auto;
  /* Symmetric horizontal inset (avoids uneven L/R safe areas reading as a shift) */
  padding-block: 0 52px;
  padding-inline: max(18px, env(safe-area-inset-left, 0px), env(safe-area-inset-right, 0px));
  box-sizing: border-box;
}
@media (max-width: 940px){
  /* One gutter layer: .app goes edge-to-edge; Lab owns horizontal safe-area + padding */
  body[data-route="mentor"] .app{
    padding-left: 0;
    padding-right: 0;
  }
}
.mentorAmbient{
  position: absolute;
  left: 50%;
  transform: translateX(-50%);
  width: 100vw;
  max-width: 100vw;
  top: 0;
  height: min(320px, 46vh);
  pointer-events: none;
  background: radial-gradient(ellipse 120% 90% at 50% -8%, rgba(124, 92, 255, 0.08) 0%, transparent 62%);
  opacity: 0.45;
}
.mentorPageHead{
  display: flex;
