/* =====================================================================
 * Friends feed — X / Twitter style row
 *
 * Single column, avatar pinned left, everything else (meta, body, quoted
 * track card, actions row) stacks in a single column to the right of it.
 * Hairline dividers between posts, no card chrome.
 * =================================================================== */

/* Both selectors target the same element to beat the higher-specificity
 * legacy rules on `.friendsPage .followActStack .followAct` (3 classes)
 * and `.profileActivitiesList.followActStack .followAct` (3 classes).
 * Stacking three classes on the same element gives us specificity 3 and
 * lets source order break the tie in our favour. */
.followAct.followAct--xstyle.followActStack,
.followActStack .followAct.followAct--xstyle,
.followAct--xstyle{
  --feed-song-art-size: 78px;
  --feed-song-card-min-h: 88px;
  --feed-post-gap-after-actions: 12px;
  --feed-post-gap-before-header: 12px;
  --feed-post-divider-color: rgba(255, 255, 255, 0.063);
  --feed-cover-radius: 19px;
  --feed-cover-art-radius: 18px;
  --feed-cover-art-width: min(72%, 253px);
  --feed-header-row-gap: 2px;
  --feed-caption-gap: 6px;
  --feed-art-gap: 10px;
  --feed-repost-banner-gap: 6px;
  --feed-repost-section-gap: 10px;
  --feed-repost-nested-caption-gap: 6px;
  --feed-username-size: 14px;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0;
  padding: 0 14px var(--feed-post-gap-after-actions, 12px);
  border: 0;
  border-bottom: 1px solid var(--feed-post-divider-color, rgba(255, 255, 255, 0.063));
  background: transparent;
  border-radius: 0;
  box-shadow: none;
  overflow: visible;
  box-sizing: border-box;
  min-width: 0;
}
#friendsPage .followActStack .followAct.followAct--xstyle,
#discoveryFollowingList.followActStack .followAct.followAct--xstyle,
.profileActivitiesList.followActStack .followAct.followAct--xstyle,
#profileRepostsList.followActStack .followAct.followAct--xstyle,
#userPublicSongs.followActStack .followAct.followAct--xstyle,
#userPublicRepostsList.followActStack .followAct.followAct--xstyle{
  border-bottom: none;
}
.followActStack .followAct.followAct--xstyle:first-child,
.followAct.followAct--xstyle.followActStack:first-child{
  padding-top: 10px;
}
.followActStack .followAct.followAct--xstyle + .followAct.followAct--xstyle{
  padding-top: var(--feed-post-gap-before-header, 12px);
}
.followActStack .followAct.followAct--xstyle:hover,
.followAct--xstyle:hover{
  background: rgba(255, 255, 255, 0.02);
}
/* Explicit overrides for profile/public feed scopes — match Friends spacing, no dividers. */
.profileActivitiesList.followActStack .followAct.followAct--xstyle,
#discoveryFollowingList.followActStack .followAct.followAct--xstyle,
#profileRepostsList.followActStack .followAct.followAct--xstyle,
#userPublicSongs.followActStack .followAct.followAct--xstyle,
#userPublicRepostsList.followActStack .followAct.followAct--xstyle{
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0;
  --feed-post-gap-before-header: 24px;
  --feed-post-gap-after-actions: 20px;
  --feed-post-pad-x: 14px;
  --feed-cover-radius: 0;
  padding: 0 var(--feed-post-pad-x) var(--feed-post-gap-after-actions, 20px);
  padding-left: var(--feed-post-pad-x);
  padding-right: var(--feed-post-pad-x);
  border: 0;
  border-bottom: none;
  background: transparent;
  border-radius: 0;
  box-shadow: none;
  overflow: visible;
}
.profileActivitiesList.followActStack .followAct.followAct--xstyle + .followAct.followAct--xstyle,
#discoveryFollowingList.followActStack .followAct.followAct--xstyle + .followAct.followAct--xstyle,
#profileRepostsList.followActStack .followAct.followAct--xstyle + .followAct.followAct--xstyle,
#userPublicSongs.followActStack .followAct.followAct--xstyle + .followAct.followAct--xstyle,
#userPublicRepostsList.followActStack .followAct.followAct--xstyle + .followAct.followAct--xstyle{
  padding-top: var(--feed-post-gap-before-header, 24px);
  border-top: 0;
}
.profileActivitiesList.followActStack .followAct.followAct--xstyle:first-child,
#discoveryFollowingList.followActStack .followAct.followAct--xstyle:first-child,
#profileRepostsList.followActStack .followAct.followAct--xstyle:first-child,
#userPublicSongs.followActStack .followAct.followAct--xstyle:first-child,
#userPublicRepostsList.followActStack .followAct.followAct--xstyle:first-child{
  padding-top: 8px;
}
/* And undo the `.followAct--music/--status` left/right padding override
 * that the friends scope applies, which would otherwise pull the row
 * out of alignment with the new grid edges. */
.profileActivitiesList.followActStack .followAct.followAct--xstyle.followAct--music,
.profileActivitiesList.followActStack .followAct.followAct--xstyle.followAct--status,
#discoveryFollowingList.followActStack .followAct.followAct--xstyle.followAct--music,
#discoveryFollowingList.followActStack .followAct.followAct--xstyle.followAct--status,
#profileRepostsList.followActStack .followAct.followAct--xstyle.followAct--music,
#profileRepostsList.followActStack .followAct.followAct--xstyle.followAct--status,
#userPublicSongs.followActStack .followAct.followAct--xstyle.followAct--music,
#userPublicSongs.followActStack .followAct.followAct--xstyle.followAct--status,
#userPublicRepostsList.followActStack .followAct.followAct--xstyle.followAct--music,
#userPublicRepostsList.followActStack .followAct.followAct--xstyle.followAct--status{
  padding-left: var(--feed-post-pad-x, 14px);
  padding-right: var(--feed-post-pad-x, 14px);
}
