  width: 11px;
  height: 11px;
}
.followActRemixTilePlay{
  position: absolute;
  top: 8px;
  right: 8px;
  width: 26px;
  height: 26px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(8,10,18,0.66);
  color: #fff;
}
.followActRemixTileFoot{
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  display: flex;
  flex-direction: column;
  gap: 1px;
  padding: 20px 10px 8px;
  background: linear-gradient(180deg, transparent, rgba(4,6,12,0.90));
  text-align: left;
}
.followActRemixTileTitle{
  color: #fff;
  font-size: 12.5px;
  font-weight: 700;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.followActRemixTileBy{
  color: rgba(232,238,247,0.62);
  font-size: 11px;
  font-weight: 600;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
