/* Actions row — Reply / Like / Plays at the bottom of every post */
.followActActions{
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin: 6px -4px 0;
  padding: 0;
  max-width: 360px;
}
.followActAct{
  appearance: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--icon-muted);
  font: inherit;
  font-size: 12.5px;
  font-weight: 600;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: color 160ms ease, background 160ms ease, transform 160ms ease;
}
.followActAct:hover{
  background: rgba(255, 255, 255, 0.05);
  color: var(--text-primary);
}
.followActAct[data-friends-act="like"]:hover{
  color: var(--danger);
  background: rgba(255, 77, 109, 0.10);
}
.followActAct[data-friends-act="reply"]:hover{
  color: rgba(96, 165, 250, 0.95);
  background: rgba(59, 130, 246, 0.10);
}
.followActAct--stat{
  pointer-events: none;
  color: var(--text-muted);
}
.followActActIco{
  width: 16px;
  height: 16px;
  fill: none;
  stroke: currentColor;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
  display: block;
}
.followActActIco--comment,
.followActActIco--like,
.followActActIco--plays,
.followActActIco--gift,
.followActActIco--analytics{
  width: 22px;
  height: 22px;
  flex-shrink: 0;
  display: block;
  transform-origin: center;
}
.followActActIco--comment,
.followActActIco--like,
.followActActIco--plays,
.followActActIco--gift,
.followActActIco--analytics{
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.followActActIco--comment{
  transform: translateY(0);
}
.followActActIco--like{
  transform: translateY(0);
}
.followActActIco--gift{
  transform: translateY(0);
}
.followActActIco--plays{
  transform: translateY(1px);
}
.followActActIco--analytics{
  transform: translateY(0.5px);
}
.followActAct[data-friends-act="reply"],
.followActAct[data-friends-act="like"],
.followActAct[data-friends-act="plays"],
.followActAct[data-friends-act="gift"],
.followActAct.followActAct--gift,
.followActAct[data-friends-act="analytics"],
.followActAct.followActAct--analytics{
  gap: 5px;
