.followActAct[data-friends-act="like"] .followActActCount,
.followActAct[data-friends-act="plays"] .followActActCount{
  font-size: 12.5px;
}
/* Slightly larger interaction icons in the premium feed cards (Friends, own
   Profile, public profiles). Scoped so Discover and other rows stay at 16px. */
:is(#friendsPage, #discoveryFollowingList, #profileActivitiesList, #profileRepostsList, #userPublicSongs, #userPublicRepostsList) .followActActIco{
  width: 18px;
  height: 18px;
}
:is(#friendsPage, #discoveryFollowingList, #profileActivitiesList, #profileRepostsList, #userPublicSongs, #userPublicRepostsList) .followActActIco--comment,
:is(#friendsPage, #discoveryFollowingList, #profileActivitiesList, #profileRepostsList, #userPublicSongs, #userPublicRepostsList) .followActActIco--like,
:is(#friendsPage, #discoveryFollowingList, #profileActivitiesList, #profileRepostsList, #userPublicSongs, #userPublicRepostsList) .followActActIco--plays,
:is(#friendsPage, #discoveryFollowingList, #profileActivitiesList, #profileRepostsList, #userPublicSongs, #userPublicRepostsList) .followActActIco--gift,
:is(#friendsPage, #discoveryFollowingList, #profileActivitiesList, #profileRepostsList, #userPublicSongs, #userPublicRepostsList) .followActActIco--analytics{
