  font-size: 12.5px;
  font-weight: 600;
  min-width: 8px;
}
.followActActCount:empty{
  display: none;
}
.followActAct.isPulse{
  animation: followActPulse 320ms ease;
}
@keyframes followActPulse {
  0%   { transform: scale(1); }
  50%  { transform: scale(1.18); }
  100% { transform: scale(1); }
}
.followActAct[data-friends-act="like"].isLiked{
