}
html[data-theme="light"] body[data-route="friends"], body.friendsFeedActive .followAct--xstyle .followActActions .followActAct--gift.isGifted,
html[data-theme="light"] body[data-route="friends"], body.friendsFeedActive .followAct--xstyle .followActActions .followActAct[data-friends-act="gift"].isGifted{
