/* =====================================================================
 * Feed reply sheet (X-style thread modal)
 * =================================================================== */

.feedReplySheet{
  position: fixed;
  inset: 0;
  z-index: 110;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  pointer-events: none;
  --feed-reply-keyboard-inset: 0px;
}
.feedReplySheet[aria-hidden="false"]{
  pointer-events: auto;
  padding-bottom: var(--feed-reply-keyboard-inset, 0px);
}
.feedReplySheet[hidden]{
  display: none !important;
}
.feedReplySheetBackdrop{
  position: absolute;
  inset: 0;
  background: rgba(4, 6, 12, 0.66);
  opacity: 0;
  transition: opacity 220ms ease;
}
.feedReplySheet[aria-hidden="false"] .feedReplySheetBackdrop{
  opacity: 1;
}
.feedReplySheetCard{
  position: relative;
  width: 100%;
  max-width: 560px;
  max-height: min(
    88vh,
    calc(100dvh - var(--feed-reply-keyboard-inset, 0px) - 12px - env(safe-area-inset-top, 0px))
  );
  background: linear-gradient(180deg, var(--card), var(--bg));
  border-top-left-radius: 22px;
  border-top-right-radius: 22px;
  border: 1px solid var(--surface-border);
  border-bottom: 0;
  display: flex;
  flex-direction: column;
  padding: 10px 0 0;
  transform: translateY(16px);
  opacity: 0;
  transition: transform 240ms cubic-bezier(0.22, 1, 0.36, 1), opacity 220ms ease;
  padding-bottom: env(safe-area-inset-bottom, 0);
  box-shadow:
    0 -16px 54px rgba(0, 0, 0, 0.46),
    var(--surface-highlight);
}
.feedReplySheet[aria-hidden="false"] .feedReplySheetCard{
  transform: translateY(0);
  opacity: 1;
}
.feedReplySheetGrab{
  width: 38px;
  height: 4px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.18);
  margin: 0 auto 8px;
}
.feedReplySheetHead{
  position: relative;
  padding: 4px 18px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.feedReplySheetClose{
  position: absolute;
  top: -2px;
  right: 10px;
  width: 32px;
  height: 32px;
  border-radius: 999px;
  border: 0;
  background: rgba(255, 255, 255, 0.06);
  color: rgba(232, 238, 247, 0.78);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.feedReplySheetClose:hover{
  background: rgba(255, 255, 255, 0.10);
  color: #fff;
}
.feedReplySheetKicker{
  margin: 0 0 2px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(232, 238, 247, 0.45);
}
.feedReplySheetTitle{
  margin: 0;
  font-size: 17px;
  font-weight: 800;
  color: rgba(248, 250, 255, 0.98);
  letter-spacing: -0.01em;
}
.feedReplySheetSub{
  margin: 4px 0 0;
  font-size: 13px;
  color: rgba(232, 238, 247, 0.62);
