.createOptionsClose{
  flex: 0 0 auto;
  width: 32px;
  height: 32px;
  margin-left: 4px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.06);
  color: rgba(223, 231, 251, 0.7);
  font-size: 20px;
  line-height: 1;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.createOptionsPanel{
  margin-top: 10px;
  padding: 14px 14px 12px !important;
  border-radius: 22px !important;
  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  background:
    radial-gradient(100% 80% at 100% 0%, rgba(35, 213, 171, 0.06), transparent 55%),
    rgba(8, 11, 20, 0.72) !important;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.04) !important;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.createOptionsKicker{
  margin: 0 0 8px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(94, 234, 212, 0.82);
}
.createOptionsPillRow{
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0;
}
.createOptionsPill{
  flex: 1 1 0;
  min-width: 72px;
  min-height: 40px;
  padding: 0 14px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.05);
  color: rgba(238, 244, 255, 0.9);
  font: inherit;
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: background 160ms ease, border-color 160ms ease, box-shadow 160ms ease;
}
.createOptionsPill:hover,
.createOptionsPill:focus-visible{
  border-color: rgba(124, 92, 255, 0.35);
  background: rgba(124, 92, 255, 0.12);
}
.createOptionsPill:active{
  background: rgba(124, 92, 255, 0.2);
}
.createOptionsFine{
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.createOptionsGroup{
  border-radius: 16px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  background: rgba(255, 255, 255, 0.03);
  overflow: hidden;
}
.createOptionsGroup > summary{
  list-style: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.createOptionsGroup > summary::-webkit-details-marker{
  display: none;
}
.createOptionsGroupHead{
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 12px 14px;
  font-size: 14px;
  font-weight: 800;
  letter-spacing: -0.02em;
  color: rgba(238, 244, 255, 0.92);
}
.createOptionsGroupHead--theory .createOptionsSwitch{
  margin-left: auto;
}
.createOptionsGroup[open] .createOptionsGroupHead{
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
}
.createOptionsGrid{
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px;
  padding: 12px 14px 14px;
}
.createOptionsPill.isActive{
  border-color: rgba(167,139,250,0.65);
  background: linear-gradient(150deg, rgba(124,92,255,0.24), rgba(124,92,255,0.1));
  color: #fff;
}
.createOptionsStack{
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 12px 14px 14px;
}
.optChipGroup{
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.optChipLabel{
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(226,232,246,0.45);
}
.optChipRow{
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.optChip{
  display: inline-flex;
  align-items: center;
  min-height: 32px;
  padding: 4px 12px;
  border-radius: 999px;
  border: 1px solid rgba(255,255,255,0.12);
  background: rgba(255,255,255,0.045);
  color: rgba(232,238,247,0.8);
  font: inherit;
  font-size: 12.5px;
  font-weight: 700;
  cursor: pointer;
  white-space: nowrap;
  transition:
    border-color 160ms ease,
    background 160ms ease,
    color 160ms ease,
    transform 120ms ease;
  -webkit-tap-highlight-color: transparent;
}
.optChip:active{ transform: scale(0.96); }
.optChip.isActive{
  /* Unified active-purple pill (shared with .styleSuggestPill + .addressPill). */
  border-color: rgba(167,139,250,0.55);
  background: linear-gradient(150deg, rgba(124,92,255,0.20), rgba(124,92,255,0.09));
  color: #fff;
}

/* ── Create surface — neutral selected pills: brighter fill + soft white glow,
   no brand purple. Scoped to the route so other pages keep their accents. */
body[data-route="generate"] .createPageHeader .appScreenTitle,
body[data-route="generate"] .appScreenTitle{
  text-shadow: none;
}
body[data-route="generate"] .optChip.isActive,
body[data-route="generate"] .styleSuggestPill.isActive,
body[data-route="generate"] .addressPill.isActive{
  border-color: rgba(255,255,255,0.34);
  background: linear-gradient(180deg, rgba(255,255,255,0.20), rgba(255,255,255,0.09));
  color: #fff;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.25),
    0 0 0 1px rgba(255,255,255,0.085),
    0 3px 14px rgba(255,255,255,0.06),
    0 8px 24px rgba(0,0,0,0.17);
}
body[data-route="generate"] .addressPill.isActive .addressPillSub{
  color: rgba(244,247,255,0.78);
}
html[data-theme="light"] body[data-route="generate"] .optChip.isActive,
html[data-theme="light"] body[data-route="generate"] .styleSuggestPill.isActive,
html[data-theme="light"] body[data-route="generate"] .addressPill.isActive,
html[data-theme="light"] #singerGenderPills .addressPill.isActive,
html[data-theme="light"] #arabicAddressPills .addressPill.isActive{
  border-color: rgba(15,23,40,0.14);
  background: linear-gradient(180deg, rgba(255,255,255,0.96), rgba(244,247,252,0.92));
  color: var(--text);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.88),
    0 3px 12px rgba(88,104,140,0.10);
}
html[data-theme="light"] body[data-route="generate"] .addressPill.isActive .addressPillSub{
  color: rgba(15,23,40,0.55);
}
html[data-theme="light"] body[data-route="generate"] .aiAssistBtn{
  border-color: rgba(124, 92, 255, 0.34);
  background: linear-gradient(135deg, rgba(35, 213, 171, 0.16) 0%, rgba(124, 92, 255, 0.14) 55%, rgba(183, 139, 255, 0.12) 100%);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.85),
    0 4px 14px rgba(124, 92, 255, 0.14);
}
html[data-theme="light"] body[data-route="generate"] .aiAssistBtn:hover:not(:disabled){
  border-color: rgba(124, 92, 255, 0.48);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.92),
    0 6px 18px rgba(124, 92, 255, 0.2);
}
html[data-theme="light"] body[data-route="generate"] .aiAssistIco,
html[data-theme="light"] body[data-route="generate"] .aiAssistLabel,
html[data-theme="light"] body[data-route="generate"] .lyricsPolishIco,
html[data-theme="light"] body[data-route="generate"] .lyricsPolishLabel,
html[data-theme="light"] body[data-route="generate"] .lyricsMagicIco,
html[data-theme="light"] body[data-route="generate"] .lyricsMagicLabel{
  background: linear-gradient(135deg, #0f9b7a 0%, #12b896 22%, #7c5cff 72%, #9b7bff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
html[data-theme="light"] body[data-route="generate"] .lyricsMagicBtn:not(.aiAssistBtn){
  border-color: var(--border);
  background: var(--surface-secondary);
  box-shadow: none;
  color: var(--text);
}
html[data-theme="light"] body[data-route="generate"] .lyricsPolishBtn{
  /* inherits .aiAssistBtn light theme above */
}
html[data-theme="light"] body[data-route="generate"] .generateOrb,
html[data-theme="light"] body[data-route="generate"] #btnGenerateOrb,
html[data-theme="light"] body[data-route="generate"] .aiGenerate{
  background: linear-gradient(135deg, #23d5ab 0%, #12b896 100%);
  border: none;
  color: #fff;
  box-shadow: 0 10px 28px rgba(35, 213, 171, 0.28);
}
html[data-theme="light"] body[data-route="generate"] .stepCard{
  border-color: var(--border);
  background: var(--card);
  box-shadow: var(--chart-surface-shadow);
}
/* Legacy neutral magic buttons without .aiAssistBtn */
body[data-route="generate"] .lyricsMagicBtn:not(.aiAssistBtn){
  border-color: rgba(255,255,255,0.16);
  background: rgba(255,255,255,0.08);
  box-shadow: none;
  color: rgba(238,242,250,0.92);
}
/* The in-form Generate button is no longer the colour anchor (the centre "+"
   tab is), so it reads neutral as well — desktop dock + the in-form orb. */
body[data-route="generate"] .generateOrb,
body[data-route="generate"] #btnGenerateOrb,
body[data-route="generate"] .aiGenerate{
  background: rgba(255,255,255,0.12);
  border: 1px solid rgba(255,255,255,0.18);
  color: #fff;
  box-shadow: 0 10px 24px rgba(0,0,0,0.34);
}

/* ─── Live event campaign (World Cup → Christmas → …) ─────────────────── */
.campaignBanner{
  position: relative;
  z-index: 1;
  margin: 14px 0 18px;
}
.campaignBanner[hidden]{ display: none !important; }
.campaignBannerBtn{
  position: relative;
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 16px 18px;
  border-radius: 20px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(255, 255, 255, 0.03);
  color: var(--text);
  text-align: start;
  cursor: pointer;
  overflow: hidden;
  -webkit-tap-highlight-color: transparent;
}
.campaignBannerBtn:active{ transform: scale(0.99); }
.campaignBannerGlow{
  display: none;
}
.campaignBannerBody{
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 0;
  flex: 1;
}
.campaignBannerKicker{
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(35, 213, 171, 0.78);
}
.campaignLiveDot{
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--brand-teal);
  box-shadow: 0 0 0 0 rgba(35, 213, 171, 0.45);
  animation: campaignLivePulse 1.6s ease-out infinite;
}
@keyframes campaignLivePulse{
  0%{ box-shadow: 0 0 0 0 rgba(35, 213, 171, 0.4); }
  70%{ box-shadow: 0 0 0 7px rgba(35, 213, 171, 0); }
  100%{ box-shadow: 0 0 0 0 rgba(35, 213, 171, 0); }
}
.campaignBannerTitle{
  font-size: 19px;
  font-weight: 900;
  letter-spacing: 0.2px;
  color: #fff;
}
.campaignBannerSub{
  font-size: 12.5px;
  font-weight: 600;
  line-height: 1.35;
  color: rgba(223, 231, 251, 0.52);
}
.campaignBannerCta{
  margin-top: 7px;
  align-self: flex-start;
  padding: 7px 14px;
  border-radius: 999px;
  background: var(--brand-cta-bg);
  color: #051018;
  font-size: 12.5px;
  font-weight: 900;
  box-shadow: var(--brand-cta-shadow);
}
.campaignBannerEmoji{
  position: relative;
  font-size: 44px;
  line-height: 1;
  filter: none;
  opacity: 0.92;
}

/* Campaign sheet */
.campaignSheet{
  position: fixed;
  inset: 0;
  z-index: 13060;
  display: flex;
  align-items: flex-end;
  justify-content: center;
}
.campaignSheetBackdrop{
  position: absolute;
  inset: 0;
  background: rgba(3, 6, 10, 0.66);
  -webkit-backdrop-filter: blur(4px);
  backdrop-filter: blur(4px);
}
.campaignSheetCard{
  position: relative;
  display: flex;
  flex-direction: column;
  width: min(100%, 560px);
  max-height: 86dvh;
  border-radius: 24px 24px 0 0;
  border: 1px solid rgba(74, 222, 128, 0.22);
  border-bottom: none;
  background:
    radial-gradient(120% 70% at 100% 0%, rgba(250, 204, 21, 0.1), transparent 55%),
    linear-gradient(170deg, rgba(7, 40, 28, 0.99), rgba(7, 12, 18, 0.99));
  box-shadow: 0 -18px 60px rgba(0,0,0,0.55);
  animation: campaignSheetUp 240ms ease-out;
}
@keyframes campaignSheetUp{
  from{ transform: translateY(28px); opacity: 0; }
  to{ transform: translateY(0); opacity: 1; }
}
.campaignSheetHead{
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 18px 18px 12px;
}
.campaignSheetEmoji{ font-size: 36px; line-height: 1.1; }
.campaignSheetHeadText{ flex: 1; min-width: 0; }
.campaignSheetKicker{
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin: 0 0 3px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(134, 239, 172, 0.9);
}
.campaignSheetHead h3{
  margin: 0;
  font-size: 20px;
  font-weight: 900;
  color: #fff;
}
.campaignSheetSub{
  margin: 4px 0 0;
  font-size: 12.5px;
  line-height: 1.4;
  color: rgba(220, 252, 231, 0.66);
}
.campaignSheetClose{
  flex: none;
  width: 32px;
  height: 32px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.14);
  background: rgba(255,255,255,0.06);
  color: rgba(255,255,255,0.85);
  font-size: 18px;
  line-height: 1;
  cursor: pointer;
}
.campaignSheetScroll{
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  padding: 0 18px;
}
.campaignLeaderboard{
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 12px;
}
.campaignLeaderboard[hidden]{ display: none !important; }
.campaignBoardItem{
  padding: 5px 11px;
  border-radius: 999px;
  border: 1px solid rgba(250, 204, 21, 0.3);
  background: rgba(250, 204, 21, 0.09);
  color: rgba(254, 249, 195, 0.95);
  font-size: 12px;
  font-weight: 700;
}
.campaignBoardItem b{ font-weight: 900; }
.campaignSheetSection{ margin-bottom: 14px; }
.campaignSheetLabel{
  margin: 0 0 8px;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(220, 252, 231, 0.5);
}
.campaignTeamGrid{
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
}
.campaignTeamChip{
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  padding: 10px 6px 8px;
  border-radius: 14px;
  border: 1px solid rgba(255,255,255,0.1);
  background: rgba(255,255,255,0.04);
  color: rgba(236, 253, 245, 0.85);
  font: inherit;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  transition: border-color 150ms ease, background 150ms ease, transform 120ms ease;
}
.campaignTeamChip:active{ transform: scale(0.96); }
.campaignTeamChip.isActive{
  border-color: rgba(74, 222, 128, 0.7);
  background: linear-gradient(160deg, rgba(34, 197, 94, 0.24), rgba(34, 197, 94, 0.08));
  color: #fff;
}
.campaignTeamFlag{ font-size: 24px; line-height: 1.1; }
.campaignTeamName{
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}
.campaignTeamAr{
  font-size: 11px;
  font-weight: 600;
  color: rgba(220, 252, 231, 0.55);
}
.campaignTeamChip.isActive .campaignTeamAr{ color: rgba(220, 252, 231, 0.85); }
.campaignSheetFoot{
  padding: 12px 18px calc(14px + env(safe-area-inset-bottom));
}
.campaignCreateBtn{
  width: 100%;
  min-height: 50px;
  border: none;
  border-radius: 999px;
  background: linear-gradient(135deg, #facc15, #f59e0b);
  color: #1c1408;
  font: inherit;
  font-size: 15px;
  font-weight: 900;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.campaignCreateBtn:active{ transform: scale(0.98); }
.campaignCreateBtn:disabled{
  background: rgba(255,255,255,0.08);
  color: rgba(255,255,255,0.4);
  cursor: default;
}

/* Discover rail extras */
.discoverCampaignTitleBtn{
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0;
  border: none;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.discoverCampaignJoin{
  font-size: 12px;
  font-weight: 800;
  color: #facc15;
  white-space: nowrap;
}
.discoverCampaignRail .discoverChallengeSpotArt{ position: relative; }
.discoverCampaignFlag{
  position: absolute;
  top: 4px;
  left: 4px;
  z-index: 1;
  font-size: 15px;
  line-height: 1;
  filter: drop-shadow(0 1px 3px rgba(0,0,0,0.6));
}

/* Campaign badge on feed cards */
.campaignAttributionPill{
  border-color: rgba(250, 204, 21, 0.4) !important;
  background: rgba(250, 204, 21, 0.1) !important;
  color: rgba(254, 240, 138, 0.95) !important;
}

/* ─── Weekly chart (Top songs of the week) ────────────────────────────── */
.discoverWeeklyChart{
  position: relative;
  margin: 0 0 8px;
  padding: 0;
  border: none;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
.discoverWeeklyChart::before,
.discoverWeeklyChart::after{
  display: none;
}
.discoverWeeklyChart--final{
  margin-bottom: 16px;
  padding: 0;
}
.discoverWeeklyChart--final .chartWeekHead{
  margin-bottom: 12px;
}
.discoverWeeklyChart--final .chartWeekWinner{
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 0;
  width: 100%;
  padding: 10px 6px 10px 14px;
  margin: 0 0 10px;
  border: 1px solid var(--chart-surface-border);
  border-radius: 18px;
  background: var(--chart-surface);
  color: inherit;
  transition: background 160ms ease, border-color 160ms ease;
  box-shadow: var(--chart-surface-shadow);
}
.discoverWeeklyChart--final .chartWeekWinnerTap{
  display: grid;
  grid-template-columns: clamp(112px, 34vw, 136px) minmax(0, 1fr);
  align-items: center;
  gap: 14px;
  width: 100%;
  min-width: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.discoverWeeklyChart--final .chartWeekWinner:has(.chartWeekWinnerTap:active){
  background: rgba(255, 255, 255, 0.05);
  border-color: rgba(255, 255, 255, 0.12);
}
.discoverWeeklyChart--final .chartWeekWinnerHead,
.discoverWeeklyChart--final .chartWeekLeaderLead,
.discoverWeeklyChart--final .chartWeekRunnerLead{
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
}
.discoverWeeklyChart--final .chartWeekWinnerRank,
.discoverWeeklyChart--final .chartWeekRunnerRank,
.discoverWeeklyChart--final .chartWeekLeaderRank{
  font-size: 12px;
  font-weight: 850;
  letter-spacing: 0.03em;
  color: var(--text-primary);
  font-variant-numeric: tabular-nums;
}
.discoverWeeklyChart--final .chartWeekWinnerArt{
  position: relative;
  width: 100%;
  aspect-ratio: 1;
  border-radius: 16px;
  overflow: hidden;
  flex: none;
  align-self: center;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
}
.discoverWeeklyChart--final .chartWeekWinnerArt img{
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  display: block;
}
.discoverWeeklyChart--final .chartWeekWinnerBody{
  display: flex;
  flex-direction: column;
  gap: 3px;
  min-width: 0;
  justify-content: center;
}
.discoverWeeklyChart--final .chartWeekWinnerTitle{
  font-size: 18px;
  font-weight: 850;
  letter-spacing: -0.03em;
  color: var(--text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.discoverWeeklyChart--final .chartWeekWinnerBy{
  font-size: 13px;
  color: var(--text-secondary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.discoverWeeklyChart--final .chartWeekWinnerPlays{
  margin-top: 2px;
  font-size: 12px;
  font-weight: 700;
  color: var(--text-muted);
}
.discoverWeeklyChart--final .chartWeekWinner .discoverFeedPlayBtn--hero{
  display: none;
}
.discoverWeeklyChart--final .chartWeekRunners{
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 10px;
}
.discoverWeeklyChart--final .chartWeekRest{
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-bottom: 10px;
  padding-top: 8px;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}
.discoverWeeklyChart--final .chartWeekRest[hidden]{
  display: none !important;
}
.discoverWeeklyChart--final .chartWeekRunner{
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: 0;
  width: 100%;
  padding: 4px 4px 4px 8px;
  border: 1px solid var(--chart-surface-border);
  border-radius: 14px;
  background: var(--chart-surface);
  color: inherit;
  transition: background 160ms ease;
  box-shadow: var(--chart-surface-shadow);
}
.discoverWeeklyChart--final .chartWeekRunnerTap{
  display: grid;
  grid-template-columns: auto auto 1fr;
  align-items: center;
  gap: 10px;
  width: 100%;
  min-width: 0;
  padding: 4px 6px;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
