  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
  color: #eef3ff;
  font-size: 16px;
  font-weight: 600;
  padding: 14px 12px;
  border-radius: 12px;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}
.userActionSheetRow:active{ background: rgba(255, 255, 255, 0.06); }
.userActionSheetRow--danger{ color: #ff6b6b; }
.userActionSheetCancel{
  margin-top: 4px;
  text-align: center;
  font-weight: 700;
  color: rgba(223, 231, 251, 0.75);
  background: rgba(255, 255, 255, 0.04);
}

/* ============================================================================
   NabadAi Studio (V1)
   Neutral, premium, "a room inside Nabad". Restraint: teal = the one primary
   action, violet = active/highlight. Few containers, open spacing.
   ============================================================================ */

/* Full-screen feel: hide the app chrome while inside Studio. */
body[data-route="studio"] .mobileTabbar,
body[data-route="studio"] .header,
body[data-route="studio"] .footer { display: none !important; }

/* Desktop / wide web: the Studio is an immersive "room", so collapse the
   2-column app shell (sidebar + right rail) it would otherwise sit inside.
   Without this the centered column drifts right behind an empty sidebar
   gutter. The studio's own `.studio { max-width: 560px; margin: 0 auto }`
   then centers it on the full viewport, same as mobile. */
body[data-route="studio"] > .app {
  display: block !important;
  max-width: none !important;
  padding: 0 !important;
  height: auto;
  min-height: 100svh;
}
body[data-route="studio"] main.grid {
  display: block !important;
  margin: 0 !important;
  max-width: none !important;
}
body[data-route="studio"] .deskRail { display: none !important; }

/* Desktop / wide web: immersive entry screens (auth, onboarding, intro,
   music prefs) — collapse the app shell grid and hide the right rail so
   content centers on the viewport. Scoped to is-web-shell so the native
   Capacitor shell is unchanged. */
@media (min-width: 721px){
  html.is-web-shell body[data-route="auth"] > .app,
  html.is-web-shell body[data-route="onboarding"] > .app,
  html.is-web-shell body[data-route="intro"] > .app,
  html.is-web-shell body[data-route="music-preferences"] > .app{
    display: flex !important;
    flex-direction: column !important;
    align-items: stretch !important;
    justify-content: center !important;
    max-width: none !important;
    width: 100% !important;
    padding: 0 !important;
    margin: 0 !important;
    min-height: 100svh;
    height: 100svh;
  }
  html.is-web-shell body[data-route="auth"] main.grid,
  html.is-web-shell body[data-route="onboarding"] main.grid,
  html.is-web-shell body[data-route="intro"] main.grid,
  html.is-web-shell body[data-route="music-preferences"] main.grid{
    display: flex !important;
    flex: 1 1 auto !important;
    align-items: center !important;
    justify-content: center !important;
    margin: 0 !important;
    max-width: none !important;
    min-height: 0;
    grid-column: unset !important;
  }
  html.is-web-shell body[data-route="auth"] .deskRail,
  html.is-web-shell body[data-route="onboarding"] .deskRail,
  html.is-web-shell body[data-route="intro"] .deskRail,
  html.is-web-shell body[data-route="music-preferences"] .deskRail{
    display: none !important;
  }
  html.is-web-shell body.isAuth .authScreen,
  html.is-web-shell body.isOnboarding .onboardingScreen,
  html.is-web-shell body.isIntro .introScreen,
  html.is-web-shell body.isMusicPrefs .musicPrefsScreen{
    width: 100%;
    min-height: 100%;
    background:
      radial-gradient(90% 70% at 50% 0%, rgba(124,92,255,0.16), transparent 62%),
      #05070d !important;
  }
  html.is-web-shell body.isAuth .authInner{
    max-width: 420px;
    padding: 48px 32px 40px;
  }
  html.is-web-shell body.isOnboarding .onboardingInner{
    max-width: 440px;
    margin-inline: auto;
    padding:
      max(28px, env(safe-area-inset-top, 0))
      32px
      max(28px, env(safe-area-inset-bottom, 0));
  }
  html.is-web-shell body.isIntro .introInner{
    max-width: 440px;
    margin-inline: auto;
  }
  html.is-web-shell body.isMusicPrefs .musicPrefsInner{
    max-width: 480px;
    margin-inline: auto;
  }

  /* Immersive routes — collapse the sidebar grid on web desktop. */
  html.is-web-shell body[data-route="player"]:not(.discoverReelInShell) > .app,
  html.is-web-shell body[data-route="moment"] > .app,
  html.is-web-shell body[data-route="hub"] > .app{
    display: flex !important;
    flex-direction: column !important;
    max-width: none !important;
    width: 100% !important;
    padding: 0 !important;
    margin: 0 !important;
    min-height: 100svh;
  }
  html.is-web-shell body[data-route="player"]:not(.discoverReelInShell) main.grid,
  html.is-web-shell body[data-route="moment"] main.grid,
  html.is-web-shell body[data-route="hub"] main.grid{
    display: flex !important;
    flex: 1 1 auto !important;
    flex-direction: column !important;
    margin: 0 !important;
    max-width: none !important;
    min-height: 0;
    grid-column: unset !important;
  }
  html.is-web-shell body[data-route="player"]:not(.discoverReelInShell) main.grid{
    align-items: flex-start;
    justify-content: flex-start;
    overflow-x: hidden;
    overflow-y: auto;
    padding: 20px 24px 40px;
  }
  html.is-web-shell body[data-route="moment"] main.grid,
  html.is-web-shell body[data-route="hub"] main.grid{
    overflow: hidden;
  }
  html.is-web-shell body[data-route="player"]:not(.discoverReelInShell) .header,
  html.is-web-shell body[data-route="player"]:not(.discoverReelInShell) .deskRail,
  html.is-web-shell body[data-route="player"]:not(.discoverReelInShell) .footer,
  html.is-web-shell body[data-route="player"]:not(.discoverReelInShell) .mobileTabbar,
  html.is-web-shell body[data-route="moment"] .deskRail,
  html.is-web-shell body[data-route="hub"] .deskRail{
    display: none !important;
  }

  /* Player — centered card layout on web desktop (no sidebar). */
  html.is-web-shell body[data-route="player"]:not(.discoverReelInShell) .playerCard{
    width: 100%;
    max-width: 920px;
    margin: 0 auto;
    padding: 8px 4px 24px;
    display: flex;
    flex-direction: column;
    gap: 8px;
  }
  html.is-web-shell body[data-route="player"]:not(.discoverReelInShell) .playerShell{
    display: grid;
    grid-template-columns: minmax(280px, 360px) minmax(0, 1fr);
    gap: 28px;
    align-items: start;
    width: 100%;
  }
  html.is-web-shell body[data-route="player"]:not(.discoverReelInShell) .playerArtWrap{
    position: relative;
  }
  html.is-web-shell body[data-route="player"]:not(.discoverReelInShell) .playerMeta{
    position: static;
    align-items: flex-start;
    text-align: left;
    padding-top: 8px;
  }
  html.is-web-shell body[data-route="player"]:not(.discoverReelInShell) .playerTitleRow,
  html.is-web-shell body[data-route="player"]:not(.discoverReelInShell) .playerCreatorRow{
    justify-content: flex-start;
  }
  html.is-web-shell body[data-route="player"]:not(.discoverReelInShell) .playerTransport{
    width: 100%;
    max-width: 360px;
    margin-inline: 0;
  }
  html.is-web-shell body[data-route="player"]:not(.discoverReelInShell) .playerSocialRail{
    position: absolute;
    right: 12px;
    bottom: 12px;
    top: auto;
  }

  /* Discover For You reel — player route inside the 3-column shell. */
  html.is-web-shell body.discoverReelInShell[data-route="player"] > .app{
    display: grid !important;
    grid-template-columns: var(--nb-sidebar, 248px) minmax(0, 1fr);
    column-gap: var(--nb-shell-gap, 34px);
    align-items: start;
    min-height: 100vh;
    flex-direction: unset !important;
  }
  html.is-web-shell body.discoverReelInShell[data-route="player"] main.grid{
    grid-column: 2 !important;
    display: flex !important;
    flex-direction: column !important;
    align-items: stretch !important;
    justify-content: flex-start;
    flex: unset !important;
    margin: 0 !important;
    max-width: none !important;
    min-height: calc(100vh - 64px);
    padding: 0 0 12px;
    overflow: visible;
  }
  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerCard{
    display: flex !important;
    flex-direction: column;
    width: min(100%, 480px);
    max-width: 480px;
    min-height: calc(100vh - 64px);
    max-height: calc(100vh - 52px);
    margin-inline: auto;
    padding: 0;
    border-radius: 22px;
    overflow: hidden;
    border: 1px solid rgba(255,255,255,0.09);
    background: #0a0c12;
    box-shadow: 0 24px 64px rgba(0,0,0,0.45);
    position: relative;
    flex: 1 1 auto;
  }
  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerHeader{
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    z-index: 30;
    margin: 0;
    padding: 10px 12px;
    background: linear-gradient(180deg, rgba(0,0,0,0.48) 0%, transparent 100%);
    pointer-events: none;
  }
  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerHeader .nabadBackBtn,
  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerHeader .playerMenuBtn{
    pointer-events: auto;
    border-color: rgba(255,255,255,0.14);
    background: rgba(0,0,0,0.28);
    -webkit-backdrop-filter: blur(12px);
            backdrop-filter: blur(12px);
    color: rgba(255,255,255,0.92);
  }
  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerShell{
    flex: 1 1 auto;
    display: flex;
    flex-direction: column;
    min-height: 0;
    gap: 0;
    grid-template-columns: unset;
    position: relative;
    overflow: hidden;
    background: #0a0c12;
    width: 100%;
  }
  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerArtCol{
    flex: 1 1 auto;
    min-height: 0;
    position: relative;
    width: 100%;
  }
  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerArtWrap{
    position: absolute;
    inset: 0;
    border: none;
    border-radius: 0;
    padding: 0;
    box-shadow: none;
    min-height: 0;
    overflow: hidden;
    background: #0a0c12;
  }
  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerArtWrap .playerSocialRail{
    position: absolute;
    right: 12px;
    top: auto;
    bottom: 56px;
    transform: none;
    z-index: 12;
    max-height: calc(100% - 72px);
    overflow: visible;
    pointer-events: auto;
  }
  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerSocialActions{
    gap: 16px;
