  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerArt{
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    min-width: 0;
    min-height: 0;
    max-width: none;
    object-fit: cover;
    object-position: center top;
    border-radius: 0;
  }
  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerMeta{
    position: relative;
    flex: 0 0 auto;
    z-index: 12;
    width: 100%;
    padding: 10px 16px 14px;
    margin: 0;
    align-items: flex-start;
    text-align: left;
    color: #eef3ff;
