  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerTitle,
  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerCreatorHandle,
  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerTimeNum{
    color: rgba(240, 244, 255, 0.94);
  }
  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerTitleRow,
  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerCreatorRow{
