  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerCard[data-discover-reel="1"] .playerSocialRail,
  html.is-web-shell body.discoverReelInShell[data-route="player"] .playerCard[data-discover-reel="1"] .playerSocialRail[hidden]{
