.studioRoute { padding: 0; min-height: 100svh; }
#studioRoot { min-height: 100svh; }

.studio {
  --studio-pad: 20px;
  max-width: 560px;
  margin: 0 auto;
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  gap: 18px;
  padding: max(14px, env(safe-area-inset-top)) var(--studio-pad) calc(20px + env(safe-area-inset-bottom));
  color: var(--text);
  animation: studioFade 280ms ease both;
}
@keyframes studioFade { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }

.studioHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding-top: 2px;
}
.studioHeaderTitle {
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.18em;
  color: rgba(223, 231, 251, 0.62);
}
.studioBack, .studioHeaderSpacer {
  width: 38px; height: 38px;
  display: inline-flex; align-items: center; justify-content: center;
  border-radius: 999px;
  border: 1px solid var(--nabad-glass-border);
  background: var(--nabad-glass-bg);
  color: var(--text);
  -webkit-backdrop-filter: blur(var(--nabad-glass-blur));
  backdrop-filter: blur(var(--nabad-glass-blur));
  transition: transform 120ms ease, background 160ms ease;
}
.studioBack:active { transform: scale(0.94); }
.studioHeaderSpacer { border: 0; background: transparent; }

.studioHero { display: flex; align-items: center; gap: 16px; }
.studioCover {
  width: 92px; height: 92px;
  border-radius: 18px;
  overflow: hidden;
  flex-shrink: 0;
  box-shadow: var(--elev-1);
  background: rgba(255,255,255,0.05);
}
.studioCover img { width: 100%; height: 100%; object-fit: cover; display: block; }
.studioCoverPlaceholder {
  width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
  font-size: 30px; color: rgba(255,255,255,0.45);
}
.studioHeroMeta { min-width: 0; }
.studioTitle { font-size: 22px; font-weight: 800; line-height: 1.15; margin: 0; }
.studioArtist { font-size: 14px; color: var(--muted); margin: 3px 0 8px; }
.studioGuideTag {
  display: inline-flex; align-items: center;
  font-size: 11px; font-weight: 700; letter-spacing: 0.04em;
  padding: 4px 9px; border-radius: 999px;
  color: rgba(186, 206, 255, 0.92);
  background: var(--brand-violet-muted);
}

.studioWave, .studioRecWave {
  display: flex; align-items: center; gap: 3px;
  height: 64px;
}
.studioWave span, .studioRecWave span {
  flex: 1 1 auto;
  min-width: 2px;
  border-radius: 999px;
  background: rgba(255,255,255,0.16);
  transform-origin: center;
  transition: transform 90ms ease;
}

.studioGuideRow { display: flex; align-items: center; justify-content: space-between; gap: 14px; }
.studioGuideStatus { font-size: 13px; color: var(--muted); }
.studioGuideStatus[data-state="ready"] { color: rgba(120, 226, 199, 0.95); }
.studioGuideStatus[data-state="error"] { color: var(--danger); }
.studioVolume { display: flex; align-items: center; gap: 8px; flex: 0 0 150px; }
.studioVolumeIco { color: var(--muted); font-size: 13px; }
.studioVolume input[type="range"] { width: 100%; accent-color: var(--brand-violet); }

.studioMonitorRow {
  display: flex; align-items: center; gap: 12px;
  width: 100%; padding: 12px 14px; border-radius: 16px;
  border: 1px solid var(--nabad-glass-border); background: rgba(255,255,255,0.04);
  text-align: left; transition: border-color 160ms ease, background 160ms ease;
}
.studioMonitorRow.isOn { border-color: rgba(124,92,255,0.45); background: var(--brand-violet-muted); }
.studioMonitorIco { font-size: 18px; flex-shrink: 0; }
.studioMonitorText { display: flex; flex-direction: column; min-width: 0; flex: 1; }
.studioMonitorTitle { font-size: 14px; font-weight: 700; color: var(--text); }
.studioMonitorSub { font-size: 12px; color: var(--muted); line-height: 1.35; }
.studioMonitorRow .studioToggle { flex-shrink: 0; background: rgba(255,255,255,0.14); }
.studioMonitorRow .studioToggle.isOn { background: var(--brand-violet); }

.studioLyrics { font-size: 15px; line-height: 1.7; color: rgba(231, 238, 255, 0.78); }
.studioLyrics p { margin: 0 0 4px; }
.studioLyricsEmpty { color: var(--muted); font-style: italic; }
.studioLyricsWrap--scroll {
  flex: 1 1 auto;
  min-height: 0;
  max-height: min(40vh, 340px);
  overflow-y: auto;
  overscroll-behavior: contain;
  -webkit-overflow-scrolling: touch;
  touch-action: pan-y;
  padding-right: 2px;
}
.studioLyrics--plain {
  text-align: start;
  color: var(--text);
}
.studioLyrics--plain .studioLyricSpacer {
  height: 6px;
  margin: 0;
}

.studioFooter { margin-top: auto; display: flex; flex-direction: column; gap: 10px; padding-top: 8px; }
.studioPrimary {
  width: 100%;
  height: 54px;
  border: 0; border-radius: 16px;
  font-size: 16px; font-weight: 800;
  color: #042019;
  background: var(--brand-teal);
  box-shadow: var(--brand-cta-shadow);
  display: inline-flex; align-items: center; justify-content: center; gap: 10px;
  transition: transform 120ms ease, background 160ms ease, opacity 160ms ease;
}
.studioPrimary:active { transform: scale(0.985); }
.studioPrimary:disabled { opacity: 0.45; box-shadow: none; }
.studioPrimaryIco { color: #c0152e; font-size: 14px; }
.studioGhost {
  width: 100%; height: 46px;
  border: 1px solid var(--nabad-glass-border);
  border-radius: 14px;
  background: transparent;
  color: var(--text);
  font-size: 15px; font-weight: 600;
}
.studioGhost:active { transform: scale(0.985); }

.studioEmpty { margin: auto; text-align: center; color: var(--muted); display: flex; flex-direction: column; gap: 8px; align-items: center; }
.studioEmptyIco { font-size: 40px; }
.studioEmpty h2 { color: var(--text); font-size: 19px; margin: 6px 0 0; }

.studioRec { justify-content: flex-start; position: relative; }
.studioRecTop { display: flex; align-items: center; gap: 10px; }
.studioRecDot { width: 10px; height: 10px; border-radius: 999px; background: var(--danger); animation: studioPulse 1.1s ease-in-out infinite; }
.studioRecLabel { font-weight: 700; letter-spacing: 0.02em; }
.studioRecTimer { margin-left: auto; font-variant-numeric: tabular-nums; color: var(--muted); }
@keyframes studioPulse { 0%,100% { opacity: 1; transform: scale(1); } 50% { opacity: 0.4; transform: scale(0.8); } }

.studioCountIn {
  position: absolute; inset: 0; margin: auto;
  display: flex; align-items: center; justify-content: center;
  pointer-events: none; z-index: 5;
}
.studioCountIn span {
  font-size: 96px; font-weight: 800; color: var(--brand-violet);
  text-shadow: 0 0 40px rgba(124,92,255,0.5);
}
.studioCountIn span.studioCountPulse {
  animation: studioCount 0.85s ease both;
}
@keyframes studioCount { from { opacity: 0; transform: scale(1.5); } 40% { opacity: 1; } to { opacity: 0; transform: scale(0.8); } }

.studioRecWaves { display: flex; flex-direction: column; gap: 14px; margin-top: 24px; }
.studioRecWave--guide span { background: rgba(124, 92, 255, 0.55); }
.studioRecWave--voice span { background: rgba(255,255,255,0.85); }
.studioRecLyric { text-align: center; font-size: 20px; font-weight: 700; color: var(--brand-violet); margin-top: 18px; min-height: 28px; }

/* Synced karaoke lyrics — Home preview list */
.studioLyricsHead { margin-bottom: 6px; }
.studioLyricsBadge {
  font-size: 11px; font-weight: 700; letter-spacing: 0.03em;
  color: rgba(186, 206, 255, 0.92);
}
.studioLyrics--timed p { margin: 0 0 5px; }
.studioLyricSection {
  margin-top: 10px !important; font-size: 11px; font-weight: 800;
  letter-spacing: 0.06em; text-transform: uppercase; color: var(--muted);
}

/* Synced karaoke lyrics — Recording screen (auto-scrolls + highlights) */
.studioRecLyrics {
  flex: 1 1 auto; min-height: 0; overflow-y: auto; margin-top: 20px;
  display: flex; flex-direction: column; gap: 10px; padding: 8px 4px 40px;
  text-align: center; scrollbar-width: none;
  -webkit-mask-image: linear-gradient(180deg, transparent 0, #000 16%, #000 78%, transparent 100%);
          mask-image: linear-gradient(180deg, transparent 0, #000 16%, #000 78%, transparent 100%);
}
.studioRecLyrics::-webkit-scrollbar { display: none; }
.studioRecLyrics--plain {
  text-align: start;
  gap: 6px;
  -webkit-mask-image: none;
          mask-image: none;
  touch-action: pan-y;
}
.studioRecLyricPlainLine {
  font-size: 17px;
  font-weight: 650;
  line-height: 1.5;
  color: rgba(231, 238, 255, 0.88);
  text-align: start;
}
.studioRecLyrics--plain .studioLyricSection {
  text-align: start;
}
.studioRecLyricLine {
  font-size: 19px; font-weight: 700; line-height: 1.3;
  color: rgba(255,255,255,0.32);
  transition: color 220ms ease, transform 220ms ease, opacity 220ms ease;
}
.studioRecLyricLine.isPast { color: rgba(255,255,255,0.42); }
.studioRecLyricLine.isActive {
  color: var(--brand-violet-hover); transform: scale(1.04);
  text-shadow: 0 0 24px rgba(124,92,255,0.45);
}
.studioRecLyricSection {
  font-size: 11px; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase;
  color: var(--muted); margin-top: 6px;
}
.studioRecControls { margin-top: auto; display: flex; justify-content: center; padding-bottom: 8px; }
.studioStop {
  width: 76px; height: 76px; border-radius: 999px;
  border: 0; background: var(--danger); color: #fff;
  box-shadow: 0 10px 30px rgba(255,77,109,0.34);
  transition: transform 120ms ease;
  display: inline-flex; align-items: center; justify-content: center;
  padding: 0;
}
.studioStopIcon {
  width: 24px; height: 24px; border-radius: 5px;
  background: currentColor; flex-shrink: 0;
}
.studioStop:active { transform: scale(0.93); }

.discoverTrackSheetRow--studio { color: var(--brand-violet-hover); font-weight: 700; }
.discoverTrackSheetRow--publish{
  margin: 2px 4px 8px;
  border-radius: 14px;
  font-weight: 800;
  letter-spacing: 0.01em;
  color: #051018;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.22), rgba(255,255,255,0) 38%),
    var(--brand-cta-bg);
  box-shadow: var(--brand-cta-shadow);
}
.discoverTrackSheetRow--publish:active{
  background: var(--brand-cta-bg-hover);
}
html[data-theme="light"] .discoverTrackSheetRow--publish{
  color: #051018;
}
html[data-theme="light"] .playerPublishBtn{
  color: #051018;
}

/* ---- Review ---- */
.studioReview { justify-content: flex-start; gap: 16px; }
.studioReviewHead { text-align: center; }
.studioTakeBadge {
  display: inline-flex; align-items: center;
  font-size: 11px; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase;
  padding: 4px 11px; border-radius: 999px; margin-bottom: 10px;
  color: rgba(186, 206, 255, 0.92); background: var(--brand-violet-muted);
}
.studioTakeTabs {
  display: flex; flex-wrap: wrap; justify-content: center; gap: 6px; margin-bottom: 10px;
}
.studioTakeTab {
  border: 1px solid var(--nabad-glass-border); background: rgba(255,255,255,0.04);
  color: var(--muted); font-size: 12px; font-weight: 700; padding: 5px 12px; border-radius: 999px;
  transition: border-color 120ms ease, color 120ms ease, background 120ms ease;
}
.studioTakeTab.isActive {
  color: var(--brand-violet-hover); border-color: rgba(124,92,255,0.55);
  background: var(--brand-violet-muted);
}
.studioReviewTitle { font-size: 22px; font-weight: 800; margin: 0 0 6px; }
.studioReviewSub { font-size: 14px; color: var(--muted); margin: 0; line-height: 1.5; }

.studioReviewEditor { display: flex; flex-direction: column; gap: 12px; }

/* ---- Edit Take ---- */
.studioEdit { justify-content: flex-start; gap: 14px; }
.studioEditSub { margin-top: 4px; }
.studioEditBody { display: flex; flex-direction: column; gap: 10px; flex: 1; min-height: 0; }

.studioEditRuler {
  display: flex; justify-content: space-between;
  font-size: 10px; font-weight: 600; letter-spacing: 0.03em;
  color: rgba(255,255,255,0.38); font-variant-numeric: tabular-nums;
  padding: 0 2px;
}

.studioEditLanes {
  position: relative; display: flex; flex-direction: column; gap: 8px;
  padding: 12px; border-radius: 16px;
  background: rgba(255,255,255,0.03); border: 1px solid var(--nabad-glass-border);
}
.studioEditPlayhead {
  position: absolute; top: 10px; bottom: 10px; width: 2px; margin-left: -1px;
  background: rgba(255,255,255,0.9); z-index: 5; cursor: ew-resize; touch-action: none;
}
.studioEditLane { display: flex; flex-direction: column; gap: 5px; }
.studioEditLaneLabel {
  font-size: 11px; font-weight: 800; letter-spacing: 0.06em; text-transform: uppercase;
}
.studioEditLane--voice .studioEditLaneLabel { color: var(--brand-violet-hover); }
.studioEditLane--music .studioEditLaneLabel { color: rgba(90, 210, 190, 0.88); }

.studioEditTrack {
  position: relative; height: 52px; border-radius: 10px; overflow: hidden;
  background: rgba(0,0,0,0.24); touch-action: none;
}
.studioEditLane--voice .studioEditTrack { border: 1px solid rgba(124, 92, 255, 0.28); }
.studioEditLane--music .studioEditTrack { border: 1px solid rgba(60, 180, 160, 0.24); }

.studioEditClip { position: absolute; top: 0; bottom: 0; min-width: 10px; }
.studioEditWave {
  display: flex; align-items: center; gap: 1px; height: 100%; width: 100%; padding: 0 3px; box-sizing: border-box;
}
.studioEditWave--voice .studioPeakBar { background: rgba(124, 92, 255, 0.65); }
.studioEditWave--music .studioPeakBar { background: rgba(60, 180, 160, 0.55); }
.studioEditWave--empty {
  display: flex; align-items: center; justify-content: center;
  height: 100%; font-size: 12px; color: var(--muted);
}

.studioEditTrimShade {
  position: absolute; top: 0; bottom: 0; background: rgba(0,0,0,0.45); pointer-events: none; z-index: 2;
}
.studioEditTrimShade--left { left: 0; }
.studioEditTrimShade--right { right: 0; }

.studioEditTrimHandle {
  position: absolute; top: 0; bottom: 0; width: 14px; margin-left: -7px;
  border: 0; padding: 0; background: transparent; cursor: ew-resize; z-index: 4; touch-action: none;
}
.studioEditTrimHandle::after {
  content: ""; position: absolute; top: 8px; bottom: 8px; left: 6px; width: 2px;
  border-radius: 2px; background: var(--brand-violet-hover);
  box-shadow: 0 0 6px rgba(124, 92, 255, 0.55);
}

.studioEditSelect {
  position: absolute; top: 0; bottom: 0; z-index: 3; pointer-events: none;
  background: rgba(124, 92, 255, 0.22); border: 1px solid rgba(186, 160, 255, 0.55); border-radius: 4px;
}

.studioEditTools {
  display: flex; justify-content: center; flex-wrap: wrap; gap: 6px;
  padding: 6px 0 2px;
}
.studioEditTool {
  display: inline-flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 4px; min-width: 58px; height: 54px; padding: 4px 8px;
  border-radius: 12px; border: 1px solid var(--nabad-glass-border);
  background: rgba(255,255,255,0.04); color: rgba(231,238,255,0.88);
  font-size: 11px; font-weight: 600; transition: transform 120ms ease, border-color 120ms ease;
}
.studioEditTool:active:not(:disabled) { transform: scale(0.96); }
.studioEditTool:disabled { opacity: 0.35; pointer-events: none; }
.studioEditTool--play.isPlaying {
  border-color: rgba(124,92,255,0.5); color: var(--brand-violet-hover);
  background: var(--brand-violet-muted);
}
.studioEditTool--danger:not(:disabled) { color: var(--danger); }

.studioLevelsSheet {
  position: fixed; inset: 0; z-index: 120; display: flex; align-items: flex-end; justify-content: center;
}
.studioLevelsSheet[hidden] { display: none !important; }
.studioLevelsBackdrop {
  position: absolute; inset: 0; background: rgba(0,0,0,0.55);
}
.studioLevelsPanel {
  position: relative; width: min(100%, 420px); margin: 0 10px max(10px, env(safe-area-inset-bottom));
  padding: 16px; border-radius: 18px 18px 16px 16px;
  background: #12151c; border: 1px solid var(--nabad-glass-border);
  box-shadow: 0 -8px 32px rgba(0,0,0,0.45);
}
.studioLevelsHead {
  display: flex; align-items: center; justify-content: space-between; margin-bottom: 14px;
}
.studioLevelsTitle { font-size: 16px; font-weight: 800; }
.studioLevelsDone {
  border: 0; background: transparent; color: var(--brand-teal); font-weight: 700; font-size: 14px;
}
.studioLevelsSliders { display: flex; flex-direction: column; gap: 14px; }

/* Dev-only raw take analysis (never shown unless audio debug flag is on) */
.studioAudioDebugSheet {
  position: fixed; inset: 0; z-index: 200; display: flex; align-items: flex-end; justify-content: center;
  pointer-events: auto;
}
.studioAudioDebugBackdrop {
  position: absolute; inset: 0; background: rgba(0,0,0,0.45);
}
.studioAudioDebugPanel {
  position: relative; width: min(100%, 420px); max-height: min(78vh, 560px); overflow-y: auto;
  margin: 0 8px max(8px, env(safe-area-inset-bottom));
  padding: 14px 16px 16px; border-radius: 16px 16px 14px 14px;
  background: #0c0e14; border: 1px solid rgba(255,180,80,0.35);
  box-shadow: 0 -6px 28px rgba(0,0,0,0.55);
  font-family: ui-monospace, "SF Mono", Menlo, monospace;
  font-size: 11px;
}
.studioAudioDebugHead { margin-bottom: 10px; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; }
.studioAudioDebugMode {
  font-size: 10px; font-weight: 600; letter-spacing: 0.04em;
  color: rgba(124, 92, 255, 0.95); padding: 3px 8px; border-radius: 999px;
  background: rgba(124, 92, 255, 0.15); border: 1px solid rgba(124, 92, 255, 0.35);
}
.studioAudioDebugKicker {
  font-size: 10px; font-weight: 700; letter-spacing: 0.06em;
  color: rgba(255, 180, 80, 0.95);
}
.studioAudioDebugLoading {
  margin: 0; padding: 24px 0; text-align: center;
  color: rgba(232,238,247,0.55); font-size: 12px;
}
.studioAudioDebugStats { margin: 0 0 12px; }
.studioAudioDebugRow {
  display: flex; justify-content: space-between; gap: 12px;
  padding: 3px 0; border-bottom: 1px solid rgba(255,255,255,0.05);
}
.studioAudioDebugRow dt { margin: 0; color: rgba(232,238,247,0.45); font-weight: 500; }
.studioAudioDebugRow dd { margin: 0; color: rgba(232,238,247,0.92); text-align: right; }
.studioAudioDebugVoice { margin-bottom: 14px; }
.studioAudioDebugVoiceTitle {
  display: block; font-size: 10px; font-weight: 700; letter-spacing: 0.04em;
  color: rgba(232,238,247,0.5); margin-bottom: 6px; text-transform: uppercase;
}
.studioAudioDebugDiagList {
  list-style: none; margin: 0; padding: 0; display: flex; flex-direction: column; gap: 4px;
}
.studioAudioDebugDiag { font-size: 11px; line-height: 1.35; }
.studioAudioDebugDiag--ok { color: rgba(120, 220, 160, 0.95); }
.studioAudioDebugDiag--warn { color: rgba(255, 190, 100, 0.95); }
.studioAudioDebugContinue {
  width: 100%; font-family: inherit; font-size: 15px; font-weight: 700;
}
.studioAudioDebugExport {
  width: 100%; margin-bottom: 10px; font-family: inherit; font-size: 14px; font-weight: 600;
  padding: 12px 16px; border-radius: 14px; border: 1px solid rgba(255,255,255,0.14);
  background: rgba(255,255,255,0.06); color: rgba(232,238,247,0.92); cursor: pointer;
}
.studioAudioDebugExport:active { transform: scale(0.985); background: rgba(255,255,255,0.09); }
.studioAudioDebugPipeline { margin-bottom: 12px; }
.studioAudioDebugMono { font-size: 10px; line-height: 1.3; max-width: 58%; text-align: right; }
.studioAudioDebugRow--note dd { color: rgba(255, 190, 100, 0.85); }

.studioAgcTest {
  margin: 0 0 14px; padding: 12px; border-radius: 14px;
  background: rgba(124, 92, 255, 0.08); border: 1px dashed rgba(124, 92, 255, 0.35);
}
.studioAgcTestLabel {
  display: block; font-size: 10px; font-weight: 700; letter-spacing: 0.08em;
  color: rgba(124, 92, 255, 0.9); margin-bottom: 8px;
}
.studioAgcTestToggle { display: flex; gap: 8px; margin-bottom: 8px; }
.studioAgcTestBtn {
  flex: 1; font-family: inherit; font-size: 12px; font-weight: 600;
  padding: 10px 8px; border-radius: 12px; cursor: pointer;
  border: 1px solid rgba(255,255,255,0.12); background: rgba(255,255,255,0.04);
  color: rgba(232,238,247,0.75);
}
.studioAgcTestBtn.isActive {
  border-color: rgba(124, 92, 255, 0.55); background: rgba(124, 92, 255, 0.2);
  color: rgba(232,238,247,0.95);
}
.studioAgcTestBtn--full { width: 100%; text-align: center; }
.studioAgcTestHint { margin: 0; font-size: 11px; line-height: 1.35; color: rgba(232,238,247,0.45); }

.studioRecAgcBadge {
  font-size: 9px; font-weight: 600; letter-spacing: 0.03em;
  color: rgba(124, 92, 255, 0.95); margin-left: 6px;
}

.studioAudioDebugCompare { margin-bottom: 14px; }
.studioAudioDebugCompareTable {
  width: 100%; border-collapse: collapse; font-size: 10px; margin-bottom: 8px;
}
.studioAudioDebugCompareTable th,
.studioAudioDebugCompareTable td {
  padding: 5px 4px; text-align: right; border-bottom: 1px solid rgba(255,255,255,0.06);
}
.studioAudioDebugCompareTable th:first-child,
.studioAudioDebugCompareTable td:first-child { text-align: left; }
.studioAudioDebugCompareTable th { color: rgba(232,238,247,0.45); font-weight: 600; }
.studioAudioDebugCompareHint {
  margin: 0 0 8px; font-size: 10px; line-height: 1.35; color: rgba(232,238,247,0.45);
}
.studioAudioDebugCompareClear {
  font-family: inherit; font-size: 11px; font-weight: 600; padding: 0;
  border: none; background: none; color: rgba(124, 92, 255, 0.85); cursor: pointer;
}

.studioFooter--edit { margin-top: auto; }

.studioWave--solo .studioPeakBar { background: rgba(124, 92, 255, 0.55); }
.studioPeakBar {
  flex: 1 1 0; min-width: 1px; max-width: 5px; align-self: center; border-radius: 2px;
}
.studioPeakBar--empty { background: rgba(255,255,255,0.08) !important; height: 18% !important; }

.studioReviewLanesWrap {
  position: relative; display: flex; flex-direction: column; gap: 10px;
  padding: 12px; border-radius: 18px;
  background: rgba(255,255,255,0.03); border: 1px solid var(--nabad-glass-border);
}
.studioReviewPlayhead {
  position: absolute; top: 8px; bottom: 8px; width: 2px; margin-left: -1px;
  background: rgba(255,255,255,0.92); box-shadow: 0 0 8px rgba(124,92,255,0.65);
  pointer-events: none; z-index: 4;
}
.studioReviewLane { display: flex; flex-direction: column; gap: 6px; }
.studioReviewLaneHead {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
}
.studioReviewLaneLabel {
  font-size: 12px; font-weight: 800; letter-spacing: 0.05em; text-transform: uppercase;
}
.studioReviewLane--voice .studioReviewLaneLabel { color: rgba(186, 230, 255, 0.95); }
.studioReviewLane--music .studioReviewLaneLabel { color: rgba(255, 196, 140, 0.95); }

.studioReviewVolInline {
  display: grid; grid-template-columns: 18px 1fr 28px; align-items: center; gap: 6px;
  min-width: 0; flex: 1; max-width: 168px;
}
.studioReviewVolIco { font-size: 12px; opacity: 0.75; text-align: center; }
.studioReviewVolInline input[type="range"] { width: 100%; accent-color: var(--brand-violet); }
.studioReviewVolVal { font-size: 11px; color: var(--muted); text-align: right; font-variant-numeric: tabular-nums; }

.studioReviewLaneTrack {
  position: relative; height: 56px; border-radius: 12px; overflow: hidden;
  background: rgba(0,0,0,0.22); touch-action: none;
}
.studioReviewLane--voice .studioReviewLaneTrack { border: 1px solid rgba(80, 180, 255, 0.22); }
.studioReviewLane--music .studioReviewLaneTrack { border: 1px solid rgba(255, 160, 80, 0.22); }

.studioReviewWaveClip {
  position: absolute; top: 0; bottom: 0; min-width: 8px;
}
.studioReviewWave {
  display: flex; align-items: center; justify-content: stretch; gap: 1px;
  height: 100%; width: 100%; padding: 0 4px; box-sizing: border-box;
}
.studioReviewWave--voice .studioPeakBar { background: rgba(90, 200, 255, 0.72); }
.studioReviewWave--music .studioPeakBar { background: rgba(255, 170, 90, 0.68); }
.studioPeakBar {
  flex: 1 1 0; min-width: 1px; max-width: 6px; align-self: center;
  border-radius: 2px; transform-origin: center bottom;
}
.studioPeakBar--empty { background: rgba(255,255,255,0.08) !important; height: 18% !important; }
.studioReviewWave--empty {
  display: flex; align-items: center; justify-content: center;
  font-size: 12px; color: var(--muted);
}

.studioReviewSelect {
  position: absolute; top: 0; bottom: 0;
  background: rgba(124, 92, 255, 0.28);
  border: 1px solid rgba(186, 160, 255, 0.75);
  border-radius: 6px; pointer-events: none; z-index: 2;
}

.studioReviewTimeRow {
  display: flex; align-items: center; justify-content: center; flex-wrap: wrap; gap: 6px;
  font-size: 13px; color: var(--muted); font-variant-numeric: tabular-nums;
}
.studioReviewTimeSep { opacity: 0.5; }
.studioReviewSelHint { font-size: 12px; color: var(--brand-violet-hover); }

.studioReviewActionBar {
  display: flex; flex-wrap: wrap; gap: 6px; justify-content: center;
  padding: 8px; border-radius: 14px;
  background: rgba(255,255,255,0.03); border: 1px solid var(--nabad-glass-border);
}
.studioReviewAct {
  display: inline-flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 2px; min-width: 52px; height: 52px; padding: 4px 6px;
  border-radius: 12px; border: 1px solid var(--nabad-glass-border);
  background: rgba(255,255,255,0.04); color: var(--text);
  font-size: 15px; transition: transform 120ms ease, border-color 120ms ease, background 120ms ease;
}
.studioReviewAct:active:not(:disabled) { transform: scale(0.96); }
.studioReviewAct:disabled { opacity: 0.38; pointer-events: none; }
.studioReviewActLbl { font-size: 10px; font-weight: 700; letter-spacing: 0.02em; color: var(--muted); }
.studioReviewAct--play {
  min-width: 58px; background: var(--brand-teal); color: #042019; border-color: transparent;
  box-shadow: var(--brand-cta-shadow);
}
.studioReviewAct--play .studioReviewActLbl { color: rgba(4, 32, 25, 0.72); }
.studioReviewAct--play.isPlaying {
  background: var(--brand-violet); color: #fff;
}
.studioReviewAct--play.isPlaying .studioReviewActLbl { color: rgba(255,255,255,0.82); }
.studioReviewAct.isActive {
  border-color: rgba(124,92,255,0.55); color: var(--brand-violet-hover);
  background: var(--brand-violet-muted);
}
.studioReviewAct--danger:not(:disabled) { color: var(--danger); border-color: rgba(255,77,109,0.35); }

.studioReviewHint {
  margin: 0; font-size: 12px; color: var(--muted); text-align: center; line-height: 1.45;
}

.studioPlayDisk {
  align-self: center;
  width: 92px; height: 92px; border-radius: 999px; border: 0;
  background: var(--brand-teal); color: #042019; font-size: 28px;
  box-shadow: var(--brand-cta-shadow);
  display: inline-flex; align-items: center; justify-content: center;
  transition: transform 140ms ease;
}
.studioPlayDisk:active { transform: scale(0.94); }
.studioPlayDisk.isPlaying { background: var(--brand-violet); color: #fff; }
.studioPlayDiskIco { line-height: 1; }
.studioWave--review span { background: rgba(124, 92, 255, 0.5); }
.studioReviewTime { text-align: center; font-size: 13px; color: var(--muted); font-variant-numeric: tabular-nums; }
.studioReviewTimeSep { opacity: 0.5; margin: 0 4px; }

.studioPitchField {
  display: flex; flex-direction: column; gap: 10px;
  padding: 14px; border-radius: 16px;
  background: rgba(255,255,255,0.03); border: 1px solid var(--nabad-glass-border);
  position: relative;
}
.studioPitchField--busy { opacity: 0.92; }
.studioPitchSeg { margin-top: 2px; flex-wrap: wrap; }
.studioPitchSeg .studioSegBtn {
  min-width: calc(33.33% - 4px);
  flex: 1 1 calc(33.33% - 4px);
}
.studioPitchSeg .studioSegBtn:disabled { opacity: 0.55; }
.studioPitchSeg .studioSegBtn.isLoading {
  color: var(--brand-violet-hover);
  background: rgba(124, 92, 255, 0.14);
  position: relative;
}
.studioPitchSeg .studioSegBtn.isLoading::after {
  content: "";
  position: absolute; right: 8px; top: 50%;
  width: 10px; height: 10px; margin-top: -5px;
  border: 2px solid rgba(124, 92, 255, 0.25);
  border-top-color: var(--brand-violet);
  border-radius: 999px;
  animation: studioPitchSpin 650ms linear infinite;
}
.studioPitchStatus {
  margin-left: auto; font-size: 12px; font-weight: 700; color: var(--brand-violet-hover);
}
.studioPitchApplied {
  display: flex; align-items: flex-start; gap: 8px;
  padding: 10px 12px; border-radius: 12px;
  font-size: 12px; line-height: 1.45; color: rgba(231, 238, 255, 0.82);
  background: rgba(255,255,255,0.04); border: 1px solid rgba(255,255,255,0.06);
}
.studioPitchAppliedDot {
  width: 8px; height: 8px; margin-top: 4px; flex-shrink: 0;
  border-radius: 999px; background: rgba(255,255,255,0.28);
}
.studioPitchAppliedDot.isOn { background: var(--brand-teal); box-shadow: 0 0 8px rgba(0, 212, 170, 0.45); }
.studioPitchAppliedDot.isNeutral { background: rgba(255, 196, 120, 0.95); box-shadow: 0 0 8px rgba(255, 196, 120, 0.35); }
.studioPitchAppliedDot.isWarn { background: rgba(255, 120, 100, 0.95); box-shadow: 0 0 8px rgba(255, 120, 100, 0.35); }
.studioPitchField--active { border-color: rgba(0, 212, 170, 0.35); }
.studioPitchField--onPitch { border-color: rgba(255, 196, 120, 0.28); }
.studioPitchHint { margin: 0; font-size: 12px; line-height: 1.45; }
.studioPitchHint strong { font-weight: 700; color: rgba(231, 238, 255, 0.92); }
.studioPitchLoading {
  display: flex; align-items: center; justify-content: center; gap: 10px;
  padding: 10px 12px; border-radius: 12px;
  font-size: 13px; font-weight: 700; color: var(--brand-violet-hover);
  background: rgba(124, 92, 255, 0.1); border: 1px solid rgba(124, 92, 255, 0.22);
}
.studioPitchLoading[hidden] { display: none !important; }
.studioPitchSpinner {
  width: 16px; height: 16px; flex-shrink: 0;
  border: 2px solid rgba(124, 92, 255, 0.25);
  border-top-color: var(--brand-violet);
  border-radius: 999px;
  animation: studioPitchSpin 650ms linear infinite;
}
@keyframes studioPitchSpin {
  to { transform: rotate(360deg); }
}

.studioFeedbackCard {
  display: flex; gap: 12px; align-items: flex-start;
  padding: 14px; border-radius: 16px;
  background: rgba(255,255,255,0.04); border: 1px solid var(--nabad-glass-border);
}
.studioFeedbackIco { font-size: 18px; color: var(--brand-violet); line-height: 1.4; }
.studioFeedbackBody { min-width: 0; }
.studioFeedbackTop { display: flex; align-items: center; gap: 8px; }
.studioFeedbackTitle { font-weight: 700; font-size: 14px; }
.studioFeedbackText { margin: 4px 0 0; font-size: 13px; color: var(--muted); line-height: 1.5; }
.studioSoonPill {
  font-size: 10px; font-weight: 800; letter-spacing: 0.04em; text-transform: uppercase;
  padding: 2px 7px; border-radius: 999px;
  color: rgba(255,255,255,0.7); background: rgba(255,255,255,0.08);
}
.studioReviewActions { display: flex; gap: 10px; }
.studioReviewActions .studioGhost { flex: 1; }
.studioGhost--danger { color: var(--danger); border-color: rgba(255,77,109,0.3); }

/* ---- Mix ---- */
.studioMix { justify-content: flex-start; gap: 20px; padding-bottom: 8px; }
.studioMixHead { text-align: center; margin-bottom: 2px; }
.studioPlayPill {
  align-self: center; display: inline-flex; align-items: center; gap: 10px;
  height: 44px; padding: 0 22px; border-radius: 999px;
  border: 1px solid var(--nabad-glass-border); background: rgba(255,255,255,0.04);
  color: var(--text); font-weight: 700; font-size: 14px;
  transition: transform 120ms ease;
}
.studioPlayPill:active { transform: scale(0.97); }
.studioPlayPill.isPlaying { border-color: rgba(124,92,255,0.5); color: var(--brand-violet-hover); }

.studioSliders { display: flex; flex-direction: column; gap: 18px; }
.studioSliderRow { display: grid; grid-template-columns: 22px 56px 1fr 34px; align-items: center; gap: 10px; }
.studioSliderIco { color: var(--muted); display: inline-flex; align-items: center; justify-content: center; }
.studioPlayDiskIco { line-height: 1; display: inline-flex; align-items: center; justify-content: center; }
.studioPlayDiskIco svg { display: block; }
.studioSliderLabel { font-size: 14px; font-weight: 600; color: rgba(231,238,255,0.85); }
.studioSliderRow input[type="range"] { width: 100%; accent-color: var(--brand-violet); }
.studioSliderVal { font-size: 12px; color: var(--muted); text-align: right; font-variant-numeric: tabular-nums; }
.studioSliderRow--disabled { opacity: 0.55; }
.studioSliderRow--disabled input[type="range"] { pointer-events: none; }
.studioAdvSoon {
  display: block; margin-top: 1px; font-size: 10px; font-weight: 700;
  letter-spacing: 0.04em; text-transform: uppercase; color: var(--muted);
}

.studioSliders--advPitch { gap: 6px; }
.studioSliders--advPitch .studioSliderRow {
  padding: 10px 0;
  touch-action: none;
}
.studioSliders--advPitch input[type="range"] {
  height: 28px;
  min-height: 28px;
  touch-action: none;
}
.studioSliders--advPitch .studioSliderLabel { font-size: 13px; }

.studioMixField { display: flex; flex-direction: column; gap: 10px; }
.studioMixFinishHint {
  font-size: 11px; font-weight: 600; color: var(--brand-teal);
}
.studioMixField--row { flex-direction: row; align-items: center; justify-content: space-between; }
.studioMixFieldTop { display: flex; align-items: center; gap: 8px; }
.studioMixLabel { font-size: 14px; font-weight: 600; color: rgba(231,238,255,0.85); }
.studioSeg {
  display: flex; gap: 4px; padding: 4px; border-radius: 12px;
  background: rgba(255,255,255,0.04); border: 1px solid var(--nabad-glass-border);
}
.studioSegBtn {
  flex: 1; height: 36px; border: 0; border-radius: 9px; background: transparent;
  color: var(--muted); font-size: 13px; font-weight: 700;
  transition: background 140ms ease, color 140ms ease;
}
.studioSegBtn.isActive { background: var(--brand-violet-muted); color: rgba(206, 219, 255, 0.98); }
.studioToggle {
  width: 50px; height: 30px; border-radius: 999px; border: 0; padding: 0;
  background: rgba(255,255,255,0.14); position: relative; transition: background 160ms ease;
}
.studioToggle.isOn { background: var(--brand-teal); }
.studioToggleKnob {
  position: absolute; top: 3px; left: 3px; width: 24px; height: 24px; border-radius: 999px;
  background: #fff; transition: transform 160ms cubic-bezier(.3,1.3,.5,1);
}
.studioToggle.isOn .studioToggleKnob { transform: translateX(20px); }
.studioPrimary--publish {
  color: #fff;
  background: linear-gradient(135deg, var(--brand-violet) 0%, var(--brand-teal) 100%);
}

/* ---- Publishing + Published ---- */
.studioPublish, .studioPublished { justify-content: center; }
.studioPublishInner { margin: auto; width: 100%; max-width: 340px; text-align: center; display: flex; flex-direction: column; align-items: center; gap: 12px; }
.studioPublishArt {
  width: 132px; height: 132px; border-radius: 24px; overflow: hidden; position: relative;
  background: rgba(255,255,255,0.05); box-shadow: var(--elev-1); margin-bottom: 6px;
}
.studioPublishArt img { width: 100%; height: 100%; object-fit: cover; display: block; }
.studioPublishArt.isEmpty { display: flex; align-items: center; justify-content: center; font-size: 40px; color: rgba(255,255,255,0.4); }
.studioPublishShimmer {
  position: absolute; inset: 0;
  background: linear-gradient(110deg, transparent 30%, rgba(255,255,255,0.22) 50%, transparent 70%);
  transform: translateX(-100%); animation: studioShimmer 1.4s ease-in-out infinite;
}
@keyframes studioShimmer { to { transform: translateX(100%); } }
.studioPublishTitle { font-size: 22px; font-weight: 800; margin: 0; }
.studioPublishPhase { font-size: 14px; color: var(--muted); margin: 0; line-height: 1.5; }
.studioPubBar { width: 100%; height: 8px; border-radius: 999px; background: rgba(255,255,255,0.1); overflow: hidden; margin-top: 4px; }
.studioPubFill { display: block; height: 100%; border-radius: 999px; background: linear-gradient(90deg, var(--brand-violet), var(--brand-teal)); transition: width 160ms ease; }
.studioPubPct { font-size: 13px; font-weight: 700; color: rgba(231,238,255,0.85); font-variant-numeric: tabular-nums; }
.studioPublishHint { font-size: 12px; color: var(--muted); margin: 6px 0 0; }

.studioCheck { width: 72px; height: 72px; }
.studioCheckCircle { stroke: var(--brand-teal); stroke-width: 3; stroke-dasharray: 151; stroke-dashoffset: 151; animation: studioDraw 0.5s ease forwards; }
.studioCheckMark { stroke: var(--brand-teal); stroke-width: 4; stroke-linecap: round; stroke-linejoin: round; stroke-dasharray: 48; stroke-dashoffset: 48; animation: studioDraw 0.35s 0.4s ease forwards; }
@keyframes studioDraw { to { stroke-dashoffset: 0; } }
.studioFooter--done { margin-top: 18px; width: 100%; }

/* ---- Preview + Mix (merged finish screen) ---- */
.studioFinish {
  justify-content: flex-start;
  gap: 14px;
  padding-bottom: calc(12px + env(safe-area-inset-bottom, 0px));
}
.studioFinishHead { text-align: center; display: flex; flex-direction: column; gap: 6px; }
.studioFinishTake {
  font-size: 12px; font-weight: 700; letter-spacing: 0.06em; text-transform: uppercase;
  color: var(--brand-violet-hover);
}
.studioPreviewPlay {
  align-self: center;
  display: inline-flex; align-items: center; gap: 12px;
  height: 50px; padding: 0 18px 0 6px; margin-top: 2px;
  border-radius: 999px; border: 1px solid var(--nabad-glass-border);
  background: var(--nabad-glass-bg);
  box-shadow: var(--nabad-glass-shadow), var(--nabad-glass-inset-top);
  color: rgba(231, 238, 255, 0.95); font-weight: 700; font-size: 14px;
  transition: transform 140ms ease, border-color 140ms ease, background 140ms ease;
}
.studioPreviewPlay:active { transform: scale(0.97); }
.studioPreviewPlay.isPlaying {
  border-color: rgba(124, 92, 255, 0.45);
  background: rgba(124, 92, 255, 0.12);
}
.studioPreviewPlayIco {
  width: 38px; height: 38px; border-radius: 999px;
  display: inline-flex; align-items: center; justify-content: center;
  background: rgba(255, 255, 255, 0.08); color: rgba(231, 238, 255, 0.95);
}
.studioPreviewPlay.isPlaying .studioPreviewPlayIco {
  background: var(--brand-violet-muted); color: var(--brand-violet-hover);
}
.studioPreviewPlayIco svg { display: block; }
.studioPreviewPlayLbl { letter-spacing: 0.01em; }
.studioWave--finish { margin-top: -2px; }
.studioFinishTime { margin-top: -4px; }

.studioAiCard {
  position: relative; display: flex; flex-direction: column; gap: 10px;
  padding: 14px 14px 12px; border-radius: 18px; overflow: hidden;
  background: linear-gradient(155deg, rgba(124, 92, 255, 0.16), rgba(35, 213, 171, 0.07) 52%, rgba(255, 255, 255, 0.03));
  border: 1px solid rgba(124, 92, 255, 0.22);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.08);
}
.studioAiCard::before {
  content: ""; position: absolute; inset: 0; pointer-events: none;
  background: radial-gradient(120% 80% at 0% 0%, rgba(124, 92, 255, 0.18), transparent 55%);
}
.studioAiCard.isApplied {
  border-color: rgba(35, 213, 171, 0.42);
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.22), 0 0 0 1px rgba(35, 213, 171, 0.12) inset;
}
.studioAiCardTop {
  position: relative; z-index: 1;
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
}
.studioAiCardBrand { font-size: 13px; font-weight: 800; color: rgba(231, 238, 255, 0.98); letter-spacing: 0.01em; }
.studioAiSpark { margin-right: 4px; }
.studioAiCardSub {
  position: relative; z-index: 1;
  margin: 0; font-size: 12px; color: rgba(231, 238, 255, 0.62); line-height: 1.35;
}
.studioAiChips {
  position: relative; z-index: 1;
  display: flex; flex-wrap: wrap; gap: 6px;
}
.studioAiChip {
  display: inline-flex; align-items: center; height: 26px; padding: 0 10px;
  border-radius: 999px; font-size: 11px; font-weight: 700;
  color: rgba(231, 238, 255, 0.88);
  background: rgba(255, 255, 255, 0.07); border: 1px solid rgba(255, 255, 255, 0.08);
}
.studioAiMatch {
  font-size: 11px; font-weight: 800; letter-spacing: 0.03em; text-transform: uppercase;
  color: var(--brand-teal);
}
.studioAiApply {
  position: relative; z-index: 1;
  width: 100%; height: 40px; margin-top: 2px; border-radius: 12px; border: 0;
  font-size: 13px; font-weight: 800; color: #042019;
  background: linear-gradient(135deg, var(--brand-teal), #1fc99a);
  box-shadow: 0 6px 18px rgba(0, 212, 170, 0.28);
  transition: transform 120ms ease, opacity 120ms ease;
}
.studioAiApply:active { transform: scale(0.98); }
.studioAiCard.isApplied .studioAiApply {
  color: rgba(231, 238, 255, 0.92);
  background: rgba(255, 255, 255, 0.1);
  box-shadow: none; border: 1px solid rgba(255, 255, 255, 0.12);
}

.studioPresetBlock { display: flex; flex-direction: column; gap: 8px; }
.studioStyleTabs {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px;
}
.studioStyleTab {
  height: 36px; padding: 0 8px; border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.08); background: rgba(255, 255, 255, 0.04);
  color: var(--muted); font-size: 12px; font-weight: 700;
  transition: background 140ms ease, color 140ms ease, border-color 140ms ease;
}
.studioStyleTab.isActive {
  color: rgba(231, 238, 255, 0.98);
  background: rgba(255, 255, 255, 0.14);
  border-color: rgba(255, 255, 255, 0.18);
}
.studioStyleTab[data-style-tab="melodylock"].isActive {
  background: rgba(45, 212, 191, 0.12);
  border-color: rgba(45, 212, 191, 0.32);
  color: var(--brand-teal-hover, #5eead4);
}
.studioStyleTab[data-style-tab="custom"].isActive {
  background: rgba(124, 92, 255, 0.14);
  border-color: rgba(124, 92, 255, 0.28);
  color: var(--brand-violet-hover);
}

.studioFinishSection {
  display: flex; flex-direction: column; gap: 10px;
  margin-top: 4px; padding: 14px 12px 12px; border-radius: 16px;
  background: rgba(255, 255, 255, 0.03); border: 1px solid var(--nabad-glass-border);
  width: 100%; max-width: 100%; box-sizing: border-box; overflow: hidden;
}
.studioFinishSection .studioMixLabel { font-size: 13px; }
.studioSeg--finish .studioSegBtn { font-size: 12px; min-height: 38px; }

.studioProMasterToggle {
  display: grid;
  grid-template-columns: 22px minmax(0, 1fr);
  gap: 10px;
  align-items: start;
  width: 100%; max-width: 100%;
  margin-top: 6px; padding: 12px;
  border-radius: 12px;
  background: rgba(124, 92, 255, 0.08);
  border: 1px solid rgba(124, 92, 255, 0.22);
  cursor: pointer;
  box-sizing: border-box;
}
.studioProMasterToggle input {
  width: 18px; height: 18px; margin: 2px 0 0;
  accent-color: var(--brand-violet-hover);
}
.studioProMasterCopy {
  display: flex; flex-direction: column; gap: 4px;
  min-width: 0; max-width: 100%;
  font-size: 12px; line-height: 1.4; color: var(--muted);
}
.studioProMasterCopy .studioProMasterTitle {
  font-size: 13px; font-weight: 800; color: rgba(231, 238, 255, 0.95);
}
.studioProMasterCopy .studioProMasterDesc {
  overflow-wrap: anywhere; word-break: break-word;
}

.studioProMaster { padding-bottom: 24px; }
.studioProMasterHero { text-align: center; padding: 8px 12px 16px; }
.studioProMasterArt {
  width: 88px; height: 88px; border-radius: 16px; object-fit: cover; margin: 0 auto 12px;
  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.35);
}
.studioProMasterTitle { margin: 0 0 6px; font-size: 20px; font-weight: 800; }
.studioProMasterSub { margin: 0; font-size: 13px; color: var(--muted); line-height: 1.45; }
.studioProMasterAudioHint { margin: 0 0 12px; font-size: 13px; color: var(--muted); text-align: center; }
.studioProMasterPlay { width: 100%; margin: 0 0 20px; min-height: 48px; font-size: 16px; font-weight: 700; }
.studioProMasterAudio { width: 100%; margin: 8px 0 16px; }

html[data-theme="light"] .studioProMasterToggle {
  background: rgba(124, 92, 255, 0.06); border-color: rgba(124, 92, 255, 0.18);
}
html[data-theme="light"] .studioProMasterCopy .studioProMasterTitle { color: #1a1f2e; }

.studioMixTabs {
  display: flex; gap: 4px; padding: 3px; border-radius: 12px;
  background: rgba(255, 255, 255, 0.04); border: 1px solid rgba(255, 255, 255, 0.06);
}
.studioMixTab {
  flex: 1; height: 34px; border: 0; border-radius: 9px; background: transparent;
  color: var(--muted); font-size: 13px; font-weight: 700;
}
.studioMixTab.isActive { background: rgba(255, 255, 255, 0.08); color: rgba(231, 238, 255, 0.95); }
.studioMixPanel { display: flex; flex-direction: column; gap: 14px; }
.studioMixPanel[hidden] { display: none !important; }
.studioSliders--compact { gap: 14px; }
.studioMixField--finish { gap: 8px; }
.studioSeg--finish .studioSegBtn { font-size: 12px; padding: 0 4px; }

.studioFooter--finish {
  position: sticky; bottom: 0; z-index: 2;
  padding-top: 12px; padding-bottom: max(8px, env(safe-area-inset-bottom, 0px));
  background: linear-gradient(180deg, transparent, rgba(8, 10, 18, 0.92) 28%);
}
.studioPrimary--continue {
  min-height: 52px; font-size: 16px; font-weight: 800; letter-spacing: 0.01em;
}

.studioNabadProcess .studioPublishInner { gap: 14px; }
.studioNabadKicker {
  margin: 0; font-size: 12px; font-weight: 800; letter-spacing: 0.06em;
  text-transform: uppercase; color: var(--brand-violet-hover);
}
.studioNabadScore {
  width: 100%; display: flex; flex-direction: column; align-items: center; gap: 4px;
  padding: 14px 12px; border-radius: 16px; text-align: center;
  background: linear-gradient(155deg, rgba(124, 92, 255, 0.14), rgba(35, 213, 171, 0.08));
  border: 1px solid rgba(124, 92, 255, 0.22);
}
.studioNabadScoreLbl {
  font-size: 11px; font-weight: 800; letter-spacing: 0.08em; text-transform: uppercase;
  color: rgba(231, 238, 255, 0.62);
}
.studioNabadScoreVal {
  font-size: 40px; font-weight: 800; line-height: 1;
  color: var(--brand-teal); text-shadow: 0 0 24px rgba(35, 213, 171, 0.35);
}
.studioNabadScoreDetail { margin: 2px 0 0; font-size: 12px; color: rgba(231, 238, 255, 0.78); }
.studioNabadScoreBlurb { margin: 6px 0 0; font-size: 12px; line-height: 1.45; color: var(--muted); }

.studioDetails { gap: 18px; }
.studioDetailsHero { text-align: center; display: flex; flex-direction: column; align-items: center; gap: 10px; }
.studioDetailsArt {
  width: 120px; height: 120px; border-radius: 22px; overflow: hidden;
  background: rgba(255, 255, 255, 0.05); box-shadow: var(--elev-1);
}
.studioDetailsArt img { width: 100%; height: 100%; object-fit: cover; display: block; }
.studioDetailsArt.isEmpty { display: flex; align-items: center; justify-content: center; font-size: 36px; color: rgba(255,255,255,0.35); }
.studioDetailsSub { margin: 0; font-size: 14px; color: var(--muted); line-height: 1.45; }
.studioDetailsField { display: flex; flex-direction: column; gap: 8px; }
.studioDetailsInput {
  width: 100%; height: 48px; padding: 0 14px; border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.1); background: rgba(255, 255, 255, 0.04);
  color: var(--text); font-size: 16px; font-weight: 600;
}
.studioSeg--visibility { margin-top: 2px; }

@media (prefers-reduced-motion: reduce) {
  .studio, .studioCountIn span.studioCountPulse, .studioRecDot, .studioPublishShimmer, .studioCheckCircle, .studioCheckMark { animation: none; }
  .studioCheckCircle, .studioCheckMark { stroke-dashoffset: 0; }
}

/* ===== Studio: source chooser, separating, lobby, recordings ===== */

/* Source chooser */
.studioSource {
  gap: 0;
}
.studioSourceBody {
  flex: 1 1 auto;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 28px;
  padding: 12px 0 8px;
  min-height: 0;
}
.studioSourceHero {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 18px;
}
.studioSource .studioCover--source {
  width: min(58vw, 228px);
  height: min(58vw, 228px);
  border-radius: 26px;
  box-shadow:
    0 28px 56px -20px rgba(0, 0, 0, 0.62),
    0 0 0 1px rgba(255, 255, 255, 0.07);
}
.studioSourceMeta {
  max-width: 340px;
}
.studioSource .studioTitle {
  font-size: clamp(22px, 5.6vw, 26px);
  line-height: 1.2;
}
.studioSource .studioArtist {
  font-size: 15px;
  margin: 8px 0 0;
  line-height: 1.45;
}
.studioSource .studioChoices {
  margin-top: 0;
  width: 100%;
}
.studioChoices { display: flex; flex-direction: column; gap: 12px; margin-top: 22px; }
.studioChoice {
  display: flex; align-items: center; gap: 14px; width: 100%;
  padding: 18px 16px; border-radius: 20px; text-align: left; cursor: pointer;
  border: 1px solid rgba(255,255,255,0.08);
  background: linear-gradient(160deg, rgba(255,255,255,0.05), rgba(255,255,255,0.02));
  color: var(--text, #f5f6fb);
  transition: transform .16s ease, border-color .16s ease, background .16s ease;
}
.studioChoice:active { transform: scale(0.985); }
.studioChoice--accent { border-color: rgba(124,92,255,0.4); }
.studioChoiceIco {
  flex: 0 0 auto; width: 46px; height: 46px; border-radius: 14px;
  display: flex; align-items: center; justify-content: center; font-size: 20px;
  background: rgba(255,255,255,0.06);
}
.studioChoice--accent .studioChoiceIco {
  background: linear-gradient(135deg, rgba(124,92,255,0.32), rgba(35,213,171,0.22));
}
.studioChoiceBody { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 4px; }
.studioChoiceTitle { font-size: 16px; font-weight: 650; }
.studioChoiceSub { font-size: 13px; line-height: 1.45; color: rgba(255,255,255,0.6); }
.studioChoiceSub b { color: rgba(255,255,255,0.82); font-weight: 600; }
.studioChoiceChev { flex: 0 0 auto; color: rgba(255,255,255,0.4); font-size: 18px; }
.studioReadyTag {
  display: inline-block; margin-left: 6px; padding: 1px 8px; border-radius: 999px;
  font-size: 10px; font-weight: 700; letter-spacing: .04em; vertical-align: middle;
  color: #06231b; background: var(--brand-teal, #23d5ab);
}

/* Separating — indeterminate progress fill (reuses .studioPublish shell) */
.studioPubFill--indet {
  width: 38%; border-radius: inherit;
  background: linear-gradient(90deg, transparent, var(--brand, #7c5cff), transparent);
  animation: studioIndet 1.3s ease-in-out infinite;
}
@keyframes studioIndet {
  0% { margin-left: -40%; }
  100% { margin-left: 100%; }
}

/* Lobby */
.studioLobbyHead { margin-top: 8px; }
.studioLobbyHead .studioTitle { font-size: 28px; }
.studioQuickTake {
  display: flex; align-items: center; gap: 14px; width: 100%; margin-top: 20px;
  padding: 18px 18px; border-radius: 22px; cursor: pointer; text-align: left;
  color: #fff; border: 0;
  background: linear-gradient(135deg, #7c5cff, #5b8cff 70%, #23d5ab);
  box-shadow: 0 18px 40px -18px rgba(124,92,255,0.6);
  transition: transform .16s ease;
}
.studioQuickTake:active { transform: scale(0.985); }
.studioQuickIco {
  flex: 0 0 auto; width: 44px; height: 44px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center; font-size: 16px;
  color: #fff; background: rgba(255,255,255,0.18);
}
.studioQuickBody { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.studioQuickTitle { font-size: 17px; font-weight: 700; }
.studioQuickSub { font-size: 13px; color: rgba(255,255,255,0.82); }

.studioLobbySection { margin-top: 26px; }
.studioLobbySectionTop { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.studioLobbyKicker { font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; color: rgba(255,255,255,0.5); }
.studioLink { background: none; border: 0; color: var(--brand, #7c5cff); font-size: 13px; font-weight: 600; cursor: pointer; padding: 4px 0; }
.studioLobbyEmpty { font-size: 13px; line-height: 1.5; color: rgba(255,255,255,0.5); margin: 0; }
.studioLobbyEmpty b { color: rgba(255,255,255,0.8); }

.studioMiniList { display: flex; flex-direction: column; gap: 8px; }
.studioMiniRow {
  display: flex; align-items: center; gap: 12px; width: 100%;
  padding: 12px 14px; border-radius: 14px; cursor: pointer; text-align: left;
  border: 1px solid rgba(255,255,255,0.06); background: rgba(255,255,255,0.035);
  color: var(--text, #f5f6fb);
}
.studioMiniRow--proj { padding: 0; overflow: hidden; }
.studioMiniMain {
  display: flex; align-items: center; gap: 12px; flex: 1 1 auto; min-width: 0;
  padding: 12px 14px; background: none; border: 0; color: inherit; cursor: pointer; text-align: left;
}
.studioMiniIco { flex: 0 0 auto; width: 28px; height: 28px; border-radius: 8px; display: flex; align-items: center; justify-content: center; font-size: 12px; background: rgba(255,255,255,0.07); color: rgba(255,255,255,0.7); }
.studioMiniName { flex: 1 1 auto; min-width: 0; font-size: 14px; font-weight: 550; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.studioMiniMeta { flex: 0 0 auto; font-size: 12px; color: rgba(255,255,255,0.45); }
.studioMiniDel { flex: 0 0 auto; padding: 0 16px; align-self: stretch; background: none; border: 0; color: rgba(255,255,255,0.35); font-size: 14px; cursor: pointer; }
.studioMiniDel:active { color: rgba(255,120,120,0.9); }

/* Recordings */
.studioRecList { display: flex; flex-direction: column; gap: 10px; margin-top: 18px; }
.studioRecItem {
  display: flex; align-items: center; gap: 12px;
  padding: 12px 12px 12px 12px; border-radius: 16px;
  border: 1px solid rgba(255,255,255,0.06); background: rgba(255,255,255,0.035);
}
.studioRecPlay {
  flex: 0 0 auto; width: 42px; height: 42px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center; font-size: 14px;
  border: 0; cursor: pointer; color: #fff;
  background: linear-gradient(135deg, #7c5cff, #23d5ab);
}
.studioRecItemBody { flex: 1 1 auto; min-width: 0; }
.studioRecItemName { font-size: 15px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.studioRecItemMeta { font-size: 12px; color: rgba(255,255,255,0.45); margin-top: 2px; }
.studioRecDel { flex: 0 0 auto; width: 36px; height: 36px; border-radius: 10px; border: 0; background: none; color: rgba(255,255,255,0.35); font-size: 14px; cursor: pointer; }
.studioRecDel:active { color: rgba(255,120,120,0.9); }
.studioRecLyric--memo { color: rgba(255,255,255,0.55); font-size: 15px; }

/* ===== Studio: New-project card, library picker, sync slider, scrub ===== */

/* "New project" — a neutral companion to the brand Quick-take CTA */
.studioQuickTake--alt {
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.08);
  box-shadow: none;
  color: var(--text, #f5f6fb);
  margin-top: 12px;
}
.studioQuickTake--alt .studioQuickSub { color: rgba(255,255,255,0.6); }
.studioQuickIco--alt { background: rgba(255,255,255,0.07); color: rgba(255,255,255,0.8); }
.studioQuickTake--alt .studioChoiceChev { margin-left: auto; color: rgba(255,255,255,0.4); }

/* Library picker */
.studioPickList { display: flex; flex-direction: column; gap: 10px; margin-top: 16px; }
.studioPickRow {
  display: flex; align-items: center; gap: 13px; width: 100%; text-align: left; cursor: pointer;
  padding: 10px 12px; border-radius: 16px;
  border: 1px solid rgba(255,255,255,0.06); background: rgba(255,255,255,0.035);
  color: var(--text, #f5f6fb);
}
.studioPickRow:active { background: rgba(255,255,255,0.06); }
.studioPickArt {
  flex: 0 0 auto; width: 48px; height: 48px; border-radius: 11px; overflow: hidden;
  display: flex; align-items: center; justify-content: center;
  background: rgba(255,255,255,0.06); color: rgba(255,255,255,0.5); font-size: 18px;
}
.studioPickArt img { width: 100%; height: 100%; object-fit: cover; }
.studioPickBody { flex: 1 1 auto; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
.studioPickName { font-size: 15px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.studioPickTag {
  align-self: flex-start; font-size: 10px; font-weight: 700; letter-spacing: .04em;
  padding: 1px 7px; border-radius: 999px; color: rgba(35,213,171,0.95);
  background: rgba(35,213,171,0.12);
}

/* Voice-timing (latency) — bipolar slider, thumb sits at centre (0) */
.studioMixField--sync { display: flex; flex-direction: column; gap: 8px; }
.studioSyncVal { font-size: 13px; font-weight: 600; color: var(--brand, #7c5cff); }
.studioSyncSlider {
  -webkit-appearance: none; appearance: none; width: 100%; height: 6px; border-radius: 999px;
  background: linear-gradient(90deg, rgba(255,255,255,0.12), rgba(124,92,255,0.5) 50%, rgba(255,255,255,0.12));
  outline: none; margin: 2px 0;
}
.studioSyncSlider::-webkit-slider-thumb {
  -webkit-appearance: none; appearance: none; width: 22px; height: 22px; border-radius: 50%;
  background: #fff; border: 3px solid var(--brand, #7c5cff); cursor: pointer;
  box-shadow: 0 2px 8px rgba(0,0,0,0.4);
}
.studioSyncSlider::-moz-range-thumb {
  width: 22px; height: 22px; border-radius: 50%; background: #fff;
  border: 3px solid var(--brand, #7c5cff); cursor: pointer;
}
.studioSyncScale {
  display: flex; align-items: center; justify-content: space-between;
  font-size: 11px; color: rgba(255,255,255,0.45);
}
.studioSyncRec { color: rgba(35,213,171,0.9); font-weight: 600; }
.studioSyncHint { margin: 2px 0 0; font-size: 12px; line-height: 1.4; color: rgba(255,255,255,0.45); }

/* Review waveform scrubbing */
.studioWave--review { position: relative; cursor: pointer; touch-action: none; overflow: hidden; }
.studioWave--review .studioPeakBar { pointer-events: none; user-select: none; }
.studioWaveFill {
  position: absolute; left: 0; top: 0; bottom: 0; width: 0%; z-index: 2;
  background: linear-gradient(90deg, rgba(124,92,255,0.28), rgba(35,213,171,0.28));
  border-radius: 12px; pointer-events: none; transition: width 60ms linear;
}
.studioWave--review.is-scrubbing .studioWaveFill { transition: none; }
.studioWaveHandle {
  position: absolute; top: -3px; bottom: -3px; left: 0%; width: 3px; z-index: 3;
  border-radius: 3px;
  background: #fff; box-shadow: 0 0 8px rgba(124,92,255,0.7); transform: translateX(-50%);
  pointer-events: none;
}
.studioScrubHint, .studioSoonNoteCenter { text-align: center; font-size: 12px; color: rgba(255,255,255,0.4); margin: 6px 0 0; }

@media (prefers-reduced-motion: reduce) {
  .studioWaveFill { transition: none; }
}

