/* ---------- Edit Profile (creator workspace) ---------- */
.profileEditPage{
  position: relative;
  width: 100%;
  max-width: 640px;
  margin: 0 auto;
  padding: 4px max(18px, env(safe-area-inset-left, 0px), env(safe-area-inset-right, 0px)) 96px;
  box-sizing: border-box;
  display: flex;
  flex-direction: column;
  gap: 0;
  min-width: 0;
  animation: sectionFadeIn 260ms ease;
}
body[data-route="profile-edit"] .app{
  padding-left: 0;
  padding-right: 0;
}
body[data-route="profile-edit"] main.grid{
  background: #05070d;
}
.profileEditHead{
  display: grid;
  grid-template-columns: 44px 1fr 44px;
  align-items: center;
  gap: 8px;
  margin: 0 0 28px;
  padding: 2px 0 0;
}
.profileEditBack{
  grid-column: 1;
  grid-row: 1;
  justify-self: start;
  margin-left: -4px;
}
.profileEditTitle{
  grid-column: 1 / -1;
  grid-row: 1;
  margin: 0;
