/* Pro Singer — request / apply sheets */
.proSingerSheetCard{
  max-height: min(
    92vh,
    calc(100dvh - var(--feed-reply-keyboard-inset, 0px) - 12px - env(safe-area-inset-top, 0px)),
    720px
  );
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.03) 0%, transparent 18%),
    linear-gradient(180deg, var(--card), var(--bg));
}
.proSingerSheetCard .feedReplySheetTitle{
  font-size: 20px;
  font-weight: 750;
  letter-spacing: -0.03em;
}
.proSingerSheetCard .feedReplySheetSub{
  font-size: 13px;
  line-height: 1.4;
  color: rgba(236,240,252,0.52);
}
.proSingerSteps{
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
  overscroll-behavior: contain;
  padding: 0 18px 12px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}
.proSingerFoot{
  flex-shrink: 0;
  display: flex;
  gap: 10px;
  align-items: stretch;
  padding: 14px 18px calc(14px + env(safe-area-inset-bottom));
  border-top: 1px solid rgba(255,255,255,0.08);
  background: rgba(0,0,0,0.14);
}
.proSingerFoot--solo .proSingerBtn--primary{
  flex: 1;
  width: 100%;
}
.proSingerFoot--loading .proSingerBtn--primary{
  opacity: 0.55;
}
.proSingerBtn{
  appearance: none;
  border: 0;
  margin: 0;
  font: inherit;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  border-radius: 14px;
  min-height: 52px;
  padding: 0 20px;
  font-size: 16px;
  font-weight: 650;
  letter-spacing: -0.02em;
  transition: transform 120ms ease, opacity 120ms ease, background 160ms ease, border-color 160ms ease;
}
.proSingerBtn:active:not(:disabled){
  transform: scale(0.985);
}
.proSingerBtn:disabled{
  opacity: 0.42;
  cursor: not-allowed;
}
.proSingerBtn--primary{
  flex: 1;
  color: rgba(248,250,255,0.96);
  background: rgba(255,255,255,0.11);
  border: 1px solid rgba(255,255,255,0.14);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.07),
    0 10px 28px -16px rgba(0,0,0,0.65);
}
.proSingerBtn--primary:hover:not(:disabled){
  background: rgba(255,255,255,0.15);
  border-color: rgba(255,255,255,0.2);
}
.proSingerBtn--back{
  flex-shrink: 0;
  min-width: 72px;
  color: rgba(236,240,252,0.58);
  background: transparent;
  border: 1px solid rgba(255,255,255,0.08);
  font-weight: 600;
  font-size: 15px;
}
.proSingerBtn--back:hover:not(:disabled){
  color: rgba(248,250,255,0.88);
  border-color: rgba(255,255,255,0.14);
  background: rgba(255,255,255,0.04);
}
.proSingerLoading{
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 8px 0 4px;
}
.proSingerLoadingLine,
.proSingerLoadingBlock{
  border-radius: 12px;
  background: var(--skeleton-fill);
  border: 1px solid var(--skeleton-stroke);
  animation: hubSkelShimmer 1.15s ease-in-out infinite;
}
.proSingerLoadingLine{
  height: 14px;
  width: 72%;
}
.proSingerLoadingLine--wide{ width: 92%; height: 16px; }
.proSingerLoadingLine--short{ width: 48%; }
.proSingerLoadingBlock{
  height: 88px;
  width: 100%;
  border-radius: 14px;
}
.proSingerSheetCard .feedReplySheetHead{
  flex-shrink: 0;
}
.proSingerDots{
  display: flex;
  gap: 6px;
  justify-content: center;
  margin-top: 10px;
}
.proSingerDot{
  width: 6px;
  height: 6px;
  border-radius: 999px;
  background: rgba(255,255,255,0.16);
  transition: background 180ms ease, transform 180ms ease;
}
.proSingerDot.isActive{
  background: rgba(248,250,255,0.92);
  transform: scale(1.15);
}
.proSingerDot.isDone{ background: rgba(255,255,255,0.38); }
.proSingerLead{
  margin: 0;
  font-size: 0.88rem;
  line-height: 1.45;
  color: rgba(236,240,252,0.72);
}
.proSingerMuted{
  margin: 0;
  font-size: 0.82rem;
  line-height: 1.4;
  color: rgba(236,240,252,0.55);
}
.proSingerField{
  display: flex;
  flex-direction: column;
  gap: 6px;
  font-size: 0.82rem;
  color: rgba(236,240,252,0.72);
}
.proSingerField input,
.proSingerField select,
.proSingerField textarea{
  width: 100%;
  border-radius: 14px;
  border: 1px solid rgba(255,255,255,0.1);
  background: rgba(255,255,255,0.04);
  color: inherit;
  padding: 12px 14px;
  font: inherit;
  transition: border-color 160ms ease, box-shadow 160ms ease, background 160ms ease;
}
.proSingerField input:focus,
.proSingerField select:focus,
.proSingerField textarea:focus{
  outline: none;
  border-color: rgba(255,255,255,0.24);
  background: rgba(255,255,255,0.06);
  box-shadow: 0 0 0 3px rgba(255,255,255,0.05);
}
.proSingerSongCard{
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 10px;
  border-radius: 14px;
  border: 1px solid rgba(255,255,255,0.1);
  background: rgba(0,0,0,0.18);
}
.proSingerSongArt{
  width: 52px;
  height: 52px;
  border-radius: 10px;
  object-fit: cover;
}
.proSingerSongTitle{ font-weight: 700; font-size: 0.95rem; }
.proSingerSongSub{ font-size: 0.78rem; color: rgba(236,240,252,0.55); }
.proSingerPick{
  display: flex;
  gap: 12px;
  align-items: center;
  width: 100%;
  text-align: left;
  padding: 10px 12px;
  border-radius: 14px;
  border: 1px solid rgba(255,255,255,0.1);
  background: rgba(0,0,0,0.16);
  color: inherit;
}
.proSingerPick.isSelected{
  border-color: rgba(255,255,255,0.34);
  background: rgba(255,255,255,0.08);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.06);
}
.proSingerPickArt{
  width: 44px;
  height: 44px;
  border-radius: 999px;
  object-fit: cover;
}
.proSingerPickIco{
  width: 44px;
  height: 44px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  background: rgba(255,255,255,0.08);
  border: 1px solid rgba(255,255,255,0.1);
  font-size: 1.1rem;
  color: rgba(248,250,255,0.88);
}
.proSingerPickName{ display: block; font-weight: 700; font-size: 0.92rem; }
.proSingerPickMeta{ display: block; font-size: 0.78rem; color: rgba(236,240,252,0.58); }
.proSingerAddonNote{ font-size: 0.78rem; color: rgba(236,240,252,0.55); margin: 0; }
.proSingerPkgGrid{
  display: grid;
  gap: 10px;
}
.proSingerPkg{
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
  padding: 12px 14px;
  border-radius: 14px;
  border: 1px solid rgba(255,255,255,0.1);
  background: rgba(0,0,0,0.16);
  color: inherit;
  text-align: left;
}
.proSingerPkg.isSelected{
  border-color: rgba(255,255,255,0.34);
  background: rgba(255,255,255,0.08);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.06);
}
.proSingerPkg.isDisabled{ opacity: 0.45; }
.proSingerPkgPrice{ font-size: 1.15rem; font-weight: 800; color: rgba(248,250,255,0.94); }
.proSingerPkgLabel{ font-weight: 700; }
.proSingerPkgBlurb{ font-size: 0.78rem; color: rgba(236,240,252,0.58); }
.proSingerReviewCard{
  border-radius: 14px;
  border: 1px solid rgba(255,255,255,0.1);
  background: rgba(0,0,0,0.18);
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.proSingerReviewRow{
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-size: 0.86rem;
  color: rgba(236,240,252,0.72);
}
.proSingerReviewTotal{
  padding-top: 8px;
  border-top: 1px solid rgba(255,255,255,0.08);
  font-size: 0.95rem;
}
.discoverTrackSheetRow--proSinger{
  color: rgba(248,250,255,0.88);
}
.proSingerRequestsList{
  flex: 1;
  overflow-y: auto;
  padding: 0 18px 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.proSingerReqRow{
  border-radius: 14px;
  border: 1px solid rgba(255,255,255,0.1);
  background: rgba(0,0,0,0.16);
  padding: 12px 14px;
}
.proSingerReqHead{
  display: flex;
  justify-content: space-between;
  gap: 10px;
  align-items: flex-start;
}
.proSingerReqBadge{
  font-size: 0.72rem;
  font-weight: 700;
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(124,92,255,0.18);
  color: rgba(196,181,253,0.95);
  white-space: nowrap;
}
.proSingerReqMeta,
.proSingerReqDate{
  margin: 6px 0 0;
  font-size: 0.78rem;
  color: rgba(236,240,252,0.58);
}
